/// Writes four words.
///
/// # Safety
/// `actor` must be writable through `+0x324`.
///
/// # Confidence
/// high - four direct copies.
pub unsafe fn wm_set_scale_constants(actor: usize) {
    platform::write_u32(actor + 0x320, platform::read_u32(SCALE_CONSTANTS));
    platform::write_u32(actor + 0x324, platform::read_u32(SCALE_CONSTANTS + 4));
    platform::write_u32(actor + 0x318, platform::read_u32(SCALE_CONSTANTS + 8));
    platform::write_u32(actor + 0x31C, platform::read_u32(SCALE_CONSTANTS + 12));
}

/// Points the actor's two animation tables at the per-player bank.
///
/// Reads `0x802F57D0[player] & 0xFF`, multiplies by `0xF0`, and stores
/// `0x803768B0 + offset` at `+0x1060` and `0x80376928 + offset` at `+0x1064`.
///
/// # Original
/// - Ghidra: `FUN_80146700` at `0x80146700` (56 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80146700_FUN_80146700.c`
///
/// # Arguments
/// * `actor` - Wm actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x1060` and `+0x1064`.
///
/// # Safety
/// `actor + 0x1090` must hold a player index in `0..=3`.
///
/// # Confidence
/// high - the table lookup and stride are explicit.
pub unsafe fn wm_set_anim_table_pointers(actor: usize) {
    let player = platform::read_u32(actor + PLAYER_INDEX) as usize;
    let offset = (platform::read_u32(ANIM_TABLE_INDEX + player * 4) & 0xFF) as usize * 0xF0;
    platform::write_u32(actor + 0x1060, (ANIM_TABLE_A + offset) as u32);
    platform::write_u32(actor + 0x1064, (ANIM_TABLE_B + offset) as u32);
}

/// Points `+0x1068` at the normal or special motion table.
