/// Returns the mode-dependent resource id for effect ids `0x4E..=0x53`.
///
/// The result is selected from a six-row table by the mode byte at
/// [`EFFECT_MODE_BYTE`]. Rows `0x51..=0x53` only define modes `0..=6`; mode `7`
/// and all other ids return `0`, which is preserved by the trailing zero entry.
///
/// # Original
/// - Ghidra: `FUN_80105C10` at `0x80105C10` (720 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80105c10_FUN_80105c10.c`
///
/// # Arguments
/// * `_base` - unused by the original.
/// * `tag` - effect id in `0x4E..=0x53`.
///
/// # Returns
/// Resource id, or `0`.
///
/// # Side effects
/// Reads the SDA mode byte.
///
/// # Safety
/// [`EFFECT_MODE_BYTE`] must be readable.
///
/// # Confidence
/// high - every table cell is a literal return in the evidence.
pub unsafe fn wm_effect_mode_resource_id(_base: usize, tag: u32) -> u32 {
    let mode = platform::read_u8(EFFECT_MODE_BYTE);
    let row: [u32; 8] = match tag {
        0x4E => [0x454, 0x46A, 0x47E, 0x490, 0x4AC, 0x4BF, 0x4D4, 0x4E0],
        0x4F => [0x455, 0x46B, 0x47F, 0x491, 0x4AD, 0x4C0, 0x4D5, 0x4E1],
        0x50 => [0x456, 0x46C, 0x480, 0x492, 0x4AE, 0x4C1, 0x4D6, 0x4E2],
        0x51 => [0x457, 0x46D, 0x481, 0x493, 0x4AF, 0x4C2, 0x4D7, 0],
        0x52 => [0x458, 0x46E, 0x482, 0x494, 0x4B0, 0x4C3, 0x4D8, 0],
        0x53 => [0x459, 0x46F, 0x483, 0x495, 0x4B1, 0x4C4, 0x4D9, 0],
        _ => return 0,
    };
    match row.get(mode as usize) {
        Some(value) => *value,
        None => 0,
    }
}

/// Builds a record transform and dispatches one small-pool record.
///
/// If `record+0x28` or `record+0x2C` is zero, the record's transform at
/// `+0x34..+0x3C` is copied from the pointer at `+0x30` (when non-null);
/// otherwise `0x800FC4F0` fills a local three-word transform. In both cases
/// `0x8006A5E0` projects the transform into a two-float buffer.
///
/// The effect id comes from [`wm_effect_resource_id`] and the dispatch kind
/// from [`wm_effect_kind`]. Kind `0` writes the channel at `object+0xB0`; kinds
/// `2`, `3` and `4` call the renderer with the projected buffer; kind `5`
/// forwards to `0x80195390`.
///
/// # Original
/// - Ghidra: `FUN_80104CC0` at `0x80104CC0` (748 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80104cc0_FUN_80104cc0.c`
///
/// # Arguments
/// * `base` - effect pool base.
/// * `index` - signed record index; the record is `base + index * 0x34`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `record+0x34..+0x3C`, may write `object+0xB0`, and may call vtable
/// slots `+0x28`, `+0x2C`, `+0x30`, `+0x34`.
///
/// # Safety
/// The record and every referenced object must be live. `+0x30` and `+0x40`
/// must be null or readable pointers.
///
/// # Confidence
/// medium - the body and call order are explicit, but the local projection
/// buffers are sized from the callee's write pattern (`0x800FC4F0` writes three
/// words, `0x8006A5E0` reads three and writes two).
pub unsafe fn wm_effect_record_dispatch(base: usize, index: i32) {
    let record = (base as isize + (index as isize) * EFFECT_POOL_STRIDE as isize) as usize;
    // local_28 / local_24: two floats passed by pointer to the renderers.
    let mut projected = crate::platform::GuestLocal::new( [0u32; 2]);
    if platform::read_u32(record + 0x28) == 0 || platform::read_u32(record + 0x2C) == 0 {
        let src = platform::read_u32(record + 0x30) as usize;
        if src != 0 {
            platform::write_u32(record + 0x34, platform::read_u32(src));
            platform::write_u32(record + 0x38, platform::read_u32(src + 4));
            platform::write_u32(record + 0x3C, platform::read_u32(src + 8));
            platform::call2(
                FUN_8006A5E0,
                projected.as_mut_ptr() as u32,
                (record + 0x34) as u32,
            );
        }
    } else {
        let mut transform = crate::platform::GuestLocal::new( [0u32; 3]);
        platform::call1(FUN_800FC4F0, transform.as_mut_ptr() as u32);
        platform::write_u32(record + 0x34, transform[0]);
        platform::write_u32(record + 0x38, transform[1]);
        platform::write_u32(record + 0x3C, transform[2]);
        platform::call2(
            FUN_8006A5E0,
            projected.as_mut_ptr() as u32,
            (record + 0x34) as u32,
        );
    }
    let tag = platform::read_u32(record + 0x24);
    let id = wm_effect_resource_id(base, tag);
    if id == 0 {
        return;
    }
    let kind = wm_effect_kind(base, tag);
    let vec_ptr = projected.as_ptr() as u32;
    if kind == 0 {
        let short_ptr = platform::read_u32(record + 0x40) as usize;
        if tag == 0x0C {
            let object = platform::read_u32(base + 0x20) as usize;
            let channel = wm_effect_channel(base, platform::read_u32(record + 0x4C));
            platform::write_u32(object + 0xB0, channel);
            let vtable = platform::read_u32(object) as usize;
            let entry = platform::read_u32(vtable + 0x34) as usize;
            platform::call4(
                entry,
                object as u32,
                id,
                short_arg(short_ptr),
                0,
            );
        } else {
            let slot = platform::read_u32(record + 0x48) as usize;
            let object = platform::read_u32(base + slot * 4 + 0x10) as usize;
            let channel = wm_effect_channel(base, platform::read_u32(record + 0x4C));
            platform::write_u32(object + 0xB0, channel);
            let vtable = platform::read_u32(object) as usize;
            if short_ptr == 0 {
                let entry = platform::read_u32(vtable + 0x28) as usize;
                platform::call3(entry, object as u32, id, 0);
            } else {
                let entry = platform::read_u32(vtable + 0x34) as usize;
                platform::call4(
                    entry,
                    object as u32,
                    id,
                    short_arg(short_ptr),
                    0,
                );
            }
        }
    } else if kind == 2 {
        let object = platform::read_u32(base + 0x0C) as usize;
        let vtable = platform::read_u32(object) as usize;
        let short_ptr = platform::read_u32(record + 0x40) as usize;
        if short_ptr == 0 {
            let entry = platform::read_u32(vtable + 0x2C) as usize;
            platform::call5(
                entry,
                object as u32,
                id,
                1,
                vec_ptr,
                platform::read_u32(record + 0x44),
            );
        } else {
            let entry = platform::read_u32(vtable + 0x30) as usize;
            platform::call6(
                entry,
                object as u32,
                id,
                1,
                vec_ptr,
                short_arg(short_ptr),
                platform::read_u32(record + 0x44),
            );
        }
    } else if kind == 3 {
        let object = platform::read_u32(base + 0x04) as usize;
        let vtable = platform::read_u32(object) as usize;
        let short_ptr = platform::read_u32(record + 0x40) as usize;
        if short_ptr == 0 {
            let entry = platform::read_u32(vtable + 0x28) as usize;
            platform::call3(
                entry,
                object as u32,
                id,
                platform::read_u32(record + 0x44),
            );
        } else {
            let entry = platform::read_u32(vtable + 0x34) as usize;
            platform::call4(
                entry,
                object as u32,
                id,
                short_arg(short_ptr),
                platform::read_u32(record + 0x44),
            );
        }
    } else if kind == 4 {
        let object = platform::read_u32(base + 0x08) as usize;
        let vtable = platform::read_u32(object) as usize;
        let entry = platform::read_u32(vtable + 0x2C) as usize;
        platform::call5(
            entry,
            object as u32,
            id,
            platform::read_u32(record + 0x54),
            vec_ptr,
            platform::read_u32(record + 0x44),
        );
    } else if kind == 5 {
        platform::call3(
            FUN_80195390,
            platform::read_u32(EFFECT_RENDER_MANAGER),
            id,
            1,
        );
    }
}

/// Sets one record's channel and plays its effect id.
///
/// The voice id comes from [`wm_effect_voice_id`]; `0x47` means "no voice" and
/// leaves the record untouched. Otherwise the channel from
/// [`wm_effect_channel`] is stored at `object+0xB0` and `0x8019A970` is called
/// with `(object, voice, 0)`.
///
/// # Original
/// - Ghidra: `FUN_80104FD0` at `0x80104FD0` (132 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80104fd0_FUN_80104fd0.c`
///
/// # Arguments
/// * `base` - effect pool base.
/// * `tag` - effect id.
/// * `index` - player/render index; the object is at `base + index * 4 + 0x10`.
/// * `action` - value passed to [`wm_effect_channel`].
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// May write `object+0xB0` and start a sound.
///
/// # Safety
/// The selected object must be live.
///
/// # Confidence
/// high - raw instructions at `0x80104FD0..0x80105014` confirm the four
/// arguments and the `0x47` guard.
pub unsafe fn wm_effect_record_play(base: usize, tag: u32, index: i32, action: u32) {
    let voice = wm_effect_voice_id(base, tag);
    if voice != 0x47 {
        let channel = wm_effect_channel(base, action);
        let object = platform::read_u32(base + (index as usize) * 4 + 0x10) as usize;
        platform::write_u32(object + 0xB0, channel);
        platform::call3(FUN_8019A970, object as u32, voice, 0);
    }
}

/// Plays an effect with an explicit position, with two id overrides.
///
/// The base id comes from [`wm_effect_resource_id`] and the kind from
/// [`wm_effect_kind`]. Kind `0` calls the player vtable slot `+0x24`; ids `1`
/// and `8` with specific actions substitute ids `2`/`3` and `0xD`. Kind `1`
/// calls `0x8019A6D0(position, object, id, 0)`, with id `0x18` substituted when
/// `action == 5`.
///
/// # Original
/// - Ghidra: `FUN_80105060` at `0x80105060` (336 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80105060_FUN_80105060.c`
///
/// # Arguments
/// * `base` - effect pool base.
/// * `tag` - effect id.
/// * `index` - player/render index; the object is at `base + index * 4 + 0x10`.
/// * `action` - action/state selector used by the overrides.
/// * `position` - `f64` passed in `f1` to `0x8019A6D0`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `object+0xB0` and may call a vtable slot or `0x8019A6D0`.
///
/// # Safety
/// The selected object must be live and the float ABI must match.
///
/// # Confidence
/// medium - the branch structure and stores are explicit; the `f64` argument
/// signature comes from the Ghidra prototype and the EABI.
pub unsafe fn wm_effect_record_play_position(
    base: usize,
    tag: u32,
    index: i32,
    action: u32,
    position: f64,
) {
    let mut id = wm_effect_resource_id(base, tag);
    if id == 0 {
        return;
    }
    let channel = wm_effect_channel(base, action);
    let object = platform::read_u32(base + (index as usize) * 4 + 0x10) as usize;
    platform::write_u32(object + 0xB0, channel);
    let kind = wm_effect_kind(base, tag);
    if kind == 0 {
        if tag == 1 {
            if action == 0 {
                id = wm_effect_resource_id(base, 2);
            } else if action == 3 {
                id = wm_effect_resource_id(base, 3);
            }
        }
        if tag == 8 && action == 5 {
            id = wm_effect_resource_id(base, 0x0D);
        }
        let vtable = platform::read_u32(object) as usize;
        let entry = platform::read_u32(vtable + 0x24) as usize;
        platform::call3(entry, object as u32, id, 0);
    } else if kind == 1 {
        if action == 5 {
            let override_id = wm_effect_resource_id(base, 0x18);
            call_f64_u32_u32_u32(
                FUN_8019A6D0,
                position,
                object as u32,
                override_id,
                0,
            );
        } else {
            call_f64_u32_u32_u32(FUN_8019A6D0, position, object as u32, id, 0);
        }
    }
}

/// Builds a transform on the stack and submits it.
///
/// Calls `0x800FC4F0(buffer, p3, p4)` to fill `0x1C` bytes, then forwards the
/// buffer to [`wm_effect_record_submit`] with `p5`.
///
/// # Original
/// - Ghidra: `FUN_801051D0` at `0x801051D0` (100 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801051d0_FUN_801051d0.c`
///
/// # Arguments
/// * `base` - effect pool base.
/// * `tag` - effect id.
/// * `p3`, `p4` - inputs to `0x800FC4F0`.
/// * `p5` - forwarded action argument.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Fills a 0x1C-byte stack buffer and may dispatch an effect.
///
/// # Safety
/// `0x800FC4F0` must accept the two inputs and write 0x1C bytes.
///
/// # Confidence
/// high - the buffer size and call order are explicit.
pub unsafe fn wm_effect_record_play_transform(
    base: usize,
    tag: u32,
    p3: u32,
    p4: u32,
    p5: u32,
) {
    let mut transform = crate::platform::GuestLocal::new( [0u32; 7]);
    platform::call3(
        FUN_800FC4F0,
        transform.as_mut_ptr() as u32,
        p3,
        p4,
    );
    wm_effect_record_submit(base, tag, transform.as_ptr() as usize, p5);
}

/// Submits one record's transform to the renderer selected by its kind.
///
/// Kind `2` converts the transform with `0x8006A5E0` then calls vtable slot
/// `+0x20`; kind `3` calls slot `+0x24` directly; kind `4` converts the
/// transform and calls slot `+0x20` on the `base+8` object; kind `5` calls
/// `0x80195370(manager, id, action)`; kind `6` calls
/// `0x801954A0(manager, id)`.
///
/// # Original
/// - Ghidra: `FUN_80105240` at `0x80105240` (292 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80105240_FUN_80105240.c`
///
/// # Arguments
/// * `base` - effect pool base.
/// * `tag` - effect id.
/// * `transform` - pointer to the 0x1C-byte transform.
/// * `action` - extra action/state word.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// May call a vtable slot or one of two manager helpers.
///
/// # Safety
/// `transform` must be readable and every referenced object live.
///
/// # Confidence
/// medium - the call sequence is explicit; the local two-float projection is
/// sized from `0x8006A5E0`'s write pattern.
pub unsafe fn wm_effect_record_submit(base: usize, tag: u32, transform: usize, action: u32) {
    let id = wm_effect_resource_id(base, tag);
    if id == 0 {
        return;
    }
    let kind = wm_effect_kind(base, tag);
    if kind == 2 {
        let mut projected = crate::platform::GuestLocal::new( [0u32; 2]);
        platform::call2(FUN_8006A5E0, projected.as_mut_ptr() as u32, transform as u32);
        let object = platform::read_u32(base + 0x0C) as usize;
        let vtable = platform::read_u32(object) as usize;
        let entry = platform::read_u32(vtable + 0x20) as usize;
        platform::call4(
            entry,
            object as u32,
            id,
            projected.as_ptr() as u32,
            action,
        );
    } else if kind == 3 {
        let object = platform::read_u32(base + 0x04) as usize;
        let vtable = platform::read_u32(object) as usize;
        let entry = platform::read_u32(vtable + 0x24) as usize;
        platform::call3(entry, object as u32, id, action);
    } else if kind == 4 {
        let mut projected = crate::platform::GuestLocal::new( [0u32; 2]);
        platform::call2(FUN_8006A5E0, projected.as_mut_ptr() as u32, transform as u32);
        let object = platform::read_u32(base + 0x08) as usize;
        let vtable = platform::read_u32(object) as usize;
        let entry = platform::read_u32(vtable + 0x20) as usize;
        platform::call4(
            entry,
            object as u32,
            id,
            projected.as_ptr() as u32,
            action,
        );
    } else if kind == 5 {
        platform::call3(
            FUN_80195370,
            platform::read_u32(EFFECT_RENDER_MANAGER),
            id,
            action,
        );
    } else if kind == 6 {
        platform::call2(
            FUN_801954A0,
            platform::read_u32(EFFECT_RENDER_MANAGER),
            id,
        );
    }
}

/// Reports whether an effect's resource is absent.
///
/// Calls [`wm_effect_resource_id`]. A zero id returns `false`. Otherwise it
/// calls `0x80196600(manager, id)` and returns `true` exactly when the result
/// is zero (`countLeadingZeros(result) >> 5`).
///
/// # Original
/// - Ghidra: `FUN_80105EE0` at `0x80105EE0` (68 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80105ee0_FUN_80105ee0.c`
///
/// # Arguments
/// * `base` - effect pool base. Ghidra declares the function with no
///   parameters because `r3`/`r4` pass straight through to
///   [`wm_effect_resource_id`]; the two parameters are reconstructed here.
/// * `tag` - effect id.
///
/// # Returns
/// `true` when the resource lookup returns zero, `false` otherwise.
///
/// # Side effects
/// Reads the SDA manager pointer and calls `0x80196600`.
///
/// # Safety
/// The manager pointer must be readable.
///
/// # Confidence
/// medium - the body is explicit; the parameter list is inferred from the
/// register pass-through at `0x80105EE0..0x80105EF0`.
pub unsafe fn wm_effect_resource_missing(base: usize, tag: u32) -> bool {
    let id = wm_effect_resource_id(base, tag);
    if id == 0 {
        return false;
    }
    let manager = platform::read_u32(EFFECT_RENDER_MANAGER);
    let value = platform::call2(FUN_80196600, manager, id);
    value.leading_zeros() == 32
}

