/// Calls virtual slot `slot` of `object` with two integer arguments.
///
/// # Safety
/// `object` must be live and the slot must accept `(object, a, b)`.
#[inline]
unsafe fn vcall2(object: usize, slot: usize, a: u32, b: u32) -> u32 {
    let vtable = platform::read_u32(object) as usize;
    let entry = platform::read_u32(vtable + slot) as usize;
    platform::call3(entry, object as u32, a, b)
}

/// Calls virtual slot `slot` of `object` with one `f64` argument.
///
/// On the 32-bit PowerPC EABI the object pointer is in `r3` and the double is
/// in `f1`.
///
/// # Safety
/// `object` must be live and the slot must accept `(object, f64)`.
#[inline]
unsafe fn vcall_f64(object: usize, slot: usize, a: f64) -> u32 {
    let vtable = platform::read_u32(object) as usize;
    let entry = platform::read_u32(vtable + slot) as usize;
    let f = crate::platform::guest_fn!(entry, fn(usize, f64) -> u32);
    f(object, a)
}

/// Calls virtual slot `slot` of `object` with two doubles and one integer.
///
/// # Safety
/// `object` must be live and the slot must accept `(object, f64, f64, u32)`.
#[inline]
unsafe fn vcall_f64_f64_u32(object: usize, slot: usize, a: f64, b: f64, c: u32) -> u32 {
    let vtable = platform::read_u32(object) as usize;
    let entry = platform::read_u32(vtable + slot) as usize;
    let f = crate::platform::guest_fn!(entry, fn(usize, f64, f64, u32) -> u32);
    f(object, a, b, c)
}

