///
/// # Side effects
/// Same as [`wm_map_object_free`].
///
/// # Safety
/// `object` must be null or a live map child.
///
/// # Confidence
/// high - the evidence body is identical to `0x8014A260`.
pub unsafe fn wm_map_object_free_b(object: usize, free: i32) -> usize {
    if object != 0 {
        platform::call2(FUN_8015F800, object as u32, 0);
        if free > 0 {
            platform::call1(FUN_802B9280, object as u32);
        }
    }
    object
}

/// Walks up to five `+0x30` child links and returns the first node whose child
/// has a non-zero virtual slot `+0x0C`.
///
/// The original checks the child returned by `+0x30` *before* descending; when
/// all five checks return zero it recurses on the sixth link.
///
/// # Original
/// - Ghidra: `FUN_8014A4F0` at `0x8014A4F0` (224 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8014a4f0_FUN_8014a4f0.c`
///
/// # Arguments
/// * `node` - first node in the child chain.
///
/// # Returns
/// The parent node whose child passed the slot test, or the recursive result.
///
/// # Side effects
/// Calls virtual slot `+0x0C` up to five times per recursion level.
///
/// # Safety
/// Every reachable `+0x30` link must point at a live object whose vtable has a
/// slot at `+0x0C`.
///
/// # Confidence
/// high - the unrolled five checks and the tail recursion are explicit.
pub unsafe fn wm_map_child_chain(node: usize) -> usize {
    let mut current = node;
    let mut checked = 0;
    while checked < 5 {
        let child = platform::read_u32(current + 0x30) as usize;
        if vcall0(child, 0x0C) != 0 {
            return current;
        }
        current = child;
        checked += 1;
    }
    wm_map_child_chain(platform::read_u32(current + 0x30) as usize)
}

/// Compares a map object's name with a supplied name after the last `:`.
///
/// `0x802E1C40(text, ':')` is the `strrchr`-shaped search; both sides skip the
/// separator when it is present, then `0x802E1AB4` compares them.
///
/// # Original
/// - Ghidra: `FUN_8014A5D0` at `0x8014A5D0` (136 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8014a5d0_FUN_8014a5d0.c`
///
/// # Arguments
/// * `object` - map object whose virtual slot `+0x20` returns its name.
/// * `name` - candidate NUL-terminated name.
///
/// # Returns
/// `true` when the two suffixes compare equal.
///
/// # Side effects
/// Two name scans and one comparison; no writes.
///
/// # Safety
/// `object` must be live and both names must be NUL-terminated.
///
/// # Confidence
/// high - both searches and the comparison are explicit.
pub unsafe fn wm_map_object_name_matches(object: usize, name: usize) -> bool {
    let mut candidate = platform::call2(FUN_802E1C40, name as u32, 0x3A);
    if candidate != 0 {
        candidate = candidate.wrapping_add(1);
    }
    let own = vcall0(object, 0x20);
    let own_suffix = platform::call2(FUN_802E1C40, own, 0x3A);
    platform::call2(FUN_802E1AB4, own_suffix.wrapping_add(1), candidate) == 0
}

/// Constructs the `0xD70`-byte WorldMap map object.
