/// Runs the atiti-smoke action and its three sub-states.
///
/// State `0` initialises the effect, sets `+0x145C = 0x50`, calls the actor's
/// `+0x434`/`+0x428`/controller slots, and seeds the transform fields. State `1`
/// advances `0x8013D600` and moves to state `2` once the height/floor test
/// succeeds. State `2` keeps calling `0x8013D600`. While `+0x1458` is non-zero,
/// `Wm_mr_atitismoke` is spawned at `+0x6F8`; `0x80055810` closes the update.
///
/// # Original
/// - Ghidra: `FUN_8013E170` at `0x8013E170` (528 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8013e170_FUN_8013e170.c`
///
/// # Arguments
/// * `actor` - WorldMap actor running the atiti action.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// State writes, several virtual calls, an optional effect, and the sound/state
/// updates performed by the callees.
///
/// # Safety
/// `actor`, its `+0x2A64` controller, and the scene pointer at
/// `r13-0x5880` must be live.
///
/// # Confidence
/// high - the three states and all call arguments are explicit; the BSS spin
/// angles are read at runtime.
pub unsafe fn wm_atitismoke_effect(actor: usize) {
    let state = platform::read_u32(actor + 0x1458);
    if state == 0 {
        if platform::read_u32(actor + 0x145C) == 0 {
            platform::call1(
                FUN_800607D0,
                platform::read_u8(actor + 0x38D) as i32 as u32,
            );
            platform::write_u32(actor + 0x145C, 0x50);
            vcall60_2(actor, 0x434, 0x2D, 0);
            platform::call3(FUN_80057E70, actor as u32, 0x13D, 0);
            vcall60_f64(actor, 0x428, read_f32(R2_5724_5000) as f64);
            vcall_f64_f64_f64_u32(
                platform::read_u32(actor + 0x2A64) as usize,
                0x5C,
                read_f32(G_80371198) as f64,
                read_f32(G_8037119C) as f64,
                read_f32(R2_5928_ZERO) as f64,
                0x51,
            );
            let zero = platform::read_u32(R2_5928_ZERO);
            platform::write_u32(actor + 0xE8, zero);
            platform::write_u32(actor + 0xEC, platform::read_u32(R2_5720_3_25));
            platform::write_u32(actor + 0xF0, zero);
            platform::write_u32(actor + 0x118, platform::read_u32(R2_781C_NEG4));
            platform::write_u32(actor + 0x114, platform::read_u32(R2_571C_NEG0_125));
            let angle = vcall60_1(actor, 0x444, platform::read_u8(actor + 0x348) as u32) as u16;
            platform::write_u16(actor + 0x102, angle);
            platform::write_u32(actor + 0x1458, 1);
            platform::call1(FUN_8013D9F0, actor as u32);
        }
    } else if state == 1 {
        platform::call1(FUN_8013D600, actor as u32);
        if platform::read_u32(actor + 0x1554) == 0 {
            let scene = platform::read_u32(SDA_5880_PTR) as usize;
            let floor = read_f32(scene + 0x3C) - read_f32(scene + 0x44);
            let height = read_f32(actor + 0xB0)
                + read_f32(actor + 0x324)
                + read_f32(actor + 0x31C);
            if height < floor - read_f32(R2_57AC_24) {
                platform::call1(FUN_8013D670, actor as u32);
                platform::write_u32(actor + 0x1458, 2);
            }
        } else if platform::read_u32(actor + 0x145C) == 0 {
            platform::call1(FUN_8013D670, actor as u32);
            platform::write_u32(actor + 0x1458, 2);
        }
    } else if state == 2 {
        platform::call1(FUN_8013D600, actor as u32);
    }
    if platform::read_u32(actor + 0x1458) != 0 {
        let mut rotation = platform::read_u32(R2_58FC_ONE);
        if platform::read_u32(actor + 0x1090) == 3 {
            rotation = platform::read_u32(R2_5838_0_6);
        }
        let color = crate::platform::GuestLocal::new( [rotation, rotation, rotation]);
        platform::call7(
            FUN_8008FBA0,
            platform::read_u8(actor + 0x38D) as i32 as u32,
            (actor + 0x6F8) as u32,
            WM_NAME_ATITISMOKE as u32,
            0,
            (actor + 0xAC) as u32,
            0,
            color.as_ptr() as u32,
        );
    }
    platform::call1(FUN_80055810, actor as u32);
}

