/// code reads only the first float of the record. The file image is zero, so
/// the table is filled during start-up and must be read at runtime.
const G_80325364: usize = 0x8032_5364;
/// `0x80354E50`: four player-presence words, one per controller slot.
const G_80354E50: usize = 0x8035_4E50;
/// `0x80354E60`: four player-slot indices into [`G_80354E90`].
const G_80354E60: usize = 0x8035_4E60;
/// `0x80354E90`: argument words selected by [`G_80354E60`].
const G_80354E90: usize = 0x8035_4E90;
/// `r13 - 0x59EC` (absolute `0x80429C94`): global player object; `+0x84` is
/// the assigned controller slot (`-1` when no player owns it).
const SDA_59EC_PTR: usize = SDA_BASE - 0x59EC;
/// `r13 - 0x5988` (absolute `0x80429CF8`): byte of per-player update flags.
const SDA_5988_BYTE: usize = SDA_BASE - 0x5988;
const FUN_802BF3D0: usize = 0x802B_F3D0;
const FUN_802BF540: usize = 0x802B_F540;
const FUN_802BF650: usize = 0x802B_F650;
const FUN_801C9940: usize = 0x801C_9940;
const FUN_8022C9C0: usize = 0x8022_C9C0;
const FUN_801C5860: usize = 0x801C_5860;
const FUN_802BED10: usize = 0x802B_ED10;
const FUN_801C8E70: usize = 0x801C_8E70;
const FUN_80057650: usize = 0x8005_7650;
const FUN_8004D210: usize = 0x8004_D210;
const FUN_8004CFD0: usize = 0x8004_CFD0;
const FUN_8004D040: usize = 0x8004_D040;
const FUN_80138E60: usize = 0x8013_8E60;
const FUN_80102260: usize = 0x8010_2260;
const FUN_8005F900: usize = 0x8005_F900;
const FUN_8005FA60: usize = 0x8005_FA60;
const FUN_8004E050: usize = 0x8004_E050;
