/// Calls a PowerPC function `(f64, u32) -> f32`.
///
/// `0x80082240` is declared `double ...(double, int)` by Ghidra, but its body
/// returns a promoted `float`; the value therefore arrives in `f1` as `f32`.
///
/// # Safety
/// `addr` must accept a double in `f1` and a word in `r3`, and return a float.
unsafe fn call_f64_u32_f32(addr: usize, a: f64, b: u32) -> f32 {
    let f = crate::platform::guest_fn!(addr, fn(f64, u32) -> f32);
    f(a, b)
}

/// Starts the map player's slide/skid action.
///
/// Cancels eight action bits, copies the surface byte `+0x348` into `+0x27CC`,
/// zeroes `+0xF4`, seeds the action timer `+0x14A8` with `0x1E`, sends event
/// `4` to the `+0xEA4` sub-object and refreshes the angle halfword `+0x102`
/// through virtual slot `+0x444`. The horizontal speed `+0x10C` becomes
/// `-1.0 * side_table[+0x348]`, and the four-word record
/// `{0x803089B0, 2.85, 0, 1}` is handed to `0x80127FC0`. Finally state `0x15E`
/// is requested.
///
/// # Original
/// - Ghidra: `FUN_80129A00` at `0x80129A00` (292 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80129a00_FUN_80129a00.c`
///
/// # Arguments
/// * `actor` - WorldMap player actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Eight action-bit updates, six field writes, two sub-object calls, one
/// virtual call and one state request.
///
/// # Safety
/// `actor` must be live, and `+0x348` must index the eight-entry side table at
/// `0x8042B840`.
///
/// # Confidence
/// medium - every call, store and bit id is explicit; the "slide" role is
/// inferred from the speed and surface fields shared with the two siblings.
pub unsafe fn wm_slide_begin(actor: usize) {
    platform::call2(FUN_80056C70, actor as u32, 0x9B);
    platform::call2(FUN_80056C70, actor as u32, 0x9C);
    platform::call2(FUN_80056C70, actor as u32, 0x9D);
    platform::call2(FUN_80056C70, actor as u32, 0x9E);
    platform::call2(FUN_80056C70, actor as u32, 0x10);
    platform::call2(FUN_80056C70, actor as u32, 0x97);
    platform::call2(FUN_80056C70, actor as u32, 10);
    platform::call2(FUN_80056C70, actor as u32, 0xA1);
    platform::write_u8(actor + 0x27CC, platform::read_u8(actor + 0x348));
    write_f32(actor + 0xF4, 0.0);
    platform::write_u32(actor + 0x14A8, 0x1E);
    platform::call2(FUN_8005E3B0, (actor + 0xEA4) as u32, 4);
    let angle = vcall60_1(actor, 0x444, platform::read_u8(actor + 0x348) as u32);
    platform::write_u16(actor + 0x102, angle as u16);
    let side = platform::read_u8(actor + 0x348) as usize;
    write_f32(
        actor + 0x10C,
        read_f32(R2_58BC_NEG1) * read_f32(G_SIDE_TABLE_8042B840 + side * 4),
    );
    // The original fills the four-word record in the order +4, +0, +8, +0xC.
    let mut record = crate::platform::GuestLocal::new( [0u32; 4]);
    record[1] = platform::read_u32(R2_58B8_2_85);
    record[0] = G_803089B0 as u32;
    record[2] = 0;
    record[3] = 1;
    platform::call2(FUN_80127FC0, actor as u32, record.as_ptr() as u32);
    platform::call3(FUN_80057E70, actor as u32, 0x15E, 0);
}

