/// # Original
/// - Ghidra: `FUN_8013D010` at `0x8013D010` (76 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8013d010_FUN_8013d010.c`
///
/// # Arguments
/// * `actor` - WorldMap player actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One or two `0x800D8510` calls.
///
/// # Safety
/// `actor` must be live; a non-zero selection must own a sound object at
/// `+0x388`.
///
/// # Confidence
/// high - both calls and the null test are explicit.
pub unsafe fn wm_landing_sound_stop(actor: usize) {
    let sound_id = read_i16(actor + 0x17CE) as i32 as u32;
    let selected = wm_find_selected_actor(actor);
    if selected != 0 {
        platform::call2(
            FUN_800D8510,
            platform::read_u32(selected + 0x388),
            sound_id,
        );
    }
    platform::call2(
        FUN_800D8510,
        platform::read_u32(actor + 0x388),
        sound_id,
    );
}

