/// Runs the recovery half of the landing.
///
/// Cancels bit `0xBB`, writes `0xFF` to `+0x154C`, posts the `0x80375C2C`
/// event with argument `1`, plays controller sound `0x85`, clears `+0x102`,
/// calls slot `+0x428` with `2800.0` (or `-2000.0` when `+0x38F` is set), sets
/// `+0x1074 = 0x23`, runs `0x8013E850`, and finally writes state `2` when
/// `0x8005D090(global_player, player_index)` returns zero, otherwise state `0`.
///
/// # Original
/// - Ghidra: `FUN_8013E920` at `0x8013E920` (264 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8013e920_FUN_8013e920.c`
///
/// # Arguments
/// * `actor` - WorldMap player actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Three virtual calls, three external calls, four field writes and the
/// two-way state choice.
///
/// # Safety
/// `actor` must be live; the global player pointer at `r13-0x59EC` must be
/// readable.
///
/// # Confidence
/// medium - the sound parameters are BSS words; the branches and stores are
/// explicit.
pub unsafe fn wm_landing_recover(actor: usize) {
    platform::call2(FUN_80056C70, actor as u32, 0xBB);
    platform::write_u32(actor + 0x154C, 0xFF);
    vcall60_2(actor, 0x294, G_80375C2C as u32, 1);
    let controller = platform::read_u32(actor + 0x2A64) as usize;
    vcall_f64_f64_f64_u32(
        controller,
        0x5C,
        read_f32(G_80371408) as f64,
        read_f32(G_8037140C) as f64,
        read_f32(R2_5928_ZERO) as f64,
        0x85,
    );
    platform::write_u16(actor + 0x102, 0);
    if platform::read_u8(actor + 0x38F) == 0 {
        vcall60_f64(actor, 0x428, read_f32(R2_5704_2800) as f64);
    } else {
        vcall60_f64(actor, 0x428, read_f32(R2_5700_NEG2000) as f64);
    }
    platform::write_u32(actor + 0x1074, 0x23);
    platform::call1(FUN_8013E850, actor as u32);
    let global = platform::read_u32(SDA_59EC_PTR) as usize;
    let player = platform::read_u8(actor + 0x38D) as i8 as i32 as u32;
    if platform::call2(FUN_8005D090, global as u32, player) == 0 {
        platform::write_u32(actor + 0x1458, 2);
    } else {
        platform::write_u32(actor + 0x1458, 0);
    }
}

