/// Seeds the landing speed from the side table and plays controller sound `5`.
///
/// Cancels bit `0xBB`, sets `+0x145C = 0x1E`, sends sound `5`, copies the low
/// byte of `+0x1454` into `+0x348`, sets `+0x10C` and `+0x110` to
/// `0.5 * side_table[+0x1454 & 0xFF]`, stores `4.2` (variant `3`) or `5.0` in
/// `+0xEC`, stores `-4.0` in `+0x118`, runs `0x8004C560(actor)` and refreshes
/// `+0x102` through slot `+0x444`.
///
/// # Original
/// - Ghidra: `FUN_8013ED10` at `0x8013ED10` (216 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8013ed10_FUN_8013ed10.c`
///
/// # Arguments
/// * `actor` - WorldMap player actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Seven field writes, two virtual calls and one external call.
///
/// # Safety
/// `actor` must be live and `+0x1454 & 0xFF` must index the `0x8042B840`
/// table.
///
/// # Confidence
/// high - the table index, both variants and every store are explicit.
pub unsafe fn wm_landing_setup_speed(actor: usize) {
    platform::call2(FUN_80056CB0, actor as u32, 0xBB);
    platform::write_u32(actor + 0x145C, 0x1E);
    let controller = platform::read_u32(actor + 0x2A64) as usize;
    vcall_f64_f64_f64_u32(
        controller,
        0x5C,
        read_f32(G_80370E08) as f64,
        read_f32(R2_5928_ZERO) as f64,
        read_f32(R2_5928_ZERO) as f64,
        5,
    );
    let variant = platform::read_u32(actor + 0x1454);
    let side = (variant & 0xFF) as usize;
    platform::write_u8(actor + 0x348, side as u8);
    let speed = read_f32(R2_591C_HALF) * read_f32(G_SIDE_TABLE_8042B840 + side * 4);
    write_f32(actor + 0x10C, speed);
    write_f32(actor + 0x110, speed);
    if platform::read_u32(actor + 0x1090) == 3 {
        write_f32(actor + 0xEC, read_f32(R2_56FC_4_2));
    } else {
        write_f32(actor + 0xEC, read_f32(R2_5868_FIVE));
    }
    write_f32(actor + 0x118, read_f32(R2_781C_NEG4));
    platform::call1(FUN_8004C560, actor as u32);
    let angle = vcall60_1(actor, 0x444, platform::read_u8(actor + 0x348) as u32);
    platform::write_u16(actor + 0x102, angle as u16);
}

/// Reports whether the landing gate is fully open.
///
/// Four conditions must hold: slot `+0x128` returns non-zero,
/// `0x8005E890(+0xEA4)` returns non-zero, the `+0x1418` sub-object reports
/// `0x8035476C` through its two virtual slots, bit `0` of `+0x10DC` is set, and
/// the integer part of the height `+0xB0` has zero low four bits.
///
/// # Original
/// - Ghidra: `FUN_8013F100` at `0x8013F100` (188 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8013f100_FUN_8013f100.c`
///
/// # Arguments
/// * `actor` - WorldMap player actor.
///
/// # Returns
/// `1` when all conditions hold, `0` otherwise.
///
/// # Side effects
/// Three virtual calls and one external call.
///
/// # Safety
/// `actor` must be live and `actor+0x1418` must hold a valid vtable.
///
/// # Confidence
/// high - all five tests and the data word are explicit; the height test keeps
/// the float-to-integer truncation of the original.
pub unsafe fn wm_landing_gate_passed(actor: usize) -> u32 {
    if vcall60_0(actor, 0x128) == 0 {
        return 0;
    }
    if platform::call1(FUN_8005E890, (actor + 0xEA4) as u32) == 0 {
        return 0;
    }
    let sub = actor + 0x1418;
    let sub_vtable = platform::read_u32(sub) as usize;
    let get_port = platform::read_u32(sub_vtable + 0x28) as usize;
    let port = platform::call1(get_port, sub as u32) as usize;
    let port_vtable = platform::read_u32(port) as usize;
    let compare = platform::read_u32(port_vtable + 0x10) as usize;
    if platform::call2(compare, port as u32, G_8035476C as u32) == 0 {
        return 0;
    }
    if platform::read_u32(actor + 0x10DC) & 1 == 0 {
        return 0;
    }
    if read_f32(actor + 0xB0) as i32 as u32 & 0xF != 0 {
        return 0;
    }
    1
}

