/// Raises the actor onto the ground and enters action state `6`.
///
/// Copies `+0xAC`/`+0xB0`/`+0xB4` into a stack position, adds `8.0` plus the
/// value from `0x80132530` to the vertical component, probes the ground with
/// `0x800757B0`, and raises `+0xB0` when the probe reports a higher surface.
/// Then writes `+0x1538 = 10`, state `6`, clears `+0x1DF4`, sends sound `0x40`,
/// posts event `0x21`, clears bit `0x36` and releases `+0x14FC`.
///
/// # Original
/// - Ghidra: `FUN_80137130` at `0x80137130` (256 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80137130_FUN_80137130.c`
///
/// # Arguments
/// * `actor` - WorldMap player actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Two virtual calls, one `0x80056CB0` clear, one ground probe and up to five
/// field writes.
///
/// # Safety
/// `actor`, its controller and the `0x800757B0` probe must be usable.
///
/// # Confidence
/// medium - the position layout and stores are literal; the `0x80132530` role
/// is inferred from its per-player height return.
pub unsafe fn fn_80137130(actor: usize) {
    let mut position = crate::platform::GuestLocal::new( [0u8; 16]);
    let x = read_f32(actor + 0xAC);
    let z = read_f32(actor + 0xB4);
    let lift = (read_f32(R2_58D0_EIGHT) as f64 + call_u32_f64(FUN_80132530, actor as u32)) as f32;
    write_f32(position.as_mut_ptr() as usize, x);
    write_f32(position.as_mut_ptr() as usize + 4, read_f32(actor + 0xB0) + lift);
    write_f32(position.as_mut_ptr() as usize + 8, z);
    let mut surface = crate::platform::GuestLocal::<f32>::new( 0f32);
    let hit = platform::call5(
        FUN_800757B0,
        position.as_ptr() as u32,
        ((surface.as_mut_ptr() as *mut f32)) as u32,
        platform::read_u8(actor + 0x38F) as u32,
        1,
        0xFFFF_FFFF,
    );
    if hit != 0 && read_f32(actor + 0xB0) < *surface {
        write_f32(actor + 0xB0, *surface);
    }
    platform::write_u32(actor + 0x1538, 10);
    platform::write_u32(actor + 0x14A4, 6);
    platform::write_u32(actor + 0x1DF4, 0);
    let controller = platform::read_u32(actor + 0x2A64) as usize;
    vcall_f64_f64_f64_u32(
        controller,
        0x5C,
        read_f32(G_803710CC) as f64,
        read_f32(R2_5928_ZERO) as f64,
        read_f32(R2_5928_ZERO) as f64,
        0x40,
    );
    vcall60_2(actor, 0x434, 0x21, 0);
    platform::call2(FUN_80056CB0, actor as u32, 0x36);
    fn_80135fc0(actor);
}

/// Advances the three-state landing hand-off.
///
/// State `0` sends sound `0x3F` and moves to `1`; state `1` waits for
/// `0x80169020(controller + 0x28)`, sends sound `0x3B`, zeroes `+0x102` and
/// moves to `2`; state `2` posts `0x80375C2C` with argument `1`.
///
/// # Original
/// - Ghidra: `FUN_80137230` at `0x80137230` (240 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80137230_FUN_80137230.c`
///
/// # Arguments
/// * `actor` - WorldMap player actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Up to two controller virtual calls, one actor virtual call, one
/// `0x80169020` call and writes `+0x102`, `+0x1DF4`.
///
/// # Safety
/// `actor` and its controller must be live.
///
/// # Confidence
/// medium - the states and calls are literal; the sound doubles are BSS words.
pub unsafe fn fn_80137230(actor: usize) {
    let state = platform::read_u32(actor + 0x1DF4);
    if state == 0 {
        let controller = platform::read_u32(actor + 0x2A64) as usize;
        vcall_f64_f64_f64_u32(
            controller,
            0x5C,
            read_f32(G_803710C0) as f64,
            read_f32(G_803710C4) as f64,
            read_f32(R2_5928_ZERO) as f64,
            0x3F,
        );
        platform::write_u32(actor + 0x1DF4, 1);
    } else if state == 1 {
        let controller = platform::read_u32(actor + 0x2A64) as usize;
        if platform::call1(FUN_80169020, (controller + 0x28) as u32) != 0 {
            vcall_f64_f64_f64_u32(
                controller,
                0x5C,
                read_f32(G_80371090) as f64,
                read_f32(R2_5928_ZERO) as f64,
                read_f32(R2_5928_ZERO) as f64,
                0x3B,
            );
            platform::write_u16(actor + 0x102, 0);
            platform::write_u32(actor + 0x1DF4, 2);
        }
    } else if state == 2 {
        vcall60_2(actor, 0x294, G_80375C6C as u32, 1);
    }
}

