/// Chooses and submits the two or three ground colliders from `+0x5B4`.
///
/// # Original
/// - Ghidra: `FUN_8011D450` at `0x8011D450` (312 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8011d450_FUN_8011d450.c`
///
/// # Arguments
/// * `object` - magma-wave object with the height `+0x5B4`, the segment table
///   at `+0x554..+0x584` and the height-field state at `+0x1EC`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// When the object's header type is `1`, submits an empty collider set and
/// clears `+0x23C`. Otherwise fills the three descriptors from `+0x5B4` and
/// submits them through `0x8006D090`.
///
/// # Safety
/// `object` must be live and the height-field state must accept the descriptor
/// pointers.
///
/// # Confidence
/// medium - the arithmetic and both calls are literal; the descriptor fields
/// are inferred collider words.
pub unsafe fn fn_8011d450(object: usize) {
    let kind = (platform::read_u32(object + 4) >> 16) & 3;
    if kind == 1 {
        platform::call5(FUN_8006D090, (object + 0x1EC) as u32, object as u32, 0, 0, 0);
        platform::write_u32(object + 0x23C, 0);
        return;
    }
    let height = read_f32(object + 0x5B4);
    platform::write_u32(object + 0x560, 0);
    let half = read_f32(R2_5B5C_HALF) * height;
    let span = read_f32(R2_5B0C_4096);
    let low = span * (half - read_f32(R2_5B08_THREE));
    platform::write_u32(object + 0x554, 1);
    platform::write_u32(object + 0x564, 1);
    platform::write_u32(object + 0x574, 1);
    let low_i = low as i32;
    platform::write_i32(object + 0x558, -low_i);
    platform::write_i32(object + 0x55C, low_i);
    platform::write_u32(object + 0x578, 0x4000);
    platform::write_i32(object + 0x568, -low_i);
    platform::write_i32(object + 0x56C, low_i);
    platform::write_i32(
        object + 0x570,
        (span * read_f32(object + 0x5B8)) as i32,
    );
    platform::write_i32(
        object + 0x57C,
        (span * (read_f32(object + 0x5B8) - read_f32(R2_5B28_FOUR))) as i32,
    );
    platform::write_i32(
        object + 0x580,
        (span * (half - read_f32(R2_5B5C_HALF))) as i32,
    );
    platform::call5(
        FUN_8006D090,
        (object + 0x1EC) as u32,
        object as u32,
        (object + 0x554) as u32,
        (object + 0x564) as u32,
        (object + 0x574) as u32,
    );
}

