    let inner = read_f32(G_802F4D04);
    let outer = read_f32(G_802F4D08);
    let mut value = read_f32(player + 0xE8);
    if value <= flat {
        if -flat <= value {
            value = inner * value;
        } else {
            value = -inner * flat + (value + flat) * outer;
        }
    } else {
        value = inner * flat + (value - flat) * outer;
    }
    let index = (platform::read_u8(object + 0x348) as usize) * 4;
    write_f32(object + 0xE8, value + read_f32(R2_59C0_TABLE + index));
    platform::write_u32(object + 0xEC, platform::read_u32(R2_59B0_3_7));
    platform::write_u32(object + 0xF0, platform::read_u32(R2_5A10_ZERO));
    platform::write_u32(object + 0x114, platform::read_u32(R2_59AC_NEG0_15));
    platform::write_u32(object + 0xF4, platform::read_u32(R2_59B8_TABLE + index));
    platform::write_u32(object + 0x118, platform::read_u32(R2_59C8_NEG3));
    platform::write_u32(object + 0x11C, platform::read_u32(R2_59A8_0_04));
