/// slots `0x8006CD90`/`0x8006CE70`/`0x8006CD40`, then dispatches on the ground
/// result, the `+0x274` flags and the `+0x2DC` collider.
///
/// # Safety
/// `object` must be live and all sub-objects and SDA words initialised.
///
/// # Confidence
/// high - the timer, the three transform calls and the branch tree are literal.
pub unsafe fn fn_80124340(object: usize) {
    platform::call1(FUN_80094560, (object + 0xAC) as u32);
    let timer = platform::read_u32(object + 0x3D0);
    if timer != 0 {
        let left = timer - 1;
        platform::write_u32(object + 0x3D0, left);
        if left == 0 {
            decrement_player_counter(object);
        }
    }
    platform::call1(FUN_8006CD90, object as u32);
    platform::call1(FUN_8006CE70, object as u32);
    platform::call1(FUN_8006CD40, object as u32);
    fn_80123b70(object);
    if fn_80123d70(object) != 0 {
        fn_80123a00(object);
        platform::call1(FUN_80162510, object as u32);
    } else if fn_80123970(object) {
        post_contact_event(object, 0x269);
        fn_80123a00(object);
        platform::call1(FUN_80162510, object as u32);
    } else if platform::call1(FUN_800D9900, (object + 0x2DC) as u32) != 0 {
        post_contact_event(object, 0x269);
        fn_80123a00(object);
        platform::call1(FUN_80162510, object as u32);
    } else if fn_80123c00(object) != 0 {
        platform::call1(FUN_80162510, object as u32);
    }
}

