/// Reads a big-endian `double` built from two words at `addr`.
///
/// # Safety
/// `addr .. addr + 8` must be readable.
#[inline]
unsafe fn read_f64(addr: usize) -> f64 {
    f64::from_bits(((platform::read_u32(addr) as u64) << 32) | platform::read_u32(addr + 4) as u64)
}

/// Reproduces the PowerPC compiler idiom `(double)CONCAT44(0x43300000, x ^
/// 0x80000000)` used for unsigned 32-bit to double conversion.
#[inline]
fn unsigned_to_double(value: u32) -> f64 {
    f64::from_bits((0x4330_0000u64 << 32) | (value ^ 0x8000_0000) as u64)
}

/// Calls a PowerPC function `(f64, f64, f64, f64, u32, u32, u32) -> u32`.
///
/// # Safety
/// `addr` must point at a function with this EABI prototype.
#[inline]
unsafe fn call_f64x4_u32_u32_u32(
    addr: usize,
    a: f64,
    b: f64,
    c: f64,
    d: f64,
    e: u32,
    f: u32,
    g: u32,
) -> u32 {
    let call = crate::platform::guest_fn!(addr, fn(f64, f64, f64, f64, u32, u32, u32) -> u32);
    call(a, b, c, d, e, f, g)
}

