/// `0x802BFF30`: initialises the `0x20`-byte render-mode record.
const FUN_802BFF30: usize = 0x802B_FF30;
/// `0x802BFF70`: stores the viewport rectangle `(0, 0, 640, 456)`.
const FUN_802BFF70: usize = 0x802B_FF70;
/// `0x802C0110`: commits the render-mode record.
const FUN_802C0110: usize = 0x802C_0110;
/// `0x802BEF00`: emits one coloured quad through the GX FIFO. The export shows
/// only the colour stores; the instruction stream reads four floats from `r3`
/// (`x0, y0, x1, y1`) and one RGBA quad of bytes from `r4`.
const FUN_802BEF00: usize = 0x802B_EF00;
/// `0x802BE5D0`: four-byte branch to the matrix loader `0x801C9940`.
const FUN_802BE5D0: usize = 0x802B_E5D0;
/// `0x8022DE40`: releases the nested text object at `text + 0x1C`.
const FUN_8022DE40: usize = 0x8022_DE40;
/// `r2 - 0x5E28` .. `r2 - 0x5E18`: `-400.0f`, `400.0f`, `24.0f`, `-24.0f`
/// and `0.5f`, read from `main.elf` at `0x8042D258..0x8042D268`.
const R2_5E28_NEG400: usize = SDA2_BASE - 0x5E28;
const R2_5E24_400: usize = SDA2_BASE - 0x5E24;
const R2_5E20_24: usize = SDA2_BASE - 0x5E20;
const R2_5E1C_NEG24: usize = SDA2_BASE - 0x5E1C;
const R2_5E18_HALF: usize = SDA2_BASE - 0x5E18;

/// Draws the message manager's black backdrop and its formatted text line.
///
/// In plain English: if the manager's `+0x04` byte is set, set up a
/// `640 x 456` render mode and camera, paint a black `(-400, -400)..(400, 400)`
/// quad, choose the message column from `+0x1B0`/`+0x1B4`, build the white text
/// record at the `(24, -24)` anchor, measure it twice with the selected format
/// string, hand the half-width/half-height to the record's virtual `+0x18`
/// setter, format the text, reset the light channel and release the nested
/// text object.
///
/// # Original
/// - Ghidra: `FUN_80107460` at `0x80107460` (580 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80107460_FUN_80107460.c`
///
/// # Arguments
/// * `this` - message-manager record. `+0x00` is passed to
///   [`fn_80106f80`], `+0x04` is the "draw" byte read by `0x80107850`, `+0x08`
///   is the message record handed to [`fn_801079b0`], and `+0x1B0`/`+0x1B4`
///   are the raw and latched column selectors.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Reconfigures the render mode and viewport, emits one black GX quad, writes
/// the `0x80`-byte text record, performs two text measurements, calls the
/// record's virtual setter, formats the text into the record, resets the light
/// channel through [`wm_render_light_reset`], and destroys the nested text
/// object.
///
/// # Safety
/// `this` must be live for `0x1B8` bytes, `+0x08` must be a live message
/// record, and the renderer must be initialised. The record's `+0x18` word
/// must point at the `0x80321BD8` vtable.
///
/// # Confidence
/// medium - every call, field offset, comparison, constant and float operation
/// is literal in the export or the `main.elf` instruction stream; the roles of
/// the `4`/`6`/`0xB` column selectors and of the manager bytes are inferred
/// from the neighbouring message functions.
pub unsafe fn fn_80107460(this: usize) {
    // observed: `FUN_80107850` reads the `+0x04` byte of the manager it is
    // given; the export prints the call without an argument because `r3` still
    // holds the incoming `this`.
    if platform::call1(FUN_80107850, this as u32) == 0 {
        return;
    }

    // observed: word-aligned stack records. The export names them
    // `auStack_120` (0x20 bytes), `auStack_80` (0x44 bytes plus the word the
    // frame recycles for `local_3C`) and `local_100` (0x80 bytes, including
    // the 0x64-byte nested text object at `+0x1C`).
    let mut mode = crate::platform::GuestLocal::new( [0u32; 8]);
    let mut camera = crate::platform::GuestLocal::new( [0u32; 0x12]);
    let mut text = crate::platform::GuestLocal::new( [0u32; 0x20]);
    let mode_ptr = mode.as_mut_ptr() as u32;
    let camera_ptr = camera.as_mut_ptr() as u32;
    let text_ptr = text.as_mut_ptr() as usize;

    platform::call1(FUN_802BFF30, mode_ptr);
    platform::call1(FUN_802BF3D0, camera_ptr);
    platform::call5(FUN_802BFF70, mode_ptr, 0, 0, 0x280, 0x1C8);
    platform::call1(FUN_802C0110, mode_ptr);
    // observed: the original also stores `mode_ptr` into the frame word
    // `local_3C` (r1+0x124), but nothing reads it; that store is dead.
    platform::call1(FUN_802BF650, camera_ptr);
    platform::call0(FUN_802BED10);
    platform::call1(FUN_801C5860, 0);
    // observed: Ghidra calls this `thunk_FUN_801c9940`; the instruction stream
    // shows a four-byte branch at `0x802BE5D0` to `0x801C9940`.
    platform::call2(FUN_802BE5D0, G_80424558 as u32, 0);

    // Black backdrop quad spanning `(-400, -400)..(400, 400)`. The export
    // keeps only the colour stores; the instruction stream loads all four
    // floats and `0x802BEF00` emits them as two triangles.
    let mut quad = crate::platform::GuestLocal::new( [
        read_f32(R2_5E28_NEG400),
        read_f32(R2_5E28_NEG400),
        read_f32(R2_5E24_400),
        read_f32(R2_5E24_400),
    ]);
    let mut colour = crate::platform::GuestLocal::new( [0u8, 0, 0, 0xFF]);
    platform::call2(
        FUN_802BEF00,
        quad.as_mut_ptr() as u32,
        colour.as_mut_ptr() as u32,
    );

    // observed: `param_1[0x6C]` is `+0x1B0` and `param_1[0x6D]` is `+0x1B4`.
    let state = platform::read_u32(this + 0x1B0);
    let mut column = 4u32;
    if state < 2 {
        match platform::read_u32(this + 0x1B4) {
            4 => column = 0,
            0x0B => column = 1,
            6 => column = 2,
            _ => {}
        }
    } else {
        match state {
            4 => column = 0,
            0x0B => column = 1,
            6 => column = 2,
            _ => {}
        }
    }
    let format = fn_801079b0(this + 8, column);

    fn_80106ee0(text_ptr);
    fn_80106f80(text_ptr, platform::read_u32(this));
    wm_transform_scene_apply(text_ptr);
    // White text colour at `+0x00..+0x03`.
    let mut index = 0;
    while index < 4 {
        platform::write_u8(text_ptr + index, 0xFF);
        index += 1;
    }
    fn_80106fa0(
        read_f32(R2_5E20_24) as f64,
        read_f32(R2_5E1C_NEG24) as f64,
        text_ptr,
    );

    // First measurement: the export prints no variadic words for this call, so
    // the model supplies empty arrays.
    let mut rect = crate::platform::GuestLocal::new( [0f32; 4]);
    fn_80107170(
        rect.as_mut_ptr() as usize,
        text_ptr,
        format,
        [0u32; 5],
        [0f64; 8],
    );
    let width = rect[2] - rect[0];
    let half_width = read_f32(R2_5E18_HALF) * width;

    // Second measurement: the instruction stream loads the line width into
    // `f1`, which the export prints as the first argument.
    let mut inner = crate::platform::GuestLocal::new( [0f32; 4]);
    let mut fpr = [0f64; 8];
    fpr[0] = width as f64;
    fn_80107170(
        inner.as_mut_ptr() as usize,
        text_ptr,
        format,
        [0u32; 5],
        fpr,
    );
    let height = read_f32(R2_5E18_HALF) * (inner[3] - inner[1]);

    // observed: the record's `+0x18` word is the `0x80321BD8` vtable written by
    // [`fn_80106ee0`]; slot `+0x18` is the `0x801072D0` float setter, which
    // stores `f1` at `+0x04`/`+0x0C` and `f2` at `+0x08`.
    let vtable = platform::read_u32(text_ptr + 0x18) as usize;
    let setter = platform::read_u32(vtable + 0x18) as usize;
    call_f64_f64_u32(setter, -(half_width as f64), height as f64, text_ptr as u32);

    fn_80107050(text_ptr, format, [0u32; 6], [0f64; 8]);
    wm_render_light_reset();
    platform::call2(FUN_8022DE40, (text_ptr + 0x1C) as u32, 0xFFFF_FFFF);
}

/// Advances the overlay load state for one frame.
///
/// # Original
/// - Ghidra: `FUN_801076B0` at `0x801076B0` (412 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801076b0_FUN_801076b0.c`
///
/// # Arguments
/// * `this` - overlay object; `+0x04` is the "already seen a load" byte,
///   `+0x1B0` the raw load state, `+0x1B4` the latched state, `+0x1B8` the
///   done byte, `+0x1B9` the "overlay active" byte and `+0x1BC` the idle
///   counter.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Calls `0x801CEF60` and `0x80107F10`, may raise an event on the load book at
/// `(*r13 - 0x55F4) + 0x4C`, and writes the six fields listed above.
///
/// # Safety
/// `this` must be live for `0x1C0` bytes; both `r13` objects must be readable
/// and the load book writable at `+0x09`.
///
/// # Confidence
/// medium - every branch, mask and store is literal; the three load states
/// `4`/`6`/`0xB` and the `0x13` timeout are inferred roles.
pub unsafe fn fn_801076b0(this: usize) {
    let state = call0_u32(FUN_801CEF60);
    platform::write_u32(this + 0x1B0, state);
    let busy = state == 4 || state == 6 || state == 0x0B;
    if platform::read_u8(this + 0x04) == 0 {
        if busy {
            platform::write_u8(this + 0x04, 1);
            let book = platform::read_u32(platform::read_u32(SDA_55F4_OBJECT) as usize + 0x4C)
                as usize;
            let flag_object = platform::read_u32(SDA_4838_OBJECT) as usize;
            let flag = vcall0(flag_object, 8) as usize;
            let enabled = if (platform::read_u8(flag + 4) & 1) == 0
                || (platform::read_u8(book + 9) & 1) != 0
            {
                0
            } else {
                platform::write_u8(book + 9, platform::read_u8(book + 9) | 1);
                1
            };
            platform::write_u8(this + 0x1B9, enabled);
        }
    } else if busy {
        platform::write_u32(this + 0x1B4, state);
    } else if state == 0 {
        let controller = call0_u32(FUN_80107F10) as usize;
        let mut busy_controller = false;
        if platform::read_u32(controller + 0x0C) == 5
            || platform::read_u32(controller + 0x08) == 5
        {
            busy_controller = true;
        }
        if !busy_controller {
            let counter = platform::read_u32(this + 0x1BC).wrapping_add(1);
            platform::write_u32(this + 0x1BC, counter);
            if counter > 0x13 {
                platform::write_u8(this + 0x04, 0);
                platform::write_u8(this + 0x1B8, 0);
                platform::write_u32(this + 0x1B4, 0);
                platform::write_u32(this + 0x1BC, 0);
                if platform::read_u8(this + 0x1B9) != 0 {
                    let book =
                        platform::read_u32(platform::read_u32(SDA_55F4_OBJECT) as usize + 0x4C)
                            as usize;
                    let flag_object = platform::read_u32(SDA_4838_OBJECT) as usize;
                    let flag = vcall0(flag_object, 8) as usize;
                    let enabled = if (platform::read_u8(flag + 4) & 1) == 0
                        && (platform::read_u8(book + 9) & 1) == 0
                    {
                        platform::write_u8(book + 9, platform::read_u8(book + 9) | 1);
                        1
                    } else {
                        0
                    };
                    platform::write_u8(this + 0x1B9, enabled);
                }
            }
        }
    } else {
        platform::write_u32(this + 0x1BC, 0);
    }
}

/// Returns whether the global load has finished.
///
/// # Original
/// - Ghidra: `FUN_80107860` at `0x80107860` (44 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80107860_FUN_80107860.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `1` when `0x80107340` returns `0`, otherwise `0`. The export computes
/// `countLeadingZeros(result) >> 5`.
///
/// # Side effects
/// Starts the load through `0x801072F0` and blocks in `0x80107340` until the
/// load reports completion.
///
/// # Safety
/// The loader must be initialised and must eventually set its done byte.
///
/// # Confidence
/// high - both calls and the `countLeadingZeros >> 5` reduction are literal.
pub unsafe fn fn_80107860() -> u32 {
    platform::call0(FUN_801072F0);
    // `0x80107340` takes no argument; `call1(..., 0)` is used only to read the
    // `r3` result that the export consumes through `countLeadingZeros`.
    let result = platform::call1(FUN_80107340, 0);
    result.leading_zeros() >> 5
}

/// Clears the message record and the two sub-records it owns.
///
/// # Original
/// - Ghidra: `FUN_80107890` at `0x80107890` (132 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80107890_FUN_80107890.c`
///
/// # Arguments
/// * `this` - message record; `+0xE0` is the mode record and `+0xF4` the
///   language pointer table.
///
/// # Returns
/// `this`, unchanged.
///
/// # Side effects
/// Resets `+0xE0` through [`fn_80107c70`], installs the pointer table through
/// [`fn_80107ad0`], then clears `0xE0` bytes starting at `+0x00`.
///
/// # Safety
/// `this` must be writable for `0x150` bytes.
///
/// # Confidence
/// high - the two calls and the two interleaved clear loops are literal; the
/// loops cover `0x00..0xE0` exactly.
pub unsafe fn fn_80107890(this: usize) -> usize {
    fn_80107c70(this + 0xE0);
    fn_80107ad0(this + 0xF4);
    let mut i = 0usize;
    while i < 7 {
        let pair = this + 0xA8 + i * 8;
        platform::write_u32(pair, 0);
        platform::write_u32(pair + 4, 0);
        let six = this + i * 0x18;
        let mut j = 0usize;
        while j < 6 {
            platform::write_u32(six + j * 4, 0);
            j += 1;
        }
        i += 1;
    }
    this
}

/// Copies fourteen words of the message table and rebuilds all string slots.
///
/// # Original
/// - Ghidra: `FUN_80107920` at `0x80107920` (136 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80107920_FUN_80107920.c`
/// - Removed: the modelled `0x802DCD74` pair call. It is the outlined
///   `_savegpr_27` prologue helper, which preserves the incoming `r3`/`r4`; the
///   owner and source are now the live parameters.
///
/// # Arguments
/// * `param_1` - the dispenser owner, writable for at least `0x100` bytes
///   (incoming `r3`).
/// * `param_2` - the fourteen-word message source (incoming `r4`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Copies fourteen words from the source to `owner + 0xA8`, calls
/// [`fn_801079e0`] for each of the three columns, then installs the mode record
/// through [`fn_80107c90`].
///
/// # Safety
/// `param_1` must be writable for at least `0x100` bytes and `param_2` must be a
/// readable source of fourteen words.
///
/// # Confidence
/// medium - the loop bounds, copy and three calls are literal; the
/// `(owner, source)` roles are the incoming `r3`/`r4` arguments.
pub unsafe fn fn_80107920(param_1: u32, param_2: u32) {
    let owner = param_1 as usize;
    let source = param_2 as usize;
    let mut i = 0usize;
    while i < 0x0E {
        let value = platform::read_u32(source + i * 4);
        platform::write_u32(owner + 0xA8 + i * 4, value);
        let mut column = 0u32;
        while column < 3 {
            fn_801079e0(owner, i as u32, column);
            column += 1;
        }
        i += 1;
    }
    fn_80107c90(owner + 0xE0, 1, (owner + 0xF4) as u32);
}

/// Returns one string-slot word for a message column.
///
/// # Original
/// - Ghidra: `FUN_801079B0` at `0x801079B0` (40 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801079b0_FUN_801079b0.c`
///
/// # Arguments
/// * `this` - message record.
/// * `column` - column index `0..=4`; `4` returns the shared language table.
///
/// # Returns
/// For `column == 4` the address `r13 - 0x65D8`; otherwise the word at
/// `this + 0xE0 + mode * 0xC + column * 4`.
///
/// # Side effects
/// None.
///
/// # Safety
/// The computed address must be readable.
///
/// # Confidence
/// medium - the arithmetic is literal; the meaning of the `+0xE0` selector is
/// inferred from [`fn_80107c90`], which writes the same record.
pub unsafe fn fn_801079b0(this: usize, column: u32) -> u32 {
    if column == 4 {
        return (SDA_BASE - 0x65D8) as u32;
    }
    let mode = platform::read_u32(this + 0xE0) as usize;
    platform::read_u32(this + 0xE0 + mode * 0xC + column as usize * 4)
}

/// Builds or selects one string slot of a message record.
///
/// # Original
/// - Ghidra: `FUN_801079E0` at `0x801079E0` (196 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801079e0_FUN_801079e0.c`
/// - Removed: the modelled `0x802DCD6C` pair call and the `0x802DCDB8`
///   epilogue call. They are the outlined `_savegpr_25`/`_restgpr_25` pair; the
///   record base is `owner` (`r3`) and the message index is `slot` (`r4`).
///
/// # Arguments
/// * `owner` - message record base (incoming `r3`).
/// * `slot` - message index `0..=13` (incoming `r4`).
/// * `column` - string column `0..=2`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// When the column does not need generated text, stores the shared string
/// pointer; otherwise allocates `strlen(shared) + strlen(source) + 1` bytes,
/// clears them, concatenates both strings and stores the buffer.
///
/// # Safety
/// `owner` must be writable at `r13`-relative record offsets and the
/// string-table entry must be readable.
///
/// # Confidence
/// medium - the allocation, length sum, clear and copy are literal; the
/// `owner`/`slot` split and the string-table stride are inferred.
pub unsafe fn fn_801079e0(owner: usize, slot: u32, column: u32) {
    let base = owner;
    let index = slot as usize;
    let source = platform::read_u32(base + index * 4 + 0xA8);
    let shared = platform::read_u32(STRING_TABLE_80322130 + (index * 3 + column as usize) * 4);
    if fn_80107ab0(owner, column) == 0 {
        platform::write_u32(column as usize * 4 + base + index * 0xC, shared);
    } else {
        let length = platform::call1(FUN_802DC69C, source)
            .wrapping_add(platform::call1(FUN_802DC69C, shared))
            .wrapping_add(1);
        let buffer = platform::call1(FUN_802B9250, length) as usize;
        platform::write_u32(base + index * 0xC + column as usize * 4, buffer as u32);
        platform::call3(FUN_800046B4, buffer as u32, 0, length);
        platform::call4(FUN_802E16E8, buffer as u32, length, shared, source);
    }
}

