        platform::call1(FUN_80169CD0, (object + 0x584) as u32);
        platform::call1(FUN_80168D10, (object + 0x5C4) as u32);
        platform::write_u32(object + 0x5C4, VTABLE_80303408 as u32);
        platform::call1(FUN_80168D10, (object + 0x5FC) as u32);
        platform::write_u32(object + 0x5FC, VTABLE_80303408 as u32);
