/// Applies the packed entry word and seeds the whole `+0x7xx` state.
///
/// Splits the word at `+0x04` into the three 4-bit indices `+0x810`
/// (player/variant), `+0x814` (kind) and `+0x7EC` (entry class), copies nine
/// words from `0x80375278` and keeps the triple selected by the entry class as
/// `+0x7D4..+0x7DC`, then writes the speed words, the four-word float
/// rectangle from `0x802F4B70`, the three collision boxes at `+0x75C..+0x788`
/// and the remaining state bytes.
///
/// # Original
/// - Ghidra: `FUN_801102D0` at `0x801102D0` (776 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801102d0_FUN_801102d0.c`
///
/// # Arguments
/// * `object` - course-entry controller built by [`fn_80110170`].
///
/// # Returns
/// Always `1`.
///
/// # Side effects
/// About fifty field writes plus `0x80111850`, the `+0x850` layout refresh,
/// `0x8006D090` (three boxes), `0x8008C3E0` (2-D record) and one virtual
/// notification through slot `+0xD4`.
///
/// # Safety
/// `object` must be live and the player objects returned by `0x8005F900` must
/// exist, because the entry-class-0 path reads `+0x60`/`+0xE8` of that object.
///
/// # Confidence
/// medium - the stores are literal, but the entry-class-0 branch calls a
/// vtable slot of an object whose identity is only inferred from
/// `0x8005F900(+0x810)`, and one table triple's role is inferred.
pub unsafe fn fn_801102d0(object: usize) -> u32 {
    let word = platform::read_u32(object + 4);
    platform::write_u8(object + 0x822, 1);
    let entry_class = (word >> 8) & 0xF;
    platform::write_u32(object + 0x810, word & 0xF);
    platform::write_u32(object + 0x814, (word >> 4) & 0xF);
    platform::write_u32(object + 0x7EC, entry_class);
    // observed: nine words at 0x80375278 are copied into a stack array and the
    // three-word slice chosen below is stored at +0x7D4.
    let mut table = [0u32; 9];
    for (index, slot) in table.iter_mut().enumerate() {
        *slot = platform::read_u32(DATA_80375278 + index * 4);
    }
    let variant = if entry_class == 0 {
        let player = platform::call1(FUN_8005F900, word & 0xF) as usize;
        // observed: the vtable pointer lives at +0x60, so this is not a plain
        // first-word dispatch.
        let vtable = platform::read_u32(player + 0x60) as usize;
        let entry = platform::read_u32(vtable + 0xE8) as usize;
        platform::call2(entry, player as u32, 0xFFFF_FFFF)
    } else {
        1
    };
    let variant = (variant & 0xFF) as usize;
    platform::write_u32(object + 0x7D4, table[variant * 3]);
    platform::write_u32(object + 0x7D8, table[variant * 3 + 1]);
    platform::write_u32(object + 0x7DC, table[variant * 3 + 2]);
    platform::call1(FUN_80111850, object as u32);
    vcall2(object + 0x850, 8, (object + 0x834) as u32, 2);
    if platform::read_u32(object + 0x7EC) == 1 {
        let zero = platform::read_u32(R2_5D10_ZERO);
        platform::write_u32(object + 0x7A4, zero);
        platform::write_u32(object + 0x7A8, zero);
        platform::write_u32(object + 0x7AC, zero);
        platform::write_u8(object + 0x80C, 0);
        platform::write_u32(
            object + 0x120,
            platform::read_u32(object + 0x120) | 0x20,
        );
    }
    let one = platform::read_u32(R2_5D0C_ONE);
    platform::write_u32(object + 0xDC, one);
    platform::write_u32(object + 0xE0, one);
    platform::write_u32(object + 0xE4, one);
    let four = platform::read_u32(R2_5D08_FOUR);
    let neg_four = platform::read_u32(R2_5D04_NEG4);
    let zero = platform::read_u32(R2_5D10_ZERO);
    platform::write_u32(object + 0x114, platform::read_u32(SDA_6408_RATE));
    platform::write_u32(object + 0xF4, four);
    platform::write_u32(object + 0xF8, neg_four);
    platform::write_u32(object + 0xFC, zero);
    platform::write_u8(object + 0x81F, 0xFF);
    platform::write_u32(object + 0x800, platform::read_u32(DATA_802F4B70));
    platform::write_u32(object + 0x324, platform::read_u32(DATA_802F4B70 + 4));
    platform::write_u32(object + 0x318, platform::read_u32(DATA_802F4B70 + 8));
    platform::write_u32(object + 0x31C, platform::read_u32(DATA_802F4B70 + 0xC));
    platform::write_u8(object + 0x36D, 0);
    if platform::read_u32(object + 0x7EC) == 0 {
        let player = platform::call1(FUN_8005F900, platform::read_u32(object + 0x810)) as usize;
        platform::write_u32(object + 0xB4, platform::read_u32(R2_5D00_8000));
        platform::write_u8(object + 0x821, 1);
        if platform::read_u8(player + 0x38F) == 0
            && read_f32(player + 0xB4) < read_f32(R2_5D10_ZERO)
        {
            platform::write_u8(object + 0x821, 2);
        }
    } else {
        platform::write_u8(object + 0x821, 1);
    }
    // observed: three 4-word collision boxes, each opened by 0x80000001.
    platform::write_u32(object + 0x75C, 0x8000_0001);
    platform::write_u32(object + 0x760, 0xFFFF_9000);
    platform::write_u32(object + 0x764, 0x0000_7000);
    platform::write_u32(object + 0x768, 0x0000_3000);
    platform::write_u32(object + 0x76C, 0x8000_0001);
    platform::write_u32(object + 0x770, 0xFFFF_9000);
    platform::write_u32(object + 0x774, 0x0000_7000);
    platform::write_u32(object + 0x778, 0x0001_D000);
    platform::write_u32(object + 0x77C, 0x8000_0001);
    platform::write_u32(object + 0x780, 0x0000_5000);
    platform::write_u32(object + 0x784, 0x0001_8000);
    platform::write_u32(object + 0x788, 0x0000_7000);
    platform::call5(
        FUN_8006D090,
        (object + 0x1EC) as u32,
        object as u32,
        (object + 0x75C) as u32,
        (object + 0x76C) as u32,
        (object + 0x77C) as u32,
    );
    platform::call3(
        FUN_8008C3E0,
        (object + 0x148) as u32,
        object as u32,
        DATA_802F4B80 as u32,
    );
    platform::write_u8(object + 0x1E8, 0);
    platform::write_u8(object + 0x1E7, platform::read_u8(object + 0x821));
    platform::write_u32(object + 0x518, 4);
    platform::write_u8(object + 0x1E6, 1);
    platform::write_u32(object + 0x87C, 0);
    platform::write_u32(object + 0x800, 0);
    platform::write_u8(object + 0x880, 0);
    platform::write_u8(object + 0x881, 0);
    if platform::read_u32(object + 0x7EC) == 0 && platform::read_u32(object + 0x814) == 2 {
        platform::write_u32(object + 0x7FC, 0x28);
    }
    vcall60_1(object, 0xD4, DATA_80375108 as u32);
    1
}

/// Snapshots the contact position while the entry gate is open.
///
/// Both `+0x87C` (word) and `+0x880` (byte) must be clear. The contact is
/// accepted when the `+0x394` name component rejects `0x80375248` (the
/// `(int)(-v | v) < 0` idiom is the export's "value is non-zero" test). On
/// success [`fn_801111b0`] stores the position triple from `0x8006CED0` at
/// `+0x870..+0x878` and raises `+0x86C`.
///
/// # Original
/// - Ghidra: `FUN_801111B0` at `0x801111B0` (212 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801111b0_FUN_801111b0.c`
///
/// - observed: the name query is followed by `neg r0,r3` / `or r0,r0,r3` /
///   `rlwinm. r0,r0,1,31,31` / `bne` to the epilogue, so the snapshot runs
///   when the query answers 0 (and exits for any non-zero id).
/// # Arguments
/// * `object` - course-entry controller.
/// * `event` - event record whose `+0x04` word is the other actor.
/// * `source` - record whose `+0x04` word provides the position.
///
/// # Returns
/// Always `1`.
///
/// # Side effects
/// One virtual name query, `0x80110CA0`, `0x8006CED0` and four stores.
///
/// # Safety
/// Both records and the actor behind `event + 0x04` must be live.
///
/// # Confidence
/// medium - the guard and stores are literal; the roles of `+0x870` and `+0x86C`
/// as the cached contact position and its valid flag are inferred.
pub unsafe fn fn_801111b0(object: usize, event: usize, source: usize) -> u32 {
    if platform::read_i32(object + 0x87C) < 1 && platform::read_u8(object + 0x880) == 0 {
        let other = platform::read_u32(event + 4) as usize;
        let component = vcall0(other + 0x394, 0x28) as usize;
        let id = vcall1(component, 0x14, DATA_80375248 as u32);
        if id == 0 {
            platform::call3(
                FUN_80110CA0,
                object as u32,
                platform::read_u32(source + 4),
                other as u32,
            );
            let mut position = crate::platform::GuestLocal::new( [0u32; 3]);
            platform::call2(
                FUN_8006CED0,
                position.as_mut_ptr() as u32,
                platform::read_u32(source + 4),
            );
            platform::write_u32(object + 0x870, position[0]);
            platform::write_u32(object + 0x874, position[1]);
            platform::write_u32(object + 0x878, position[2]);
            platform::write_u8(object + 0x86C, 1);
        }
    }
    1
}

