/// Clamps the object's height into the scene floor band.
///
/// The band is `scene+0x3C - 24.0f` down to `scene+0x3C - scene+0x44`, and the
/// correction is taken from the camera height at `camera+0x8FEAC`, clamped to
/// `±7.0f`. On a correction the turn value `+0xEC` is halved toward the
/// correction, and when the correction is exactly `0.0f` the turn sign flips.
///
/// # Original
/// - Ghidra: `FUN_80112B30` at `0x80112B30` (220 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80112b30_FUN_80112b30.c`
///
/// # Arguments
/// * `object` - course-entry controller.
/// * `flag` - non-zero enables the exact-zero turn flip.
///
/// # Returns
/// `1` when the height was unchanged, `0` when it was corrected (the export
/// returns `(uint)-mode >> 31`).
///
/// # Side effects
/// Writes `+0xB0` and possibly `+0xEC`.
///
/// # Safety
/// The scene and camera globals must be initialised.
///
/// # Confidence
/// medium - the arithmetic is literal; the `+0x8FEAC` camera field and the
/// `+0x3C`/`+0x44` scene fields are named from their use here and in the
/// neighbouring bodies, not by the export.
pub unsafe fn fn_80112b30(object: usize, flag: usize) -> u32 {
    let scene = platform::read_u32(SDA_5880_PTR) as usize;
    let camera = platform::read_u32(SDA_58B0_OBJECT) as usize;
    let limit = read_f32(R2_5CBC_SEVEN);
    let mut correction = -(read_f32(camera + 0x8FEAC) - read_f32(scene + 0x3C));
    if correction < -limit {
        correction = -limit;
    }
    if limit < correction {
        correction = limit;
    }
    let mut mode = 0;
    let floor_limit = read_f32(scene + 0x3C) - read_f32(R2_5CB0_24);
    let turn = read_f32(object + 0xEC);
    if read_f32(object + 0xB0) <= floor_limit {
        let lower = read_f32(scene + 0x3C) - read_f32(scene + 0x44);
        if read_f32(object + 0xB0) < lower {
            write_f32(object + 0xB0, lower);
            mode = 2;
            if turn < correction {
                write_f32(object + 0xEC, read_f32(R2_5CD0_HALF) * correction);
            }
        }
    } else {
        write_f32(object + 0xB0, floor_limit);
        mode = 1;
        if correction < turn {
            write_f32(object + 0xEC, read_f32(R2_5CD0_HALF) * correction);
        }
    }
    if mode != 0 && flag != 0 && correction == read_f32(R2_5D10_ZERO) {
        write_f32(object + 0xEC, -turn);
    }
    if mode == 0 {
        1
    } else {
        0
    }
}

