/// - Evidence: `work/ghidra/main-gb/export/80113600_FUN_80113600.c`
///
/// # Arguments
/// * `object` - course-entry controller.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0xAC` and `+0xB0`.
///
/// # Safety
/// The scene object and its `+0x3C`/`+0x40`/`+0x44` fields must be readable.
///
/// # Confidence
/// medium - the four branches and every operand are literal; the meaning of
/// `+0x348` as a side selector and of `+0x7F0` as a lane index is inferred.
pub unsafe fn fn_80113600(object: usize) {
    if platform::read_i32(object + 0x814) != 0 {
        return;
    }
    let scene = platform::read_u32(SDA_5880_PTR) as usize;
    let rail = call_f64_u32_f32(
        FUN_80082240,
        read_f32(object + 0xAC) as f64,
        scene as u32,
    );
    write_f32(object + 0xAC, rail);
    let side = platform::read_u8(object + 0x348);
    let floor = read_f32(scene + 0x3C);
    write_f32(object + 0xB0, floor);
    let lane = read_f32(DATA_802F4BA8 + platform::read_i32(object + 0x7F0) as usize * 4);
    let lateral = rail + read_f32(R2_5CD0_HALF) * read_f32(scene + 0x40);
    match side {
        2 => write_f32(object + 0xAC, lateral + lane),
        3 => {
            write_f32(object + 0xAC, lateral + lane);
            write_f32(
                object + 0xB0,
                floor - (read_f32(R2_5C94_32) + read_f32(scene + 0x44)),
            );
        }
        0 => {
            write_f32(object + 0xAC, rail + read_f32(R2_5C94_32) + read_f32(scene + 0x40));
            write_f32(
                object + 0xB0,
                floor
                    - (read_f32(R2_5C94_32)
                        + read_f32(R2_5CD0_HALF) * read_f32(scene + 0x44))
                    + lane,
            );
        }
        _ => {
            write_f32(object + 0xAC, rail - read_f32(R2_5C94_32));
            write_f32(
                object + 0xB0,
                floor
                    - (read_f32(R2_5C94_32)
                        + read_f32(R2_5CD0_HALF) * read_f32(scene + 0x44))
                    + lane,
            );
        }
    }
}

