        if platform::read_u16(object + 0x502) == 0 {
            platform::call1(FUN_80112810, object as u32);
        } else {
            call_f64_f64_u32(
                FUN_8015F480,
                read_f32(object + 0x7CC) as f64,
                read_f32(R2_5C64_0_02) as f64,
                (object + 0xEC) as u32,
            );
        }
        platform::write_u32(object + 0xF4, platform::read_u32(object + 0x10C));
        platform::write_u32(object + 0xF0, platform::read_u32(R2_5D10_ZERO));
        platform::call1(FUN_8006CD90, object as u32);
        platform::call1(FUN_800955F0, object as u32);
