/// Advances the fade value from the elapsed tick count.
///
/// # Original
/// - Ghidra: `FUN_80109ec0` at `0x80109EC0` (328 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80109ec0_FUN_80109ec0.c`
///
/// # Arguments
/// * `object` - helper object; `+0x1DC` start tick, `+0x1E0` current value.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Converts `(now - start) / (bus_clock / 4000)` to a float, then walks the
/// piecewise curve `250 -> 1250 -> 1500` (see the four `r2` constants):
/// below `250` the value is `0.004 * t`; `1250..1500` clamps to `1.0f`; the
/// middle band interpolates and clamps to `0..=1`. When the curve ends (or the
/// timer is already past the first step) the timer is reset through
/// [`fn_8010a010`].
///
/// # Safety
/// `object` must be live; `0x800000F8` must hold a non-zero bus clock.
///
/// # Confidence
/// medium - the branch ladder and the clamps are literal; the constant roles
/// are read from `main.elf`, and the curve is described rather than named.
pub unsafe fn fn_80109ec0(object: usize) {
    if platform::read_u32(object + 0x1DC) == 0 {
        return;
    }
    let now = call0_u32(FUN_801B5FA0);
    let elapsed = now.wrapping_sub(platform::read_u32(object + 0x1DC));
    let ticks = elapsed / (platform::read_u32(BUS_CLOCK_HZ) / 4000);
    let zero = read_f32(R2_5E00_ZERO);
    let one = read_f32(R2_5DFC_ONE);
    let step_time = u32_as_double(ticks, R2_5DF8_TWO52) as f32;
    let mut finished = false;
    if zero <= step_time {
        if read_f32(R2_5DCC_250) <= step_time {
            if read_f32(R2_5DC4_1250) <= step_time {
                if read_f32(R2_5DC0_1500) <= step_time {
                    finished = true;
                } else {
                    let value = one - read_f32(R2_5DC8_0_004) * (step_time - read_f32(R2_5DC4_1250));
                    write_f32(object + 0x1E0, value);
                    let mut clamped = zero;
                    if zero <= value {
                        clamped = value;
                        if one < value {
                            clamped = one;
                        }
                    }
                    write_f32(object + 0x1E0, clamped);
                }
            } else {
                write_f32(object + 0x1E0, one);
            }
        } else {
            let value = read_f32(R2_5DC8_0_004) * step_time;
            write_f32(object + 0x1E0, value);
            let mut clamped = zero;
            if zero <= value {
                clamped = value;
                if one < value {
                    clamped = one;
                }
            }
            write_f32(object + 0x1E0, clamped);
        }
    } else {
        finished = true;
    }
    if finished {
        fn_8010a010(object);
    }
}

