    if a == b && b == c {
        return 5;
    }
    if a == b && (b != c && c != 0) {
        return 1;
    }
    if b == c && (a != b && a != 0) {
        return 2;
    }
    if c == 0 && (a != b && a != 0) {
        return 3;
    }
    if a == 0 && (c != b && c != 0) {
        return 4;
    }
    if a == c && (a != 0 && c != 0) {
        return 6;
    }
    if a != 0 && (b != 0 && c != 0) {
        return 7;
    }
    0
