/// Walks up to five child links and returns the first node whose test passes.
///
/// # Original
/// - Ghidra: `FUN_8011B300` at `0x8011B300` (224 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8011b300_FUN_8011b300.c`
///
/// # Arguments
/// * `object` - head of the `+0x30` chain.
///
/// # Returns
/// The current node on the first non-zero vtable `+0xC` result, otherwise the
/// recursion into the sixth child.
///
/// # Side effects
/// Up to five indirect vtable calls and one recursive call.
///
/// # Safety
/// Every node in the chain and its vtable must be live.
///
/// # Confidence
/// medium - the chain arithmetic and recursion are literal; the vtable
/// receiver's `this` argument is inferred from the call shape.
pub unsafe fn fn_8011b300(object: usize) -> usize {
    let mut current = object;
    for _ in 0..5 {
        let child = platform::read_u32(current + 0x30) as usize;
        if vcall0(child, 0xC) != 0 {
            return current;
        }
        current = child;
    }
    fn_8011b300(platform::read_u32(current + 0x30) as usize)
}

/// Applies an eight-word placement record and updates the tile extents.
///
/// # Original
/// - Ghidra: `FUN_8011C040` at `0x8011C040` (180 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8011c040_FUN_8011c040.c`
///
/// # Arguments
/// * `object` - course-background object.
/// * `arg` - forwarded to [`fn_8011c100`] through the lost register pair.
/// * `source` - pointer to the eight-word record.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Runs the four placement helpers, copies the record to the stack, calls
/// `0x8011C630` and posts two `+0x620` layout events.
///
/// # Safety
/// `source` must point at eight readable words; the object and its `+0x394`
/// component must be live.
///
/// # Confidence
/// medium - Ghidra prints the first call with no arguments, so the forwarding
/// of `object`/`arg` to `0x8011C100` is inferred from its signature.
pub unsafe fn fn_8011c040(object: usize, arg: u32, source: usize) {
    platform::call2(W89_FUN_8011C100, object as u32, arg);
    platform::call1(W89_FUN_8011C190, object as u32);
    platform::call1(W89_FUN_8011C2B0, object as u32);
    platform::call1(W89_FUN_8011C310, object as u32);
    let mut record = crate::platform::GuestLocal::new( [0u32; 8]);
    for (index, word) in record.iter_mut().enumerate() {
        *word = platform::read_u32(source + index * 4);
    }
    platform::call2(
        W89_FUN_8011C630,
        object as u32,
        record.as_mut_ptr() as u32,
    );
    platform::call2(W89_FUN_800B8250, (object + 0x620) as u32, 0);
    platform::call2(W89_FUN_800B8250, (object + 0x620) as u32, 1);
}

/// Applies one eight-float placement record.
///
/// Stores the source position at `+0xDC`, scales it by the per-player
/// `0x803755A0` vector into `+0x5B4`, and derives `+0xD0`/`+0xD4`/`+0xD8`.
///
/// # Original
/// - Ghidra: `FUN_8011C100` at `0x8011C100` (132 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8011c100_FUN_8011c100.c`
///
/// # Arguments
/// * `object` - course-background object.
/// * `source` - pointer to at least three floats (position).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0xD0..+0xE4` and `+0x5B4..+0x5BC`.
///
/// # Safety
/// `source` must point at three readable floats.
///
/// # Confidence
/// high - the table stride, the three scale factors and every store are
/// literal.
pub unsafe fn fn_8011c100(object: usize, source: usize) {
    let index = (platform::read_u32(object + 4) & 0xF) as usize;
    let x = read_f32(source);
    let y = read_f32(source + 4);
    let z = read_f32(source + 8);
    write_f32(object + 0xDC, x);
    write_f32(object + 0xE0, y);
    write_f32(object + 0xE4, z);
    let scale_x = read_f32(W89_TBL_803755A0 + index * 0xC);
    let scale_y = read_f32(W89_TBL_803755A0 + index * 0xC + 4);
    let scale_z = read_f32(W89_TBL_803755A0 + index * 0xC + 8);
    let scaled_y = y * scale_y;
    write_f32(object + 0x5B4, x * scale_x);
    write_f32(object + 0x5B8, scaled_y);
    write_f32(object + 0x5BC, z * scale_z);
    platform::write_u32(object + 0xD0, platform::read_u32(W89_R2_5B54_ZERO));
    write_f32(object + 0xD4, read_f32(W89_R2_5B5C_HALF) * scaled_y);
    platform::write_u32(object + 0xD8, platform::read_u32(W89_R2_5B54_ZERO));
}

/// Classifies the tile extent product into four size classes.
///
/// # Original
/// - Ghidra: `FUN_8011C2B0` at `0x8011C2B0` (96 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8011c2b0_FUN_8011c2b0.c`
///
/// # Arguments
/// * `object` - course-background object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x618` as `0`, `1`, `2` or `3` for the `600`/`1536`/`3072`
/// thresholds.
///
/// # Safety
/// `object + 0x5B4 .. +0x61C` must be readable/writable.
///
/// # Confidence
/// high - the product and the three ordered thresholds are literal.
pub unsafe fn fn_8011c2b0(object: usize) {
    let extent = read_f32(object + 0x5B4) * read_f32(object + 0x5B8);
    if extent < read_f32(W89_R2_5B48_600) {
        platform::write_u32(object + 0x618, 0);
    } else if extent < read_f32(W89_R2_5B44_1536) {
        platform::write_u32(object + 0x618, 1);
    } else if extent < read_f32(W89_R2_5B40_3072) {
        platform::write_u32(object + 0x618, 2);
    } else {
        platform::write_u32(object + 0x618, 3);
    }
}

/// Tests the tile placement, optionally running the fallback probe.
///
/// # Original
/// - Ghidra: `FUN_8011C6E0` at `0x8011C6E0` (108 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8011c6e0_FUN_8011c6e0.c`
///
/// # Arguments
/// * `object` - course-background object.
/// * `try_fallback` - when zero, the `0x8011C8B0` probe is skipped.
///
/// # Returns
/// `1` when the primary test or the fallback probe succeeds, otherwise `0`.
///
/// # Side effects
/// Calls `0x8011C750` and, when needed, `0x8011C8B0`.
///
/// # Safety
/// `object` and the collision state behind both probes must be live.
///
/// # Confidence
/// medium - both probes are GQR-reconstruction records, so only their return
/// booleans are used; Ghidra also drops the object argument on `0x8011C750`.
pub unsafe fn fn_8011c6e0(object: usize, try_fallback: i32) -> u32 {
    let first = platform::call1(W89_FUN_8011C750, object as u32);
    if first != 0 {
        return 1;
    }
    if try_fallback == 0 {
        return 0;
    }
    u32::from(platform::call1(W89_FUN_8011C8B0, object as u32) != 0)
}

