/// Builds the moving colour record from the seven-float table.
///
/// # Original
/// - Ghidra: `FUN_801465D0` at `0x801465D0` (252 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801465d0_FUN_801465d0.c`
///
/// # Arguments
/// * `object` - WorldMap player actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Stores the table value at `+0x1030`, scales it by `0.5`, `-0.5` or `0.25`
/// depending on bits `0`/`2` of the model's `+0x160` word, writes the
/// `+0xD0`/`+0xD4`/`+0xD8` triple, and calls `0x8015F480` with the per-variant
/// height and `0.1`.
///
/// # Safety
/// `object + 0x2A64` must be a live model record.
///
/// # Confidence
/// medium - the scale ladder is literal, but the export also copies three
/// table words (`0x802F57B0..B8`) into an unused frame tail; they are not read
/// and are omitted.
pub unsafe fn fn_801465d0(object: usize) {
    let zero = platform::read_u32(R2_5928_ZERO);
    let variant = platform::read_u32(object + PLAYER_INDEX) as usize;
    let mut value = read_f32(W90_DATA_802F57A0 + variant * 4);
    write_f32(object + 0x1030, value);
    let model = platform::read_u32(object + 0x2A64) as usize;
    let flags = platform::read_u32(model + 0x160);
    if flags & 1 == 0 {
        if flags & 4 == 0 {
            value *= read_f32(R2_591C_HALF);
        } else {
            value = -(value * read_f32(R2_591C_HALF));
        }
    } else {
        value *= read_f32(W90_R2_56C0_0_25);
    }
    platform::write_u32(object + 0xD0, zero);
    write_f32(object + 0xD4, value);
    platform::write_u32(object + 0xD8, zero);
    let base = if platform::read_u32(object + PLAYER_INDEX) == 3 {
        read_f32(R2_58D0_EIGHT)
    } else {
        read_f32(R2_584C_16)
    };
    let interpolate = crate::platform::guest_fn!(FUN_8015F480, fn(f64, f64, u32));
    interpolate(
        base as f64,
        read_f32(R2_5920_0_1) as f64,
        (object + 0x3EC) as u32,
    );
}

