/// Calls the `+0x60` vtable slot with two `f64` values and the object plus
/// three integers, in the original register order.
///
/// # Original
/// Host-side helper; no binary address of its own. Used by [`fn_801397d0`]
/// for the slot at `+0x3FC`.
///
/// # Safety
/// `object` must be live and the slot must accept
/// `(f64, f64, object, u32, u32, u32)`.
///
/// # Confidence
/// high - mechanical wrapper.
#[inline]
unsafe fn vcall60_f64_f64_u32_u32_u32(
    object: usize,
    slot: usize,
    a: f64,
    b: f64,
    c: u32,
    d: u32,
    e: u32,
) -> u32 {
    let vtable = platform::read_u32(object + 0x60) as usize;
    let entry = platform::read_u32(vtable + slot) as usize;
    let f = crate::platform::guest_fn!(entry, fn(f64, f64, usize, u32, u32, u32) -> u32);
    f(a, b, object, c, d, e)
}

