/// # Confidence
/// high - mechanical wrapper.
#[inline]
unsafe fn call_u32_ptr_u32_f64(addr: usize, a: u32, values: *const u32, index: u32) -> f64 {
    let f = crate::platform::guest_fn!(addr, fn(u32, *const u32, u32) -> f64);
    f(a, values, index)
}

