    if call0_u32(FUN_8004DD00) != 0 {
        return;
    }
    if (platform::read_u32(this + 0x10D4) & 1) == 0 {
        return;
    }
    let record = vcall0(this + 0x1464, 0x28) as usize;
    if vcall1(record, 0x10, DATA_803763B0 as u32) != 0 {
        return;
    }
    let _ = vcall60_2(this, 0x294, DATA_803763B0 as u32, event_value);
    platform::write_u32(this + 0x14A8, delay);
