/// Binds the ice archive and its three model records into an object.
///
/// Initialises the `+0x3D0` node, loads `g3d_ice_brres` into `+0x3EC`, creates
/// the `ice_A1` model selected by the `+0x04` nibble, builds the `+0x3F0`
/// record and the `+0x434` layout, then finishes the node.
///
/// # Original
/// - Ghidra: `FUN_80114C40` at `0x80114C40` (292 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80114c40_FUN_80114c40.c`
///
/// # Arguments
/// * `object` - ice map object; `+0x04` nibble selects the `ice_A1` variant.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Calls `0x800690C0`, `0x800DF180`, `0x80239E30`, `0x80169D90`,
/// `0x80064BF0`, `0x8023A270`, `0x80167420`, `0x80167800` and `0x8016A8E0`;
/// writes `+0x3EC`, `+0x3F0`, `+0x430` and `+0x434`.
///
/// # Safety
/// `object` must be live and the archive loader record at `r13 - 0x5648` must
/// be initialised.
///
/// # Confidence
/// medium - every call and store is literal; the record sizes (`0x20`) and the
/// stack-record roles are taken from the export, the two `ice_A1` tables are
/// named from the file names in `main.elf`.
pub unsafe fn fn_80114c40(object: usize) {
    let index = platform::read_u32(object + 4) as usize & 0xF;
    platform::call5(
        W94_FUN_800690C0,
        (object + 0x3D0) as u32,
        0xFFFF_FFFF,
        W89_DATA_80377C48 as u32,
        0,
        0x20,
    );
    let loader = platform::read_u32(W89_SDA_5648) as usize;
    let archive = platform::call3(
        W89_FUN_800DF180,
        (loader + 4) as u32,
        W94_SDA_6388_TABLE as u32,
        W94_ICE_80323858 as u32,
    );
    platform::write_u32(object + 0x3EC, archive);
    let model = platform::call2(
        W94_FUN_80239E30,
        (object + 0x3EC) as u32,
        platform::read_u32(W94_ICE_80323828 + index * 4),
    );
    let mut model_word = crate::platform::GuestLocal::new( model);
    platform::call6(
        W94_FUN_80169D90,
        (object + 0x3F0) as u32,
        ((model_word.as_mut_ptr() as *mut u32)) as u32,
        (object + 0x3D0) as u32,
        0x20,
        1,
        0,
    );
    platform::call1(W94_FUN_80064BF0, (object + 0x3F0) as u32);
    let layout = platform::call2(
        W94_FUN_8023A270,
        (object + 0x3EC) as u32,
        platform::read_u32(W94_ICE_80323840 + index * 4),
    );
    platform::write_u32(object + 0x430, layout);
    let mut layout_word = crate::platform::GuestLocal::new( layout);
    platform::call6(
        W94_FUN_80167420,
        (object + 0x434) as u32,
        ((model_word.as_mut_ptr() as *mut u32)) as u32,
        ((layout_word.as_mut_ptr() as *mut u32)) as u32,
        (object + 0x3D0) as u32,
        0,
        1,
    );
    let mut bound = crate::platform::GuestLocal::new( platform::read_u32(object + 0x430));
    platform::call5(
        W94_FUN_80167800,
        (object + 0x434) as u32,
        (object + 0x3F0) as u32,
        ((bound.as_mut_ptr() as *mut u32)) as u32,
        0,
        0,
    );
    platform::call1(W94_FUN_8016A8E0, (object + 0x3D0) as u32);
}

/// Rebuilds the ice model's six-float placement from the `ice_inside` record.
///
/// Looks up the `ice_inside` entry for the `+0x04` nibble through the
/// `0x80168400`/`0x8023B200` pair, feeds its `+0x0C` word to `0x80168180`,
/// then writes the `+0x55C..+0x570` two-row placement and applies the
/// `0x548`-scaled half width to the back row.
///
/// # Original
/// - Ghidra: `FUN_80115100` at `0x80115100` (220 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80115100_FUN_80115100.c`
///
/// # Arguments
/// * `object` - ice map object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Calls `0x80168400`, `0x8023B200`, `0x80168180`; writes `+0x55C..+0x570`.
///
/// # Safety
/// `object` and its `+0x3F0` record must be live.
///
/// # Confidence
/// medium - the arithmetic and stores are literal; the `0x80168180` output is
/// modelled as a 0x20-byte scratch record because the export names two words
/// (`local_2C`, `local_1C`) of it separately.
pub unsafe fn fn_80115100(object: usize) {
    let index = platform::read_u32(object + 4) as usize & 0xF;
    let mut key = crate::platform::GuestLocal::new( [0u32; 4]);
    key[0] = platform::call1(W94_FUN_80168400, (object + 0x3F0) as u32);
    let handle = platform::call2(
        W94_FUN_8023B200,
        key.as_ptr() as u32,
        platform::read_u32(W94_ICE_80323878 + index * 4),
    ) as usize;
    let value = if handle == 0 {
        0
    } else {
        platform::read_u32(handle + 0xC)
    };
    let mut record = crate::platform::GuestLocal::new( [0u8; 0x20]);
    platform::call3(
        W94_FUN_80168180,
        (object + 0x3F0) as u32,
        value,
        record.as_mut_ptr() as u32,
    );
    let near = read_f32(record.as_ptr() as usize + 0xC);
    let far = read_f32(record.as_ptr() as usize + 0x1C);
    let row = read_f32(W94_R2_5C38_TEN) + read_f32(object + 0xB4) + read_f32(object + 0x54C);
    let spread = read_f32(W89_R2_5C4C_HALF) * read_f32(object + 0x548);
    platform::write_u32(object + 0x55C, near.to_bits());
    write_f32(object + 0x560, far);
    write_f32(object + 0x564, row);
    platform::write_u32(object + 0x568, near.to_bits());
    write_f32(object + 0x56C, far);
    write_f32(object + 0x570, row);
    if (platform::read_u32(object + 4) >> 4) & 1 != 0 {
        write_f32(object + 0x560, far + spread);
    }
    write_f32(object + 0x56C, read_f32(object + 0x56C) + spread);
}

/// Configures the course-background grid for the current variant.
///
/// Splits the `+0x04` nibble into `+0x4E4`, copies both player grid records,
/// classifies the three id halfwords into `+0x4E0`, records the `+0x480`
//// `+0x484` course dimensions, resolves the `0xD3` event object into
/// `+0x5EC`/`+0x5F0`, runs [`fn_80119060`] and seeds the 100-entry `+0x658`
/// halfword table.
///
/// # Original
/// - Ghidra: `FUN_80116110` at `0x80116110` (548 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80116110_FUN_80116110.c`
///
/// # Arguments
/// * `object` - course-background object.
///
/// # Returns
/// `1` on success, `0` when a grid class or the `0x80119060` step fails.
///
/// # Side effects
/// Calls `0x80116A30` (argument dropped by the export), `0x80118D80`,
/// `0x80118DA0`, `0x80116930`, `0x80162D50`, `0x80119060` and
/// `0x801613A0` one hundred times; writes many fields.
///
/// # Safety
/// `object + 0x4E0..+0x658 + 200` must be writable and the scene/player state
/// read by the callees must be live.
///
/// # Confidence
/// medium - the whole ladder is literal; `0x80116A30` is printed without its
/// argument, so `object` is passed explicitly, and the `0x80119060` return is
/// read although Ghidra declares that callee `void`.
pub unsafe fn fn_80116110(object: usize) -> u32 {
    platform::write_u32(object + 0x4E4, platform::read_u32(object + 4) & 0xF);
    platform::call1(W94_FUN_80116A30, object as u32);
    // observed: the export repeats the same getter three times; it is pure.
    let grid = fn_80118d80(object);
    let class = platform::call4(
        W94_FUN_80116930,
        object as u32,
        platform::read_u16(grid as usize + 0xA) as u32,
        platform::read_u16(grid as usize + 0xC) as u32,
        platform::read_u16(grid as usize + 0xE) as u32,
    );
    platform::write_u32(object + 0x4E0, class);
    if class == 0 {
        return 0;
    }
    let other = fn_80118da0(object);
    let second = platform::call4(
        W94_FUN_80116930,
        object as u32,
        platform::read_u16(other as usize + 0xA) as u32,
        platform::read_u16(other as usize + 0xC) as u32,
        platform::read_u16(other as usize + 0xE) as u32,
    );
    if second == 0 {
        if platform::read_u32(object + 0x4E4) == 0 {
            platform::write_u32(object + 0x3C0, 0);
        } else {
            platform::write_u32(object + 0x3BC, 0);
        }
    }
    let grid = fn_80118d80(object) as usize;
    write_f32(
        object + 0x480,
        signed_to_double(read_i16(grid + 8) as i32, W89_R2_5C08_BIAS) as f32,
    );
    let grid = fn_80118d80(object) as usize;
    write_f32(
        object + 0x484,
        signed_to_double(read_i16(grid + 6) as i32, W89_R2_5C08_BIAS) as f32,
    );
    let event = platform::call2(W94_FUN_80162D50, 0xD3, 0) as usize;
    if event == 0 {
        platform::write_u32(object + 0x5F0, 2);
        platform::write_u32(object + 0x5EC, platform::read_u32(W89_R2_5C1C_ZERO));
    } else {
        platform::write_u32(object + 0x5EC, platform::read_u32(event + 0xAC));
        let variant = platform::read_u32(event + 4) & 0xF;
        if variant == 0 {
            platform::write_u32(object + 0x5F0, 0);
        } else if variant == 1 {
            platform::write_u32(object + 0x5F0, 1);
        } else if variant == 2 {
            platform::write_u32(object + 0x5F0, 2);
        }
    }
    if fn_80119060(object) == 0 {
        return 0;
    }
    platform::write_u32(object + 0xDC, platform::read_u32(W89_R2_5C20_ONE));
    platform::write_u32(object + 0xE0, platform::read_u32(W89_R2_5C20_ONE));
    platform::write_u32(object + 0xE4, platform::read_u32(W89_R2_5C20_ONE));
    platform::write_u32(object + 0x4E8, platform::read_u32(W89_R2_5C1C_ZERO));
    platform::write_u32(object + 0x4EC, platform::read_u32(W89_R2_5C1C_ZERO));
    platform::write_u32(object + 0x4F0, platform::read_u32(W89_R2_5C1C_ZERO));
    platform::write_u8(object + 0x62C, 0);
    platform::write_u16(object + 0x5F4, 0xFFFF);
    platform::write_u16(object + 0x5F6, 0xFFFF);
    for index in 0..100usize {
        let value = platform::call1(W94_FUN_801613A0, 0x1_0000) as u16;
        platform::write_u16(object + 0x658 + index * 2, value);
    }
    1
}

/// Allocates the `0x8C50`-byte tile-record array and fills every slot.
///
/// Creates the array through `0x802B9250`/`0x802DC7E0` with the
/// `0x80117C10` release hook, stores it at `+0x3B8`, then fills 34 by 22
/// records of `0x30` bytes: each record has three zero/limit triples separated
/// by a `9` marker. The height limit is `-7000.0f` for variant `0` and
/// `-8000.0f` for variant `1`.
///
/// # Original
/// - Ghidra: `FUN_80117AC0` at `0x80117AC0` (312 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80117ac0_FUN_80117ac0.c`
///
/// # Arguments
/// * `object` - course-background object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Allocates `0x8C50` bytes, writes `+0x3B8`, fills the array, then calls
/// [`fn_8011a1e0`].
///
/// # Safety
/// `object` must be live and the allocator must succeed before the fill runs.
///
/// # Confidence
/// high - the allocation, the two constants and the two nested loops are
/// literal.
pub unsafe fn fn_80117ac0(object: usize) {
    let raw = platform::call1(FUN_802B9250, 0x8C50);
    let base = platform::call5(
        W94_FUN_802DC7E0,
        raw,
        W94_CODE_80117C00 as u32,
        W94_FUN_80117C10 as u32,
        0x10,
        0x8C4,
    ) as usize;
    platform::write_u32(object + 0x3B8, base as u32);
    let zero = platform::read_u32(W89_R2_5C1C_ZERO);
    let high = platform::read_u32(W94_R2_5BFC_NEG7000);
    let low = platform::read_u32(W94_R2_5BF8_NEG8000);
    let variant = platform::read_u32(object + 0x4E4);
    let mut record = base;
    for _ in 0..0x22 {
        for _ in 0..0x16 {
            if variant == 0 {
                platform::write_u32(record, zero);
                platform::write_u32(record + 4, zero);
                platform::write_u32(record + 8, high);
            } else if variant == 1 {
                platform::write_u32(record, zero);
                platform::write_u32(record + 4, zero);
                platform::write_u32(record + 8, low);
            }
            platform::write_u32(record + 0xC, 9);
            if variant == 0 {
                platform::write_u32(record + 0x10, zero);
                platform::write_u32(record + 0x14, zero);
                platform::write_u32(record + 0x18, high);
            } else if variant == 1 {
                platform::write_u32(record + 0x10, zero);
                platform::write_u32(record + 0x14, zero);
                platform::write_u32(record + 0x18, low);
            }
            platform::write_u32(record + 0x1C, 9);
            if variant == 0 {
                platform::write_u32(record + 0x20, zero);
                platform::write_u32(record + 0x24, zero);
                platform::write_u32(record + 0x28, high);
            } else if variant == 1 {
                platform::write_u32(record + 0x20, zero);
                platform::write_u32(record + 0x24, zero);
                platform::write_u32(record + 0x28, low);
            }
            platform::write_u32(record + 0x2C, 9);
            record += 0x30;
        }
    }
    fn_8011a1e0(object);
}

/// Marks the `A..F` tile flags of both players from the archive name list.
///
/// Walks every child of the layout archive, resolves its name through
/// `0x802DF098` and, for the single-letter names `A..F`, sets the matching bit
/// in two byte fields.
