// --- helpers for the actor's own `+0x60` vtable --------------------------
/// Calls slot `slot` of the actor's `+0x60` vtable with no explicit argument.
///
/// # Safety
/// `object + 0x60` must hold a live vtable and the slot must accept `(object)`.
#[inline]
unsafe fn wm_actor_vcall0(object: usize, slot: usize) -> u32 {
    let vtable = platform::read_u32(object + 0x60) as usize;
    let entry = platform::read_u32(vtable + slot) as usize;
    platform::call1(entry, object as u32)
}

/// Calls slot `slot` of the actor's `+0x60` vtable with one word.
///
/// # Safety
/// `object + 0x60` must hold a live vtable and the slot must accept
/// `(object, a)`.
#[inline]
unsafe fn wm_actor_vcall1(object: usize, slot: usize, a: u32) -> u32 {
    let vtable = platform::read_u32(object + 0x60) as usize;
    let entry = platform::read_u32(vtable + slot) as usize;
    platform::call2(entry, object as u32, a)
}

/// Calls slot `slot` of the actor's `+0x60` vtable with two words.
///
/// # Safety
/// `object + 0x60` must hold a live vtable and the slot must accept
/// `(object, a, b)`.
#[inline]
unsafe fn wm_actor_vcall2(object: usize, slot: usize, a: u32, b: u32) -> u32 {
    let vtable = platform::read_u32(object + 0x60) as usize;
    let entry = platform::read_u32(vtable + slot) as usize;
    platform::call3(entry, object as u32, a, b)
}

/// Starts or continues the actor's landing/skid action.
///
/// When the actor is idle, not in the `0x4000` action bit and not in action
/// `4`, runs the `0x800556F0` pre-step. The `0x80146FA0` kind decides whether
/// the full branch (height `+0xEC`, timer `+0x10C`, event `0x803762F0` with
/// argument `1`, `0x80127F10`, sub-controller event `3`, state byte `+0x1569`
/// and action bit `0` cleared) or the short branch (only `+0x10C` and event
/// `0x80376230` with argument `2`) runs.
///
/// # Original
/// - Ghidra: `FUN_80146D00` at `0x80146D00` (288 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80146d00_FUN_80146d00.c`
///
/// # Arguments
/// * `param_1` - height written to `+0xEC`.
/// * `param_2` - timer written to `+0x10C`.
/// * `param_3` - WorldMap player actor.
///
/// # Returns
/// `1` when the action was accepted, `0` when the guards reject it.
///
/// # Side effects
/// Calls `0x8004DD00`, `0x80056CF0`, `0x800556F0`, `0x80146FA0`, `0x80127F10`,
/// `0x8005E3B0` and `0x80056CB0`; two `+0x294` slot posts; writes `+0xEC`,
/// `+0x10C`, `+0x1569` and `+0x10D4`.
///
/// # Safety
/// `param_3` must be a live actor with a readable `+0x60` vtable.
///
/// # Confidence
/// medium - every guard, store and call is literal; the two event records are
/// named only by address and the slot arity is inferred from the export.
pub unsafe fn fn_80146d00(param_1: f64, param_2: f64, param_3: usize) -> u32 {
    if call0_u32(FUN_8004DD00) == 0
        && platform::call2(FUN_80056CF0, param_3 as u32, 4) == 0
        && (platform::read_u32(param_3 + 0x10D4) & 0x4000) == 0
    {
        platform::call1(W95_FUN_800556F0, param_3 as u32);
        let kind = fn_80146fa0(param_3);
        if kind == 0 || (platform::read_u32(param_3 + 0x10D4) & 0x1800_0000) != 0 {
            write_f32(param_3 + 0xEC, param_1 as f32);
            write_f32(param_3 + 0x10C, param_2 as f32);
            wm_actor_vcall2(param_3, 0x294, G_803762F0 as u32, 1);
            fn_80127f10(param_3);
            platform::call2(FUN_8005E3B0, (param_3 + 0xEA4) as u32, 3);
            platform::write_u8(param_3 + 0x1569, 4);
            platform::write_u32(
                param_3 + 0x10D4,
                platform::read_u32(param_3 + 0x10D4) & 0xFFFF_FFFE,
            );
            platform::call2(FUN_80056CB0, param_3 as u32, 0xA7);
        } else {
            write_f32(param_3 + 0x10C, param_2 as f32);
            wm_actor_vcall2(param_3, 0x294, G_80376230 as u32, 2);
        }
        return 1;
    }
    0
}

/// Stores the two motion values and refreshes the ground-facing byte.
///
/// Copies `param_1` into `+0xEC` and `param_2` into both `+0x10C` and
/// `+0x110`. The byte at `+0x348` becomes `1` when `param_2` is at or below the
/// `r2 - 0x5928` zero float, otherwise `0`, and event `0x803764B0` is posted
/// with `param_4`.
