        && platform::call1(FUN_8005E780, (param_1 + 0xEA4) as u32) != 0
        && (platform::read_u32(param_1 + 0x10D4) & 0x4000) == 0
        && platform::call2(FUN_80056CF0, param_1 as u32, 0x9F) != 0
