///
/// # Confidence
/// high - identical instruction sequence to `0x8010BF30`.
pub unsafe fn fn_8010ee80(this: usize, free_base: i32) -> usize {
    if this != 0 {
        platform::call2(FUN_8015F800, this as u32, 0);
        if free_base > 0 {
            platform::call1(FUN_802B9280, this as u32);
        }
    }
    this
}

