/// Calls a PowerPC function with the EABI prototype `(f64, f64) -> u32`.
///
/// # Safety
/// `addr` must point at a function with this prototype.
#[inline]
unsafe fn w98_call_f64_f64_u32(addr: usize, a: f64, b: f64) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f64, f64) -> u32);
    f(a, b)
}

/// Calls a PowerPC function with the EABI prototype `(f64, f64) -> i16`.
///
/// `0x801611C0` is declared `short` in the export, so the result is truncated
/// to 16 bits before the caller negates it.
///
/// # Safety
/// `addr` must point at a function with this prototype.
#[inline]
unsafe fn w98_call_f64_f64_i16(addr: usize, a: f64, b: f64) -> i16 {
    let f = crate::platform::guest_fn!(addr, fn(f64, f64) -> i16);
    f(a, b)
}

/// Calls a PowerPC function with the EABI prototype `(f64, f64, u32, u32) -> u32`.
///
/// # Safety
/// `addr` must point at a function with this prototype.
#[inline]
unsafe fn w98_call_f64_f64_u32_u32(addr: usize, a: f64, b: f64, c: u32, d: u32) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f64, f64, u32, u32) -> u32);
    f(a, b, c, d)
}

/// Calls virtual slot `slot` of `object` with three `f64` arguments.
///
/// Used for the ride object's `+0x5C` "apply vector" slot when the export shows
/// no trailing integer argument.
///
/// # Safety
/// `object` must be live and the slot must accept `(object, f64, f64, f64)`.
#[inline]
unsafe fn w98_vcall_f64x3(object: usize, slot: usize, a: f64, b: f64, c: f64) -> u32 {
    let vtable = platform::read_u32(object) as usize;
    let entry = platform::read_u32(vtable + slot) as usize;
    let f = crate::platform::guest_fn!(entry, fn(usize, f64, f64, f64) -> u32);
    f(object, a, b, c)
}

/// Converts a value reinterpreted as a signed 32-bit integer to `f64` through
/// the compiler's `0x4330000080000000` bias idiom.
///
/// # Safety
/// Reads the double constant at [`W98_R2_58E0_BIAS`], which must be readable.
#[inline]
unsafe fn w98_s32_to_f64(value: u32) -> f64 {
    unsigned_to_double(value) - read_f64(W98_R2_58E0_BIAS)
}

/// Calls a PowerPC function with the EABI prototype
/// `(f64, f64, u32, u32, u32) -> u32`.
///
/// # Safety
/// `addr` must point at a function with this prototype.
#[inline]
unsafe fn w98_call_f64x2_u32x3(addr: usize, a: f64, b: f64, c: u32, d: u32, e: u32) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn(f64, f64, u32, u32, u32) -> u32);
    f(a, b, c, d, e)
}

/// Clamps the ride's lean magnitude and converts it into a signed 16-bit angle.
///
/// Reads `+0x2068` (a lean/speed magnitude), raises it to `0.1` when its
/// absolute value is smaller, pokes both sub-controller predicates, and passes
/// the magnitude plus `+0x206C` to `0x801611C0`. The returned short is
/// mirrored around `0x4000` (`0x4000 - value`), so a straight-ahead result of
