    platform::write_u32(this + 0x114, zero);
    platform::write_u32(this + 0x10C, zero);
    platform::write_u32(this + 0x11C, zero);
    platform::write_u32(this + 0x110, zero);
    platform::write_u32(this + 0xE8, zero);
    platform::write_u32(this + 0xEC, zero);
    platform::write_u32(this + 0x1C9C, 0);
    if platform::read_u8(this + 0x1035) == 1 {
        platform::write_u16(this + 0x1C98, 0x8000);
    } else {
        platform::write_u16(this + 0x1C98, 0);
    }
    let variant = platform::read_u32(this + 0x14A0);
    platform::write_u16(this + 0x102, platform::read_u16(this + 0x1C98));
    platform::write_u8(this + 0x2A8, platform::read_u8(this + 0x2A8) | 1);
