    let facing = platform::read_u8(this + 0x348) as u32;
    let angle = vcall60_1(this, 0x444, facing);
    platform::write_u16(this + 0x102, angle as u16);
    if platform::read_u32(this + 0x10D8) & 0x100 == 0 {
        vcall60_2(this, 0x294, G_80375C2C as u32, 0);
    } else {
        vcall60_2(this, 0x294, DATA_80375EAC as u32, 3);
    }
