    let entry = (platform::read_u32(W98_R2_5790_DIR_TABLE + direction * 4) & 0xFF) as usize;
    let ride = platform::read_u32(this + 0x2A64) as usize;
    w98_vcall_f64x3(
        ride,
        0x5C,
        read_f32(WM_VECTOR_TABLE + entry * 12) as f64,
        read_f32(WM_VECTOR_TABLE + entry * 12 + 4) as f64,
        zero as f64,
    );
    platform::write_u8(this + 0x1DC8, platform::read_u8(this + 0x1DC8) ^ 1);
    platform::call3(W98_FUN_80057E70, this as u32, 0x12F, 0);
