            ((read_f32(this + 0xAC) as f64) - target as f64).abs() as f32 as f64;
        let roll = w100_float_probe();
        let mut steer = false;
        if (read_f32(R2_5CC0_THREE) * span) as f64 <= distance {
            if (read_f32(R2_5CB4_FIVE) * span) as f64 <= distance {
                steer = true;
            } else if roll < read_f32(W100_R2_5CA8_0_7) as f64 {
                steer = true;
            }
        } else if roll < read_f32(R2_5CD0_HALF) as f64 {
            steer = true;
        }
