/// Steps one rail accumulator and its matching speed by a signed amount.
///
/// `direction` is `-1` for the subtraction branches and `+1` for the addition
/// branches; the fast or slow step is chosen from the sign of the accumulator.
///
/// # Safety
/// `this` must be live and all four constant slots readable.
unsafe fn w100_rail_step(
    this: usize,
    position: usize,
    speed: usize,
    fast_position: usize,
    fast_speed: usize,
    slow_position: usize,
    slow_speed: usize,
    direction: i32,
) {
    let value = read_f32(this + position);
    let fast = if direction < 0 {
        0.0 <= value
    } else {
        value <= 0.0
    };
    let (step_position, step_speed) = if fast {
        (read_f32(fast_position), read_f32(fast_speed))
    } else {
        (read_f32(slow_position), read_f32(slow_speed))
    };
    write_f32(this + position, value + direction as f32 * step_position);
    write_f32(this + speed, read_f32(this + speed) + direction as f32 * step_speed);
}

