/// of the `0x8004CA60` tail call, so the actor is passed.
pub unsafe fn fn_8012ab00(object: usize) {
    if read_f32(object + 0x10C) == read_f32(R2_5928_ZERO) {
        return;
    }
    if (platform::read_u32(object + 0x10D4) & 0x8000) != 0
        && platform::read_i32(object + 0x1090) == 3
    {
        platform::call3(W102_FUN_80057F60, object as u32, 0xEA, 0);
        return;
    }
    platform::call1(W102_FUN_8004CA60, object as u32);
}

/// Drives the three-state swim/water-entry ladder.
///
/// Clears action `0x4D` when `+0x14A8` is zero, then runs `0x8004C480`,
/// `0x8004B730`, `0x8004C450` and the `0x448` slot. State `0` posts sound
/// `0x14F`, arms `+0x14AC` with `0x802F58A4`, and either runs the model's `0x8C`
/// slot and turns the actor through the `0x84` slot (bit `0x60` of `+0x10D4`)
/// or enters the `0xEA`/`0x84` variant. State `1` runs the `0x8C` slot with
/// `0.5` and picks `0x800484B0`/`0x80048410`. State `2` ramps the `0x8C`
/// argument by `0.5 * |+0x10C|` clamped to `[0.1, 1.0]` with the entry's sign,
/// and the shared tail writes `+0x110` and posts `0x80375D2C` when the model
/// finished. A busy `0x8005E6F0` runs the `0x3FC` slot instead.
///
/// # Original
/// - Ghidra: `FUN_8012AE60` at `0x8012AE60` (868 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8012ae60_FUN_8012ae60.c`
///
/// # Arguments
/// * `object` - WorldMap player actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Up to four model slots, one sound, one `+0x394` event and `+0x10C`/`+0x110`
//// `+0x14AC`/`+0x156C` stores.
///
/// # Safety
/// `object` must be live with a readable `+0x2A64` model.
///
/// # Confidence
/// medium - the ladder, the sign test and the clamps are literal; the model's
/// `0x84` slot is called without the `f1` operand the export drops on the
/// first path.
pub unsafe fn fn_8012ae60(object: usize) {
    if platform::read_i32(object + 0x14A8) == 0 {
        platform::call2(FUN_80056CB0, object as u32, 0x4D);
    }
    platform::call1(FUN_8004C480, object as u32);
    platform::call1(FUN_8004B730, object as u32);
    platform::call1(FUN_8004C450, object as u32);
    vcall60_0(object, 0x448);
    let model = platform::read_u32(object + 0x2A64) as usize;
    let busy = platform::read_i32(object + 0x14AC) != 0
        && platform::call1(W102_FUN_8005E6F0, (object + 0xEA4) as u32) != 0;
    if !busy {
        let state = platform::read_i32(object + 0x14A4);
        if state == 0 {
            platform::call3(W102_FUN_80057F60, object as u32, 0x14F, 0);
            let armed = platform::read_i32(object + 0x14AC);
            if armed == 0 {
                write_f32(object + 0x11C, read_f32(R2_5928_ZERO));
                platform::write_u32(object + 0x156C, platform::read_u32(W102_R2_58A4));
                vcall0(model, 0x8C);
                if (platform::read_u32(object + 0x10D4) & 1) == 0 {
                    if (platform::read_u32(object + 0x10D4) & 0x60) != 0 {
                        let turned = platform::read_u8(object + 0x348) ^ 1;
                        platform::write_u32(object + 0x14AC, 1);
                        platform::write_u8(object + 0x348, turned);
                        write_f32(
                            object + 0x10C,
                            read_f32(G_SIDE_TABLE_8042B840 + turned as usize * 4),
                        );
                        write_f32(object + 0xEC, read_f32(R2_5928_ZERO));
                        vcall0(model, 0x84);
                    }
                } else {
                    write_f32(
                        object + 0x10C,
                        read_f32(
                            G_SIDE_TABLE_8042B840
                                + platform::read_u8(object + 0x348) as usize * 4,
                        ),
                    );
                    platform::write_u32(object + 0x14AC, 1);
                    write_f32(object + 0xEC, read_f32(R2_5918_TWO));
                    vcall_f64(model, 0x84, read_f32(R2_5928_ZERO) as f64);
                }
            } else if armed == 1 {
                vcall_f64(model, 0x8C, read_f32(R2_591C_HALF) as f64);
                if (platform::read_u32(object + 0x10D4) & 1) != 0 {
                    if platform::call1(W102_FUN_8005E500, (object + 0xEA4) as u32) == 0 {
                        platform::call1(W102_FUN_800484B0, object as u32);
                    } else {
                        platform::call1(W102_FUN_80048410, object as u32);
                    }
                }
            } else if armed == 2 {
                if (platform::read_u32(object + 0x10D4) & 1) == 0 {
                    vcall60_2(object, 0x294, W102_DAT_80375CAC as u32, 0);
                    return;
                }
                let mut step = read_f32(R2_591C_HALF) as f64
                    * read_f32(object + 0x10C).abs() as f64;
                if (read_f32(R2_58FC_ONE) as f64) < step {
                    step = read_f32(R2_58FC_ONE) as f64;
                }
                if step < read_f32(R2_5920_0_1) as f64 {
                    step = read_f32(R2_5920_0_1) as f64;
                }
                if read_f32(object + 0x10C)
                    * read_f32(
                        G_SIDE_TABLE_8042B840 + platform::read_u8(object + 0x348) as usize * 4,
                    )
                    < read_f32(R2_5928_ZERO)
                {
                    step = -step;
                }
                vcall_f64(model, 0x8C, step);
                if read_f32(object + 0x10C).abs() < read_f32(W102_R2_58A0) {
                    if platform::call1(W102_FUN_8005E500, (object + 0xEA4) as u32) == 0 {
                        platform::call1(W102_FUN_800484B0, object as u32);
                    } else {
                        platform::call1(W102_FUN_80048410, object as u32);
                    }
                }
            }
        } else if state != 1 {
            if state != 2 {
                return;
            }
            write_f32(object + 0x10C, read_f32(R2_5928_ZERO));
            write_f32(object + 0x110, read_f32(R2_5928_ZERO));
            if platform::call1(W102_FUN_80169020, (model + 0x28) as u32) == 0 {
                return;
            }
            platform::call2(W102_FUN_800488F0, object as u32, 1);
            return;
        }
        write_f32(object + 0x110, read_f32(R2_5928_ZERO));
        if platform::call1(W102_FUN_80169020, (model + 0x28) as u32) != 0 {
            vcall60_2(object, 0x294, W102_DAT_80375D2C as u32, 1);
        }
    } else {
        w102_vcall60_stage(
            object,
            0x3FC,
            read_f32(R2_7838_3_628) as f64,
            (read_f32(R2_58A8_0_8) * read_f32(object + 0x10C)) as f64,
            object as u32,
            1,
            0,
            1,
        );
    }
}

/// Starts the water-entry state and seeds both `+0x1A1C` timers.
///
/// Zeroes `+0x14A4`, stores the `0x8004B460` result (the entry speed) at
/// `+0x110`, and with `+0x10D4` bit `0` and `0x8004B1C0` clear clamps the
/// projected `+0x1A24` speed between `0x802F5898` and `4.0` before latching
/// `+0x1A20 = 1`. It then clears action `0xC3` when the actor is at or below
/// the `+0x1138 - 4.0` height, seeds `+0x14A8 = 8`, runs [`fn_8012e5a0`],
/// raises six actions, posts stream event `0x8B`, runs pose `0x1B` and seeds
/// `+0x1A18 = 0x1E` and `+0x1A1C = (int)0x802F5748`.
///
/// # Original
/// - Ghidra: `FUN_8012B1D0` at `0x8012B1D0` (480 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8012b1d0_FUN_8012b1d0.c`
///
/// # Arguments
/// * `object` - WorldMap player actor.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Nine action writes, one stream event, one pose call and seven field writes.
///
/// # Safety
/// `object` must be live with a readable `+0x2A64` model.
///
/// # Confidence
/// medium - the ladder and stores are literal; the `unaff_GQR0` block's
/// `ldexpf` result is discarded.
pub unsafe fn fn_8012b1d0(object: usize) {
    platform::write_u32(object + 0x14A4, 0);
    let speed = call_u32_f64(W102_FUN_8004B460, object as u32) as f32;
    write_f32(object + 0x110, speed);
    if (platform::read_u32(object + 0x10D4) & 1) != 0
        && platform::call1(W102_FUN_8004B1C0, object as u32) == 0
    {
        let magnitude = read_f32(object + 0x10C).abs() as f64;
        let record = platform::call1(W102_FUN_80057650, object as u32) as usize;
        let mut ratio = read_f32(W102_R2_589C)
            + (magnitude / read_f32(record + 8) as f64) as f32;
        if read_f32(R2_58FC_ONE) < ratio {
            ratio = read_f32(R2_58FC_ONE);
        }
        if ratio < read_f32(R2_591C_HALF) {
            ratio = read_f32(R2_591C_HALF);
        }
        let limit = read_f32(R2_5914_FOUR);
        let mut value = read_f32(object + 0x10C)
            + ratio
                * read_f32(
                    G_SIDE_TABLE_8042B840 + platform::read_u8(object + 0x348) as usize * 4,
                );
        if limit < value {
            value = limit;
        }
        if value < read_f32(W102_R2_5898) {
            value = read_f32(W102_R2_5898);
        }
        write_f32(object + 0x1A24, value);
        platform::write_u32(object + 0x1A20, 1);
    }
    if read_f32(object + 0x1138) - read_f32(R2_5914_FOUR) <= read_f32(object + 0xB0) {
        platform::call2(FUN_80056C70, object as u32, 0xC3);
    }
    platform::write_u32(object + 0x14A8, 8);
    fn_8012e5a0(object);
    for action in [0x30u32, 0x97, 0x9F, 0xA2, 0x3C, 0x88] {
        platform::call2(FUN_80056C70, object as u32, action);
    }
    let model = platform::read_u32(object + 0x2A64) as usize;
    vcall_f64_f64_f64_u32(
        model,
        0x5C,
        read_f32(W102_DAT_80371450) as f64,
        read_f32(W102_DAT_80371450 + 4) as f64,
        read_f32(R2_5928_ZERO) as f64,
        0x8B,
    );
    vcall60_2(object, 0x434, 0x1B, 0);
    let frames = read_f32(W102_DAT_802F5748) as i32;
    platform::write_u32(object + 0x1A18, 0x1E);
    platform::write_i32(object + 0x1A1C, frames);
}

/// Commits or cancels the water entry.
///
/// With `+0x10D4` bit `0` set and `0x8005E6F0` busy it needs an entry whose
/// slot differs from `+0x348`: the `0x3FC` slot runs with
/// `(+0x10C * 0.8)`. Otherwise it posts stream event `0x8C`, sound `0x121`,
/// sets action `0x3D`, and recomputes `+0xEC` from `|+0x10C|` with the three
/// `0x802F574C..0x802F5754` constants, clamped between `0x802F574C` and
/// `0x802F5750`.
///
/// # Original
/// - Ghidra: `FUN_8012B440` at `0x8012B440` (368 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8012b440_FUN_8012b440.c`
///
/// # Arguments
/// * `object` - WorldMap player actor.
///
/// # Returns
/// `0` when the entry is not committed, `1` otherwise.
///
/// # Side effects
/// One stream event, one sound, one action and up to two speed stores.
///
/// # Safety
/// `object` must be live; `+0xEA4` must be a live sub-controller.
///
/// # Confidence
/// medium - the guard ladder and the clamp are literal.
pub unsafe fn fn_8012b440(object: usize) -> u32 {
    if (platform::read_u32(object + 0x10D4) & 1) == 0
        || platform::call1(W102_FUN_8005E6F0, (object + 0xEA4) as u32) == 0
    {
        return 0;
    }
    let mut slot = crate::platform::GuestLocal::<u32>::new( 0xFFFF_FFFFu32);
    let free = platform::call1(W102_FUN_8005E500, (object + 0xEA4) as u32) == 0
        && (platform::call2(
            W102_FUN_8005E7A0,
            (object + 0xEA4) as u32,
            ((slot.as_mut_ptr() as *mut u32)) as u32,
        ) == 0
            || *slot != platform::read_u8(object + 0x348) as u32);
    if free {
        w102_vcall60_stage(
            object,
            0x3FC,
            read_f32(R2_7838_3_628) as f64,
            (read_f32(R2_58A8_0_8) * read_f32(object + 0x10C)) as f64,
            object as u32,
            1,
            0,
            1,
        );
    } else {
        let model = platform::read_u32(object + 0x2A64) as usize;
        vcall_f64_f64_f64_u32(
            model,
            0x5C,
            read_f32(W102_DAT_8037145C) as f64,
            read_f32(W102_DAT_8037145C + 4) as f64,
            read_f32(R2_5928_ZERO) as f64,
            0x8C,
        );
        platform::call3(W102_FUN_80057E70, object as u32, 0x121, 0);
        platform::call2(FUN_80056C70, object as u32, 0x3D);
        let gain = read_f32(W102_DAT_802F5754);
        let base = read_f32(W102_DAT_802F5750);
        let cap = read_f32(W102_DAT_802F574C);
        let start = read_f32(R2_58A4_1_5);
        platform::write_u32(
            object + 0x10D4,
            platform::read_u32(object + 0x10D4) & !1,
        );
        let value = base + (read_f32(object + 0x10C).abs() - start) * gain;
        write_f32(object + 0xEC, value);
        if cap < value {
            write_f32(object + 0xEC, cap);
        }
        if read_f32(object + 0xEC) < base {
            write_f32(object + 0xEC, base);
        }
    }
    1
}

