/// Commits a slide contact and publishes the corrected height.
///
/// # Original
/// - Ghidra: `FUN_801396C0` at `0x801396C0` (268 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801396c0_FUN_801396c0.c`
///
/// # Arguments
/// * `height` - incoming height; replaced by `0.0` when the contact lowers the
///   actor.
/// * `speed` - second double forwarded to `0x80146D00`.
/// * `object` - actor whose `+0xAC..+0xC0` position is corrected.
///
/// # Returns
/// The `0x80146D00` result, or `0` when the sub-controller released the frame.
///
/// # Side effects
/// Calls `0x8005E780`, `0x80075CA0`, the `+0xF8` height slot and
/// `0x80055D00`; may write `+0xB0` and `+0xB8..+0xC0`.
///
/// # Safety
/// `object`, its `+0xEA4` sub-controller and its `+0x60` vtable must be live.
///
/// # Confidence
/// medium - the probe, the height subtraction and the three position stores are
/// literal; the `+0xF8` slot is read as a double because the export casts the
/// call result directly.
pub unsafe fn fn_801396c0(height: f64, speed: f64, object: u32) -> u32 {
    let object = object as usize;
    if platform::call1(FUN_8005E780, (object + 0xEA4) as u32) == 0 {
        return 0;
    }
    let mut record = crate::platform::GuestLocal::new( [0u32; 3]);
    record[0] = platform::read_u32(object + 0xAC);
    record[1] = (read_f32(W98_R2_58FC_ONE) + read_f32(object + 0xB0)).to_bits();
    record[2] = platform::read_u32(object + 0xB4);
    let mut surface = crate::platform::GuestLocal::<f32>::new( 0f32);
    let mut value = height;
    if platform::call4(
        W102_FUN_80075CA0,
        record.as_ptr() as u32,
        ((surface.as_mut_ptr() as *mut f32)) as u32,
        platform::read_u8(object + 0x38F) as u32,
        1,
    ) != 0
    {
        let vtable = platform::read_u32(object + 0x60) as usize;
        let entry = platform::read_u32(vtable + 0xF8) as usize;
        let height_of = crate::platform::guest_fn!(entry, fn(usize) -> f64);
        let drop = height_of(object);
        *surface -= (read_f32(W98_R2_58FC_ONE) as f64 + drop) as f32;
        if *surface < read_f32(object + 0xB0) {
            write_f32(object + 0xB0, *surface);
            value = read_f32(W98_R2_5928_ZERO) as f64;
            platform::write_u32(object + 0xB8, platform::read_u32(object + 0xAC));
            write_f32(object + 0xBC, *surface);
            platform::write_u32(object + 0xC0, platform::read_u32(object + 0xB4));
        }
    }
    platform::call1(W102_FUN_80055D00, object as u32);
    call_f64_f64_u32_u32_ret(W104_FUN_80146D00, value, speed, object as u32, 0)
}

/// Clears the ride attach flag and applies the dismount record.
///
/// # Original
/// - Ghidra: `FUN_8013A880` at `0x8013A880` (160 bytes)
