    w103_call_f64x3_u32(
        W103_FUN_801C0BD0,
        read_f32(R2_58BC_NEG1) as f64,
        read_f32(W98_R2_5914_FOUR) as f64,
        read_f32(W98_R2_5914_FOUR) as f64,
        tilt.as_mut_ptr() as u32,
    );
    platform::call3(
        W103_FUN_801C0540,
        matrix.as_ptr() as u32,
        tilt.as_ptr() as u32,
        matrix.as_ptr() as u32,
    );
