unsafe fn w106_call_f64x6_u32_u32_u32(
    addr: usize,
    a: f64,
    b: f64,
    c: f64,
    d: f64,
    e: f64,
    f: f64,
    g: u32,
    h: u32,
    i: u32,
) {
    let call = crate::platform::guest_fn!(addr, fn(f64, f64, f64, f64, f64, f64, u32, u32, u32));
    call(a, b, c, d, e, f, g, h, i)
}

