    let step = read_f32(this + 0x5CC);
    let mut speed = read_f32(this + 0x10C);
    if speed <= limit {
        if speed < limit {
            speed += step;
            write_f32(this + 0x10C, speed);
            if limit <= speed {
                speed = limit;
                write_f32(this + 0x10C, speed);
            }
        }
    } else {
        speed -= step;
        write_f32(this + 0x10C, speed);
        if speed <= limit {
            speed = limit;
            write_f32(this + 0x10C, speed);
        }
    }
    let phase = read_i16(this + 0x104) as u16 as f64;
    let weight = ((read_f32(R2_5AF8_INV256) as f64) * phase) as f32 as f64;
    let cosine = call_f64_f64(FUN_80237BD0, weight);
    let sine = call_f64_f64(W106_FUN_80237C40, weight);
