/// Copies one four-word motion group to `base`.
///
/// # Safety
/// `base` must be a writable four-word block.
unsafe fn write_motion_group(base: usize, group: &[u32; 4]) {
    for word in 0..4usize {
        platform::write_u32(base + word * 4, group[word]);
    }
}

