const W110_G_803222D8: usize = 0x8032_22D8;
const W110_G_803222DC: usize = 0x8032_22DC;
const W110_G_803222E0: usize = 0x8032_22E0;
/// `0x803222CC`: separate goal-manager global that receives the SDA word 23.
const W110_G_803222CC: usize = 0x8032_22CC;
/// `r2 - 0x5D88` / `-0x5D84` / `-0x5D80` = `0x8042D2F8..0x8042D300`.
const W110_R2_5D88: usize = SDA2_BASE - 0x5D88;
const W110_R2_5D84: usize = SDA2_BASE - 0x5D84;
const W110_R2_5D80: usize = SDA2_BASE - 0x5D80;

/// `0x80322880` / `0x80322884`: pair copied once from the SDA by the warning
/// initialiser. `// unknown:` role; the guard byte is the only consumer seen.
const W110_G_80322880: usize = 0x8032_2880;
const W110_G_80322884: usize = 0x8032_2884;
/// `r2 - 0x6398` / `-0x6394` = `0x8042CCE8` / `0x8042CCEC`.
const W110_R2_6398: usize = SDA2_BASE - 0x6398;
const W110_R2_6394: usize = SDA2_BASE - 0x6394;
/// `r13 - 0x539C` = `0x8042A2E4`: one-shot guard byte.
const W110_SDA_539C_BYTE: usize = SDA_BASE - 0x539C;

// `0x8010BF10` is not a function entry, so it is carried as a raw code
// address, exactly as Ghidra prints it.

/// Fills one 0x40-byte state record and registers its dispatch descriptor.
///
/// Reads the nine handler words in the original order (`+0x18`, `+0x1C`,
/// `+0x20`, `+0x0C`, `+0x10`, `+0x14`, `+0x00`, `+0x04`, `+0x08`), constructs
/// the record with `0x8015F7C0(state, name)`, overwrites the base vtable and
/// stores the nine words at `+0x0C..+0x2C`. Finally `0x802DC780` prepends the
/// descriptor at `descriptor` to the global list.
///
/// # Safety
/// `state` must be writable for 0x30 bytes, `name` readable, and `descriptor`
/// writable for 12 bytes.
unsafe fn w110_fill_state_record(
    state: usize,
    name: usize,
    template: usize,
    vtable: usize,
    handler: usize,
    descriptor: usize,
) {
    let w18 = platform::read_u32(template + 0x18);
    let w1c = platform::read_u32(template + 0x1C);
    let w20 = platform::read_u32(template + 0x20);
    let w0c = platform::read_u32(template + 0x0C);
    let w10 = platform::read_u32(template + 0x10);
    let w14 = platform::read_u32(template + 0x14);
    let w00 = platform::read_u32(template);
    let w04 = platform::read_u32(template + 0x04);
    let w08 = platform::read_u32(template + 0x08);
    platform::call2(W110_FUN_8015F7C0, state as u32, name as u32);
    platform::write_u32(state, vtable as u32);
    platform::write_u32(state + 0x0C, w18);
    platform::write_u32(state + 0x10, w1c);
    platform::write_u32(state + 0x14, w20);
    platform::write_u32(state + 0x18, w0c);
    platform::write_u32(state + 0x1C, w10);
    platform::write_u32(state + 0x20, w14);
    platform::write_u32(state + 0x24, w00);
    platform::write_u32(state + 0x28, w04);
    platform::write_u32(state + 0x2C, w08);
    platform::call3(
        W110_FUN_802DC780,
        state as u32,
        handler as u32,
        descriptor as u32,
    );
}

/// Builds the eight `dGoalManager_c` state records and registers the goal
/// bootstrap callback.
///
/// The body copies three SDA words plus the shared word `23` into four
/// goal-manager globals, registers `0x8010BF10`/`0x80374C78` with
/// `0x802DC780(0, ...)`, then constructs the states `StartWait`, `KiMePose`
/// (twice, at `0x80374CD0` and `0x80374D10`), `MessageOpen`, `ScoreCalc`,
/// `MessageDone`, `MessageEnd` and `ClearWait`.
///
/// # Original
/// - Ghidra: `FUN_8010B890` at `0x8010B890` (1652 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8010b890_FUN_8010b890.c`
/// - Removed: the `0x802DCD74`/`0x802DCDC0` prologue and epilogue pair
///   (`_savegpr_27`/`_restgpr_27`); `bl` at `+0x10` and `+0x660` in the
///   instruction stream, not calls made by the body.
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes four goal-manager globals, eight `0x40`-byte state records, eight
/// 12-byte registration descriptors and eight vtable stores.
///
/// # Safety
/// Must run once at startup, after the data segment and the state list head at
/// `r13 - 0x46A8` are initialised.
///
/// # Confidence
/// medium - the record geometry, constructor, vtable, copy rotation and
/// registration call are literal. The roles of the four goal-manager globals
/// and of the individual handler words are inferred only from their use here.
pub unsafe fn fn_8010b890() {
    platform::write_u32(W110_G_803222D8, platform::read_u32(W110_R2_5D88));
    platform::write_u32(W110_G_803222DC, platform::read_u32(W110_R2_5D84));
    platform::write_u32(W110_G_803222E0, platform::read_u32(W110_R2_5D80));
    platform::write_u32(W110_G_803222CC, platform::read_u32(R2_6114_23));
    // observed: `lwz r30,-0x60FC(r2)` then `stw r30,-0x53C0(r13)` at
    // `0x8010B904`/`0x8010B934`; the wave-110 body omitted this publication.
    platform::write_u32(SDA_BASE - 0x53C0, platform::read_u32(SDA2_BASE - 0x60FC));
    platform::call3(
        W110_FUN_802DC780,
        0,
        W110_GOAL_BOOT_CALLBACK as u32,
        W110_GOAL_BOOT_DATA as u32,
    );
    // observed: string labels at the cited addresses name the class and state.
    const NAMES: [usize; 8] = [
        0x8032_2570, // "dGoalManager_c::StateID_StartWait"
        0x8032_2594, // "dGoalManager_c::StateID_KiMePose"
        0x8032_25B8, // "dGoalManager_c::StateID_KiMePose" (second label)
        0x8032_25E4, // "dGoalManager_c::StateID_MessageOpen"
        0x8032_260C, // "dGoalManager_c::StateID_ScoreCalc"
        0x8032_2630, // "dGoalManager_c::StateID_MessageDone"
        0x8032_2654, // "dGoalManager_c::StateID_MessageEnd"
        0x8032_2678, // "dGoalManager_c::StateID_ClearWait"
    ];
    let mut index = 0usize;
    while index < 8 {
        let state = W110_GOAL_STATE_TABLE + index * 0x40;
        let template = W110_GOAL_STATE_TEMPLATE + index * 0x24;
        // observed: the first descriptor sits at table-0xC; later ones at
        // record-0x10, in the free tail of the preceding 0x40-byte block.
        let descriptor = if index == 0 {
            W110_GOAL_STATE_TABLE - 0x0C
        } else {
            state - 0x10
        };
        w110_fill_state_record(
            state,
            NAMES[index],
            template,
            W110_GOAL_STATE_VTABLE,
            W110_GOAL_HANDLER,
            descriptor,
        );
        index += 1;
    }
}

/// Builds the eight `dWarningManager_c` state records and seeds the warning
/// globals once.
///
/// When the byte at `r13 - 0x539C` is zero, the body copies two SDA words into
/// `0x80322880`/`0x80322884` and sets the guard byte. It then constructs the
/// eight warning states from the templates at `0x80322A18 + n*0x24`, installs
/// the `0x80322C94` vtable and registers each record with
/// `0x802DC780(state, 0x8010EE80, state - 0x10)`.
///
/// # Original
/// - Ghidra: `FUN_8010E830` at `0x8010E830` (1616 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8010e830_FUN_8010e830.c`
/// - Removed: the `0x802DCD74`/`0x802DCDC0` prologue and epilogue pair
///   (`_savegpr_27`/`_restgpr_27`); `bl` at `+0x10` and `+0x63C`, not calls
///   made by the body.
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes two globals and one guard byte, then eight `0x40`-byte records and
/// eight registration descriptors.
///
/// # Safety
/// Must run once at startup with the data segment and the state list head at
/// `r13 - 0x46A8` initialised.
///
/// # Confidence
/// medium - every copy and call is literal; the warning state names are
/// truncated to `dWarningManager_c::StateID_Warni...` in the export, so the
/// per-state roles beyond the first are not named.
pub unsafe fn fn_8010e830() {
    if platform::read_u8(W110_SDA_539C_BYTE) == 0 {
        platform::write_u32(W110_G_80322880, platform::read_u32(W110_R2_6398));
        platform::write_u32(W110_G_80322884, platform::read_u32(W110_R2_6394));
        platform::write_u8(W110_SDA_539C_BYTE, 1);
    }
    const NAMES: [usize; 8] = [
        0x8032_2B38, // "dWarningManager_c::StateID_Warni..." (Ghidra label)
        0x8032_2B60,
        0x8032_2B8C,
        0x8032_2BB8,
        0x8032_2BE0,
        0x8032_2C14,
        0x8032_2C40,
        0x8032_2C68,
    ];
    let mut index = 0usize;
    while index < 8 {
        let state = W110_WARNING_STATE_TABLE + index * 0x40;
        let template = W110_WARNING_STATE_TEMPLATE + index * 0x24;
        w110_fill_state_record(
            state,
            NAMES[index],
            template,
            W110_WARNING_STATE_VTABLE,
            W110_WARNING_HANDLER,
            state - 0x10,
        );
        index += 1;
    }
}

// ===========================================================================
// Wave 111: the two bounded-format text builders and the layout-record quad
// draw that remained in the `0x80100000` bucket after wave 110.
// ===========================================================================

/// `r2 - 0x5DE8`: scale applied to the actor's `+0x1E0` fade value before the
/// product is truncated to the draw colour's alpha byte.
const W111_R2_5DE8: usize = SDA2_BASE - 0x5DE8;
/// `r2 - 0x5DE4` / `r2 - 0x5DE0`: inset pair used when the region index is 1.
const W111_R2_5DE4: usize = SDA2_BASE - 0x5DE4;
const W111_R2_5DE0: usize = SDA2_BASE - 0x5DE0;
/// `r2 - 0x5DDC` / `r2 - 0x5DD8`: inset pair used for every other region.
const W111_R2_5DDC: usize = SDA2_BASE - 0x5DDC;
const W111_R2_5DD8: usize = SDA2_BASE - 0x5DD8;
/// `r2 - 0x5DD4`: inset scale.
const W111_R2_5DD4: usize = SDA2_BASE - 0x5DD4;
/// `r2 - 0x5DD0`: inset offset; also the base coordinate of the rectangle.
const W111_R2_5DD0: usize = SDA2_BASE - 0x5DD0;
/// `r2 - 0x5E38`: edge constant that clamps the measured text width/height.
const W111_R2_5E38: usize = SDA2_BASE - 0x5E38;

/// `0x802C17E0`: switches the GX/TEV state before the rectangle is submitted.
/// `// inferred:` role from the surrounding draw calls.
const W111_FUN_802C17E0: usize = 0x802C_17E0;
/// `0x802C2300`: prepares the descriptor word that follows the colour.
const W111_FUN_802C2300: usize = 0x802C_2300;
/// `0x802C2F70`: submits one rectangle with a colour and a two-word descriptor.
const W111_FUN_802C2F70: usize = 0x802C_2F70;
/// `0x802D1850`: fills the 12-float rectangle used by that submission.
const W111_FUN_802D1850: usize = 0x802D_1850;

/// `0x802E15DC`: bounded `vsnprintf(buffer, size, format, va_list)`.
const W111_FUN_802E15DC: usize = 0x802E_15DC;
/// `0x8022D9A0`: commits the four colour bytes of a text record.
const W111_FUN_8022D9A0: usize = 0x8022_D9A0;
/// `0x8022EED0`: runs one text run over a copy of the record.
const W111_FUN_8022EED0: usize = 0x8022_EED0;
/// `0x8022DFB0`: measures the rendered width of a formatted string.
const W111_FUN_8022DFB0: usize = 0x8022_DFB0;
/// `0x8022E1C0`: measures the rendered height of a formatted string.
const W111_FUN_8022E1C0: usize = 0x8022_E1C0;
/// `0x802DC69C`: `strlen`.
const W111_FUN_802DC69C: usize = 0x802D_C69C;

/// Writes a big-endian IEEE-754 double through two word stores.
///
/// # Safety
/// `addr..addr+8` must be writable.
unsafe fn w111_write_f64(addr: usize, value: f64) {
    let bits = value.to_bits();
    platform::write_u32(addr, (bits >> 32) as u32);
    platform::write_u32(addr + 4, bits as u32);
}

/// Builds the actor's screen-space label quad and submits it.
///
/// In plain English: when the actor's fade value is above the one-pixel inset,
/// the helper builds a white, alpha-scaled rectangle, converts it to a
/// 12-float screen rectangle with `0x802D1850` and submits it through
/// `0x802C2F70`.
///
/// # Original
/// - Ghidra: `FUN_801097f0` at `0x801097F0` (344 bytes)
/// - Evidence: `work/ghidra/main-gb/export/801097f0_FUN_801097f0.c`
///
/// # Arguments
/// - `this`: actor with the fade value at `+0x1E0` and the descriptor word at
///   `+0x7C`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Constructs a `0x38`-byte layout record, rewrites its `+0x00`, `+0x04`,
/// `+0x18`, `+0x1C` and `+0x34` fields, fills a 12-float rectangle and calls
/// four GX/draw entry points.
///
/// # Safety
/// `this` must be live for `0x1E4` bytes, and the GX state must be ready.
///
/// # Confidence
/// medium - every offset, call and arithmetic step is literal; the field roles
/// (`+0x1E0` fade, `+0x7C` descriptor) are inferred from the neighbouring draw
/// code. The export's partial store into the colour word keeps an incoming low
/// byte that the next store overwrites anyway, so the result is the single
/// `0xFFFFFF00 | alpha` value used here.
pub unsafe fn fn_801097f0(this: usize) {
    let inset = read_f32(W103_R2_5E00);
    let fade = read_f32(this + 0x1E0);
    if inset < fade {
        let alpha = w100_call_f64(
            W100_FUN_802DCC4C,
            (read_f32(W111_R2_5DE8) * fade) as f64,
        ) as u8;
        // observed: the export builds 0xFFFFFF00 | byte and then replaces the
        // low byte, i.e. white with the truncated alpha.
        let colour = 0xFFFF_FF00 | alpha as u32;

        let mut descriptor = crate::platform::GuestLocal::new( [0u32; 3]);
        descriptor[2] = colour;

        let mut record = crate::platform::GuestLocal::new( [0u8; 0x38]);
        let rec = record.as_mut_ptr() as usize;
        platform::call1(W103_FUN_802D0CC0, rec as u32);
        if platform::read_u32(rec + 4) != 0 {
            platform::write_u32(rec + 4, 0);
            let flags = platform::read_u16(rec + 0x34);
            platform::write_u16(rec + 0x34, flags | 1);
        }
        platform::write_u32(rec + 0x18, platform::read_u32(W103_R2_5DF0));
        platform::write_u32(rec + 0x1C, platform::read_u32(W103_R2_5DEC));
        platform::write_u32(rec, 0);
        platform::call1(W103_FUN_802D0F40, rec as u32);

        let (inset_x, inset_y) = if platform::read_i32(SDA_4778_REGION) == 1 {
            (read_f32(W111_R2_5DE4), read_f32(W111_R2_5DE0))
        } else {
            (read_f32(W111_R2_5DDC), read_f32(W111_R2_5DD8))
        };
        let rect_x = read_f32(W111_R2_5DD4) * inset_x - read_f32(W111_R2_5DD0);
        let rect_y = read_f32(W111_R2_5DD0) + read_f32(W111_R2_5DD4) * -inset_y;

        platform::call3(W111_FUN_802C17E0, 0, 1, 0);

        descriptor[1] = platform::read_u32(this + 0x7C);
        platform::call2(
            W111_FUN_802C2300,
            descriptor.as_mut_ptr().add(1) as u32,
            0,
        );

        let base = read_f32(W111_R2_5DD0);
        let mut rect = crate::platform::GuestLocal::new( [0u8; 0x30]);
        w103_call_f64x4_u32_u32(
            W111_FUN_802D1850,
            f64::from(rect_x - base),
            f64::from(base + rect_y),
            (((f64::from(base + rect_x) - f64::from(rect_x - base)) as f32) as f64).abs(),
            (((f64::from(rect_y - base) - f64::from(base + rect_y)) as f32) as f64).abs(),
            rec as u32,
            rect.as_mut_ptr() as u32,
        );
        descriptor[0] = descriptor[2];
        platform::call3(
            W111_FUN_802C2F70,
            0x10,
            rect.as_mut_ptr() as u32,
            descriptor.as_mut_ptr() as u32,
        );
    }
}

/// Formats one text line into a text record and commits it.
///
/// In plain English: "run `vsnprintf` into a 0x400-byte buffer, copy the
/// record's first word into `+0x34`, copy three record bytes around, then run
/// the two text-run commits."
///
/// # Original
/// - Ghidra: `FUN_80107050` at `0x80107050` (280 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80107050_FUN_80107050.c`
///
/// # Arguments
/// - `dest`: destination text record (`r3`).
/// - `format`: format string (`r4`).
/// - `gpr`: the variadic integer/pointer words `r5..r10`.
/// - `fpr`: the variadic floating-point words `f1..f8`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the formatted text into a stack buffer, stores the record's first
/// word at `+0x34`, copies `+0x03` to `+0x5E`, copies `+0x04`/`+0x08` to
/// `+0x48`/`+0x4C`, and calls the two text-run helpers with `+0x1C`.
///
/// # Safety
/// `dest` must be a live text record, `format` NUL-terminated, and the format
/// string must match the supplied `gpr`/`fpr` words.
///
/// # Confidence
/// low - the save block, the `0x02000000` `va_list` word, the formatter call,
/// the big-endian word store and the three copies are literal; `// partial:`
/// the caller's overflow-argument area (`&stack0x00000008`) is passed as null
/// and the `$cr1` guard around the float save area is not expressible, so all
/// eight doubles are stored unconditionally.
pub unsafe fn fn_80107050(dest: usize, format: u32, gpr: [u32; 6], fpr: [f64; 8]) {
    let mut buffer = crate::platform::GuestLocal::new( [0u8; 0x40C]);
    let mut save_area = crate::platform::GuestLocal::new( [0u32; 24]);
    save_area[0] = dest as u32;
    save_area[1] = format;
    save_area[2..8].copy_from_slice(&gpr);
    let mut index = 0;
    while index < 8 {
        w111_write_f64(
            save_area.as_mut_ptr() as usize + 0x20 + index * 8,
            fpr[index],
        );
        index += 1;
    }
    let mut descriptor = crate::platform::GuestLocal::new( [0u32; 3]);
    descriptor[0] = 0x0200_0000;
    descriptor[1] = 0;
    descriptor[2] = save_area.as_mut_ptr() as u32;
    platform::call4(
        W111_FUN_802E15DC,
        buffer.as_mut_ptr() as u32,
        0x400,
        format,
        descriptor.as_mut_ptr() as u32,
    );

    let head = platform::read_u32(dest);
    // observed: the export stores the word as four big-endian bytes at
    // `+0x34..+0x37`, which is a plain 32-bit store on the PowerPC target. The
    // same word is also written to a scratch local that has no reader.
    platform::write_u32(dest + 0x34, head);
    platform::call1(W111_FUN_8022D9A0, (dest + 0x1C) as u32);
    platform::write_u8(dest + 0x5E, platform::read_u8(dest + 3));
    platform::call1(W111_FUN_8022D9A0, (dest + 0x1C) as u32);
    platform::write_u32(dest + 0x48, platform::read_u32(dest + 4));
    platform::write_u32(dest + 0x4C, platform::read_u32(dest + 8));
    let length = platform::call1(W111_FUN_802DC69C, buffer.as_mut_ptr() as u32);
    platform::call3(
        W111_FUN_8022EED0,
        (dest + 0x1C) as u32,
        buffer.as_mut_ptr() as u32,
        length,
    );
}

/// Measures one formatted text line into a clamped screen rectangle.
///
/// In plain English: "format the line, measure its rendered width and height,
/// then write `[x0, y0, x1, y1]` where each axis is clamped between the
/// measured value and the shared edge constant."
///
/// # Original
/// - Ghidra: `FUN_80107170` at `0x80107170` (320 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80107170_FUN_80107170.c`
///
/// # Arguments
/// - `rect`: four-float destination (`r3`), `[x0, y0, x1, y1]`.
/// - `text`: text-record base (`r4`); the line is measured at `text + 0x1C`.
/// - `format`: format string (`r5`).
/// - `gpr`: the variadic integer/pointer words `r6..r10`.
/// - `fpr`: the variadic floating-point words `f1..f8`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Formats up to `0x400` bytes into a stack buffer, measures width and height
/// with `0x8022DFB0`/`0x8022E1C0`, and writes the four clamped floats to
/// `rect`.
///
/// # Safety
/// `rect` must be writable for 16 bytes, `text` live, and `format` must match
/// the supplied `gpr`/`fpr` words.
///
/// # Confidence
/// low - the `0x03000000` descriptor word, the two measurement calls and all
/// four clamps are literal; `// partial:` the overflow-argument area and the
/// `$cr1` float-save guard are not expressible, so all eight doubles are
/// stored unconditionally.
pub unsafe fn fn_80107170(rect: usize, text: usize, format: u32, gpr: [u32; 5], fpr: [f64; 8]) {
    let mut buffer = crate::platform::GuestLocal::new( [0u8; 0x40C]);
    let mut save_area = crate::platform::GuestLocal::new( [0u32; 24]);
    save_area[0] = rect as u32;
    save_area[1] = text as u32;
    save_area[2] = format;
    save_area[3..8].copy_from_slice(&gpr);
    let mut index = 0;
    while index < 8 {
        w111_write_f64(
            save_area.as_mut_ptr() as usize + 0x20 + index * 8,
            fpr[index],
        );
        index += 1;
    }
    let mut descriptor = crate::platform::GuestLocal::new( [0u32; 3]);
    descriptor[0] = 0x0300_0000;
    descriptor[1] = 0;
    descriptor[2] = save_area.as_mut_ptr() as u32;
    platform::call4(
        W111_FUN_802E15DC,
        buffer.as_mut_ptr() as u32,
        0x400,
        format,
        descriptor.as_mut_ptr() as u32,
    );

    let measure_width = crate::platform::guest_fn!(W111_FUN_8022DFB0, fn(usize, u32) -> f64);
    let measure_height = crate::platform::guest_fn!(W111_FUN_8022E1C0, fn(usize, u32) -> f64);
    let width = measure_width(text + 0x1C, buffer.as_mut_ptr() as u32);
    let height = measure_height(text + 0x1C, buffer.as_mut_ptr() as u32);

    let mut left = width;
    if (read_f32(W111_R2_5E38) as f64) < width {
        left = read_f32(W111_R2_5E38) as f64;
    }
    write_f32(rect, left as f32);
    let mut right = width;
    if width < read_f32(W111_R2_5E38) as f64 {
        right = read_f32(W111_R2_5E38) as f64;
    }
    write_f32(rect + 8, right as f32);

    let mut top = height;
    if (read_f32(W111_R2_5E38) as f64) < height {
        top = read_f32(W111_R2_5E38) as f64;
    }
    write_f32(rect + 4, top as f32);
    let mut bottom = height;
    if height < read_f32(W111_R2_5E38) as f64 {
        bottom = read_f32(W111_R2_5E38) as f64;
    }
    write_f32(rect + 0xC, bottom as f32);
}

// ===========================================================================
// Wave 112: the last four entries of the `0x80120000` bucket.
//
// These are the four records waves 102 and 108 left untranslated. The
// instruction stream in `work/dol/main.elf` resolves each claimed blocker:
// the `0x8015F140` dead-band is a function-entry `lfs f4` that survives to the
// call, both player queries forward their incoming `r3` unchanged, and the two
// animation buffers are 12 bytes each and do not overlap. The bodies below
// follow the export's control flow exactly and name the recovered operands in
// their doc blocks.
// ===========================================================================

/// Drops the fall actor and posts its contact/landing response.
///
/// In plain English: while the actor's `+0xEC` drop value is negative, ease it
/// toward zero with the `0x8015F140` damper and snap it to zero once it is
/// within `0x802F5A48` of the target. Then run the two per-frame model hooks,
/// probe the ground at `+0xAC`/`+0xB0`, and either release the actor through
/// `0x80162590`/`0x80162510` when it has sunk below the probe, or report the
/// landing through `0x8011EB00` when the vertical speed is significant and the
/// `+0x1EC` collider query succeeds.
///
/// # Original
/// - Ghidra: `FUN_80121280` at `0x80121280` (264 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80121280_FUN_80121280.c`
///
/// # Arguments
/// - `object`: WorldMap fall/splash actor with `+0xAC`, `+0xB0`, `+0xE8`,
///   `+0xEC`, `+0x348`, `+0x38D`, `+0x38F`, `+0x5B8` and the `+0x1EC`
///   collider.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0xEC` and the one-word ground probe; runs `0x8006CD90`,
/// `0x8006CD40`, `0x80075270` and one of the two release paths.
///
/// # Safety
/// `object` must be live for `0x5BC` bytes and the `+0x1EC` collider must be
/// a live height-field record.
///
/// # Confidence
/// medium - every comparison, store and call is literal. The C export omits
/// the fourth `0x8015F140` operand because the value is already in `f4`; the
/// instruction stream loads it once at `0x80121288` from the `r2 - 0x5B54`
/// slot (`0.0`), and no later instruction overwrites `f4` before the call, so
/// the dead-band is recovered rather than guessed. The `r2 - 0x5A3C` /
/// `-0x5A8C` / `-0x5A94` / `-0x5A48` slots keep their offsets as names because
/// their `f32` values live in `main.elf`'s `.sdata2`.
pub unsafe fn fn_80121280(object: usize) {
    let zero = read_f32(R2_5B54_ZERO);
    if read_f32(object + 0xEC) < zero
        && w102_ease(
            read_f32(W102_R2_5A3C) as f64,
            read_f32(W102_R2_5A8C) as f64,
            read_f32(W102_R2_5A94) as f64,
            zero as f64,
            object + 0xEC,
        ) < read_f32(W102_R2_5A48) as f64
    {
        write_f32(object + 0xEC, read_f32(W102_R2_5A3C));
    }
    platform::call1(FUN_8006CD90, object as u32);
    platform::call1(FUN_8006CD40, object as u32);
    let mut probe = crate::platform::GuestLocal::new( [read_f32(R2_5B54_ZERO); 1]);
    let contact = w102_call_f64_f64_u32_u32(
        W102_FUN_80075270,
        read_f32(object + 0xAC) as f64,
        read_f32(object + 0xB0) as f64,
        platform::read_u8(object + 0x38F) as u32,
        probe.as_mut_ptr() as u32,
    );
    if contact == 0 && read_f32(object + 0xB0) + read_f32(object + 0x5B8) < probe[0] {
        // observed: r3 still holds the 0x80162590 result when 0x80162510 is
        // called, so the owner is the release target.
        let owner = platform::call1(FUN_80162590, object as u32);
        if owner == 0 {
            return;
        }
        platform::call1(FUN_80162510, owner);
        return;
    }
    if read_f32(W102_R2_5A48) < read_f32(object + 0xE8).abs()
        && platform::call2(FUN_8006FA40, (object + 0x1EC) as u32, 0) != 0
    {
        platform::call3(
            FUN_8011EB00,
            object as u32,
            (platform::read_u8(object + 0x348) ^ 1) as u32,
            platform::read_u8(object + 0x38D) as i8 as u32,
        );
    }
}

/// Reports whether the actor's player slot is present and the pad mode allows
/// player control.
///
/// In plain English: resolve the player actor from the incoming actor's
/// `+0x392` slot byte, then return `0` when the pad mode is `1`, when the mode
/// is `0` and the `r13 - 0x56E0` object's `+0x20` byte is clear, or when no
/// player actor was resolved; otherwise return `1`.
///
/// # Original
/// - Ghidra: `FUN_80125D20` at `0x80125D20` (112 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80125d20_FUN_80125d20.c`
///
/// # Arguments
/// - `object`: WorldMap actor whose `+0x392` slot byte is forwarded to
///   [`fn_80125f10`].
///
/// # Returns
/// `1` when a player actor exists and the pad mode is not `0`/`1` as above;
/// otherwise `0`.
///
/// # Side effects
/// Calls `0x80125F10` and `0x800CD240`; reads the `r13 - 0x56E0` pad-mode
/// object.
///
/// # Safety
/// `object` must be live; the pad-mode object must be initialised.
///
/// # Confidence
/// medium - the mode ladder and every byte test are literal. The export
/// declares the function `void` and prints the `0x80125F10` call without an
/// operand because `r3` is forwarded untouched from this function's entry;
/// the parameter is recovered from that pass-through and from the sibling
/// [`fn_80125cc0`], which calls the same callee with its own `object`.
pub unsafe fn fn_80125d20(object: usize) -> u32 {
    let player = fn_80125f10(object);
    let mode = call0_u32(W91_FUN_800CD240) as u8;
    if mode == 1
        || (mode == 0
            && platform::read_u8(platform::read_u32(W102_SDA_56E0) as usize + 0x20) == 0)
    {
        return 0;
    }
    if player == 0 {
        0
    } else {
        1
    }
}

/// Asks the player actor's `+0xE0` virtual slot for its vehicle/ride state.
///
/// In plain English: resolve the player actor from the incoming actor, then
/// call the player's virtual slot `+0xE0` with the player as receiver and
/// return whether the answer is non-zero. With no player actor the answer is
/// `0` without a virtual call.
///
/// # Original
/// - Ghidra: `FUN_80125FA0` at `0x80125FA0` (76 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80125fa0_FUN_80125fa0.c`
///
/// # Arguments
/// - `object`: WorldMap actor whose `+0x392` slot byte is forwarded to
///   [`fn_80125f10`].
///
/// # Returns
/// The player's `+0xE0` slot result, coerced to `0`/`1`.
///
/// # Side effects
/// Calls `0x80125F10` and the player's virtual slot `+0xE0`.
///
/// # Safety
/// `object` must be live and the resolved player must have a readable `+0x60`
/// vtable whose `+0xE0` slot accepts `(player)`.
///
/// # Confidence
/// medium - the slot offset, the null guard and the result coercion are
/// literal, and the receiver is the live `r3` left by `0x80125F10`. The
/// export prints both calls without operands because this function forwards
/// its own incoming `r3`; `0x80125670` calls it with an explicit actor, which
/// confirms the parameter.
pub unsafe fn fn_80125fa0(object: usize) -> u32 {
    let player = fn_80125f10(object) as usize;
    if player == 0 {
        return 0;
    }
    if vcall60_0(player, 0xE0) != 0 {
        1
    } else {
        0
    }
}

/// Builds the model-space point from the `0x0B`/`0x0E` animation records.
///
/// In plain English: when the actor's `+0x3C8` mode slot reports `0`, copy the
/// `0x0E` animation point and wrap its X with `0x80101AA0`; otherwise average
/// the `0x0B` and `0x0E` points at half scale, wrap the averaged X, and lift Y
/// to `+0xB0 + 0x8012DE20(object)` when the controller's `+0x17C` flag `4` is
/// set.
///
/// # Original
/// - Ghidra: `FUN_8012DE80` at `0x8012DE80` (296 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8012de80_FUN_8012de80.c`
///
/// # Arguments
/// - `out`: three writable floats, `[x, y, z]`.
/// - `object`: WorldMap player with `+0x60`, `+0x2A64`, `+0xB0` and the
///   `+0x3C8` mode slot.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `out[0..3]`; two 12-byte stack records are scratch space.
///
/// # Safety
/// `out` and `object` must be live; `+0x2A64` must be a model whose animation
/// records exist.
///
/// # Confidence
/// medium - every branch, midpoint, wrap and lift is literal. The earlier note
/// that the two animation buffers overlap is incorrect: `0x800D5790` writes
/// three words (12 bytes) at `r1+0x2C` and `r1+0x20`, so the `0x0B` record is
/// `r1+0x2C..0x37` and the `0x0E` record is `r1+0x20..0x2B`. The export's
/// operand-less `0x80101AA0` call takes the X midpoint already in `f1`, the
/// same value the sibling [`fn_8012dfb0`] wraps. The animation selectors stay
/// `// inferred:` labels for the record kind.
pub unsafe fn fn_8012de80(out: usize, object: usize) {
    let model = platform::read_u32(object + 0x2A64) as usize;
    let mut entry_b = crate::platform::GuestLocal::new( [0f32; 4]);
    let mut entry_e = crate::platform::GuestLocal::new( [0f32; 4]);
    platform::call3(
        W102_FUN_800D5790,
        model as u32,
        entry_b.as_mut_ptr() as u32,
        0x0B,
    );
    platform::call3(
        W102_FUN_800D5790,
        model as u32,
        entry_e.as_mut_ptr() as u32,
        0x0E,
    );
    if vcall60_0(object, 0x3C8) == 0 {
        let wrapped = fn_80101aa0(entry_e[0] as f64);
        write_f32(out, wrapped as f32);
        write_f32(out + 4, entry_e[1]);
        write_f32(out + 8, entry_e[2]);
        return;
    }
    let half = read_f32(W98_R2_591C_HALF);
    let x = (entry_b[0] + entry_e[0]) * half;
    let mut y = (entry_b[1] + entry_e[1]) * half;
    let z = (entry_b[2] + entry_e[2]) * half;
    let wrapped = fn_80101aa0(x as f64);
    let controller = platform::read_u32(object + 0x2A64) as usize;
    if platform::read_u32(controller + 0x17C) & 4 != 0 {
        let lift = wm_scale_by_id_table(object);
        y = (read_f32(object + 0xB0) as f64 + lift) as f32;
    }
    write_f32(out, wrapped as f32);
    write_f32(out + 4, y);
    write_f32(out + 8, z);
}

// ===========================================================================
// Wave 113: the last four entries of the `0x80130000` bucket.
//
// `0x8013B0B0` was skipped by wave 36 as a "GQR-reconstruction record", and
// `0x80130F40` / `0x80137320` / `0x80138510` were what remained after the
// wave 93/98/104 sweeps. The instruction stream in `work/dol/main.elf` shows
// that the `psq_l ...,0,1` sequences are 16-bit quantised loads whose net
// effect is a halfword converted to `float` and scaled by `1/256`; the
// module's existing angle helpers already treat them that way. Each record is
// therefore transliterated instruction by instruction. Where the Ghidra export
// disagrees with the stream (all four exports carry "removing unreachable
// block" warnings) the stream wins and the spot is marked `// observed:`.
// ===========================================================================

// --- callees, tables and r2/r13 slots used only by wave 113 ---------------
/// `0x80152480`: copies the target's twelve-word transform into a caller
/// buffer and returns `1`.
const W113_FUN_80152480: usize = 0x8015_2480;
/// `0x800D1F10`: `(double, float *)` writer used by the ride turn update.
const W113_FUN_800D1F10: usize = 0x800D_1F10;
/// `0x8005E540`: `+0xEA4` sub-controller cancel predicate.
const W113_FUN_8005E540: usize = 0x8005_E540;
/// `0x80324FF0`: twelve-byte-stride animation table, indexed by `+0x14A4`.
const W113_DATA_80324FF0: usize = 0x8032_4FF0;
/// `0x80375E6C`: event record posted through virtual slot `+0x294` by the
/// mount/pose setup.
const W113_DATA_80375E6C: usize = 0x8037_5E6C;
/// `0x8042B840`: two-entry per-facing scale table (`1.0` / `-1.0`).
const W113_FACING_SCALE_TABLE: usize = 0x8042_B840;

/// `0x802F5748 + offset`: the ride rate/limit table. Every value below was
/// read from `main.elf`; the addresses are the export's `DAT_802f57xx` names.
const W113_DAT_802F575C: usize = 0x802F_575C; // 1.2f
const W113_DAT_802F5760: usize = 0x802F_5760; // 2.0f
const W113_DAT_802F5764: usize = 0x802F_5764; // 1.5f
const W113_DAT_802F5768: usize = 0x802F_5768; // 2.4f
const W113_DAT_802F576C: usize = 0x802F_576C; // 0.02f
const W113_DAT_802F5770: usize = 0x802F_5770; // 0.01f
const W113_DAT_802F5774: usize = 0x802F_5774; // 0.05f
const W113_DAT_802F5778: usize = 0x802F_5778; // 0.2f
const W113_DAT_802F577C: usize = 0x802F_577C; // 0.03f
const W113_DAT_802F5780: usize = 0x802F_5780; // 0.03f
const W113_DAT_802F5790: usize = 0x802F_5790; // 0.14f

/// `r2 - 0x7838` = `0x8042B848`: `3.628f`, the sine gain of the pose setup.
const W113_R2_7838_3_628: usize = SDA2_BASE - 0x7838;
/// `r2 - 0x781C` = `0x8042B864`: `-4.0f`, stored at `+0x118`.
const W113_R2_781C_NEG4: usize = SDA2_BASE - 0x781C;
/// `r2 - 0x5808` = `0x8042D878`: `8.25f`, the tilt gain used when the ride
/// tilt object reports a non-zero value.
const W113_R2_5808_8_25: usize = SDA2_BASE - 0x5808;
/// `r2 - 0x5804` = `0x8042D87C`: `0.0001f`.
const W113_R2_5804_0_0001: usize = SDA2_BASE - 0x5804;
/// `r2 - 0x5800` = `0x8042D880`: `0.13f`.
const W113_R2_5800_0_13: usize = SDA2_BASE - 0x5800;
/// `r2 - 0x57FC` = `0x8042D884`: `0.003f`.
const W113_R2_57FC_0_003: usize = SDA2_BASE - 0x57FC;
/// `r2 - 0x5818` = `0x8042D868`: `-0.09375` as a `double`.
const W113_R2_5818_NEG: usize = SDA2_BASE - 0x5818;
/// `r2 - 0x5810` = `0x8042D870`: `-0.02734375` as a `double`.
const W113_R2_5810_NEG: usize = SDA2_BASE - 0x5810;

/// Calls virtual slot `slot` at vtable `+0x60` with two `f64` arguments.
///
/// `0x80138510` calls `+0x410` with `(double, double, object)` and no integer
/// argument beyond the receiver, so the module's `vcall_f64_f64_u32` helper
/// does not fit.
///
/// # Original
/// Host-side helper; no binary address of its own.
///
/// # Safety
/// `object+0x60` must point at a readable vtable whose `slot` entry accepts
/// `(object, f64, f64)`.
///
/// # Confidence
/// high - mechanical wrapper.
#[inline]
unsafe fn w113_vcall60_f64_f64(object: usize, slot: usize, a: f64, b: f64) -> u32 {
    let vtable = platform::read_u32(object + 0x60) as usize;
    let entry = platform::read_u32(vtable + slot) as usize;
    let f = crate::platform::guest_fn!(entry, fn(usize, f64, f64) -> u32);
    f(object, a, b)
}

/// Copies the target's world X/Y and stores the offset toward it, split by the
/// target's facing.
///
/// In plain English: ask `0x80152480` for the target's twelve-word transform,
/// copy its X and Y words into `+0xAC`/`+0xB0`, then store
/// `(this.X - target.X) / cos(target.yaw)` at `+0x2774` and
/// `this.Y - target.Y` at `+0x2778`. Dividing the horizontal difference by the
/// cosine turns the world delta back into a distance along the target's
/// heading; the vertical difference needs no correction.
///
/// # Original
/// - Ghidra: `FUN_8013B0B0` at `0x8013B0B0` (200 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8013b0b0_FUN_8013b0b0.c`
///
/// # Arguments
/// - `this`: actor receiving the offset; `+0xAC`/`+0xB0` are its own X/Y and
///   `+0x2774`/`+0x2778` the two stored results.
/// - `target`: object whose `+0x14D8` transform, `+0x102` yaw and `+0xAC`/
///   `+0xB0` position are read.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `this+0xAC`, `this+0xB0`, `+0x2774` and `+0x2778`; calls `0x80152480`
/// and `0x80237BD0`.
///
/// # Safety
/// `target` must be non-null, live for `0x110` bytes, and hold a valid
/// `+0x14D8` transform; `this` must be writable through `+0x2778`.
///
/// # Confidence
/// medium - the guard, the two transform copies, the yaw load, the sine/cosine
/// call and both divisions are literal. The transform is laid out as three
/// twelve-word rows with the translation words at index `3`, `7` and `11`, and
/// `0x80237BD0` is read as the cosine member of the module's
/// `0x80237BD0`/`0x80237C40` pair (see [`fn_8011dab0`]). The export's
/// `psq_l`-related `GQR` branch is the decompiler's rendering of the same
/// halfword-to-`float` load the rest of the module models as
/// `read_i16(..) as u16 as f64`.
pub unsafe fn fn_8013b0b0(this: usize, target: usize) {
    if target == 0 {
        return;
    }
    let mut transform = crate::platform::GuestLocal::new( [0f32; 12]);
    if platform::call2(
        W113_FUN_80152480,
        target as u32,
        transform.as_mut_ptr() as u32,
    ) == 0
    {
        return;
    }
    write_f32(this + 0xAC, transform[3]);
    write_f32(this + 0xB0, transform[7]);
    // observed: `psq_l f1,0(r1+8),0,1` loads the halfword stored by
    // `sth r0,8(r1)` from `lha +0x102`; the two floats the stream copies into
    // the same stack block are never read.
    let yaw = read_i16(target + 0x102) as u16 as f64;
    let phase = (read_f32(W107_R2_5820_INV256) as f64 * yaw) as f32 as f64;
    let cosine = call_f64_f64(FUN_80237BD0, phase);
    write_f32(
        this + 0x2774,
        ((read_f32(this + 0xAC) - read_f32(target + 0xAC)) as f64 / cosine) as f32,
    );
    write_f32(this + 0x2778, read_f32(this + 0xB0) - read_f32(target + 0xB0));
}

/// Resets the ride's action state and starts the mount pose.
///
/// In plain English: clear action `3`, post event `0x27`, play animation
/// `0x157`, emit the `+0x38D` sound event through the `r13-0x5678` audio
/// object, and load the three 30-frame timers at `+0x6EC`, `+0x107C` and
/// `+0x1408`. It then derives two stance angles from the `+0x102` yaw: when
/// `+0x10D4` bit `0x4000` is set it posts `0x80375E6C` and calls the `+0x410`
/// pose slot with `2*sin` and `2*cos`; otherwise it calls the `+0x3FC` slot
/// with `4*cos` and `max(3.628*sin, 0)`.
///
/// # Original
/// - Ghidra: `FUN_80138510` at `0x80138510` (416 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80138510_FUN_80138510.c`
///
/// # Arguments
/// - `this`: ride/player actor with the `+0x60` vtable, `+0x38D` sound id and
///   `+0x10D4` action word.
/// - `_control`: the export's `param_2`. The stream overwrites `r4` with `3`
///   before reading it, so the argument is dead and only kept for arity.
/// - `angle`: halfword stance angle, scaled by `1/256` before the trig calls.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Three 30-frame timer stores, four calls and one of the two virtual pose
/// slots.
///
/// # Safety
/// `this` must be live with a valid `+0x60` vtable and the audio object at
/// `r13-0x5678` must be initialised.
///
/// # Confidence
/// medium - every store, timer and call is literal, and both pose slots and
/// their argument order are visible. `_control` is dead in the stream; the
/// `psq_l`-`GQR` block is the same halfword-to-`float` conversion used by the
/// rest of the module; the two trig helpers are read as
/// `0x80237C40` = sine and `0x80237BD0` = cosine, matching [`fn_8011dab0`].
pub unsafe fn fn_80138510(this: usize, _control: u32, angle: i16) {
    platform::call2(FUN_80056CB0, this as u32, 3);
    vcall60_2(this, 0x434, 0x27, 0);
    platform::call3(FUN_80057E70, this as u32, 0x157, 0);
    platform::call5(
        FUN_800D8BB0,
        platform::read_u32(SDA_5678_WORD),
        platform::read_u8(this + 0x38D) as i8 as i32 as u32,
        4,
        0,
        0,
    );
    platform::write_u32(this + 0x6EC, 0x1E);
    platform::write_u32(this + 0x107C, 0x1E);
    platform::write_u32(this + 0x1408, 0x1E);
    let phase = (read_f32(W107_R2_5820_INV256) as f64 * (angle as u16 as f64)) as f32 as f64;
    if platform::read_u32(this + 0x10D4) & 0x4000 != 0 {
        vcall60_2(this, 0x294, W113_DATA_80375E6C as u32, 0);
        let sine = call_f64_f64(W106_FUN_80237C40, phase) as f32;
        let cosine = call_f64_f64(FUN_80237BD0, phase) as f32;
        w113_vcall60_f64_f64(
            this,
            0x410,
            (read_f32(R2_5918_TWO) * cosine) as f64,
            (read_f32(R2_5918_TWO) * sine) as f64,
        );
        return;
    }
    let cosine = call_f64_f64(FUN_80237BD0, phase) as f32;
    let sine = call_f64_f64(W106_FUN_80237C40, phase) as f32;
    let mut forward = read_f32(W113_R2_7838_3_628) * sine;
    // observed: `fcmpo cr0,f1,0.0` + branch-if-not-less, so only a negative
    // value is clamped and the result is `max(3.628 * sin, 0)`.
    if forward < read_f32(R2_5928_ZERO) {
        forward = read_f32(R2_5928_ZERO);
    }
    vcall_f64_f64_u32_u32_u32(
        this,
        0x3FC,
        forward as f64,
        (read_f32(R2_5914_FOUR) * cosine) as f64,
        1,
        1,
        0,
    );
}

/// Advances the ride's steering, pose angles and landing state.
///
/// In plain English: when the `0x36` action is not active the body just posts
/// the `0x80324FF0 + 12*(+0x14A4)` animation entry; otherwise it bails out
/// with `0x80375CAC` when `+0x10D4` has bit `0x180000` set or `+0x1508` is
/// null. It then samples the `+0x14FC` angle, mirrors it when the facing byte
/// `+0x348` is `1`, and either (below `+0x1DEC == 2`) stores the angle at
/// `+0x100` and rebuilds the `+0x2A6C`/`+0x2A70` tilt pair from the
/// `+0x102` yaw, or copies `+0x1DEC` into `+0x104`. Finally it runs the
/// trick/landing attempt `0x801363C0` and, when that declines, re-posts the
/// animation entry and updates the `+0x14FC` motion record.
///
/// # Original
/// - Ghidra: `FUN_80137320` at `0x80137320` (492 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80137320_FUN_80137320.c`
///
/// # Arguments
/// - `this`: ride actor with `+0x348` facing, `+0x10D4`/`+0x14A4`/
///   `+0x1508`/`+0x1DEC` state and the `+0x14FC` motion record.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x100`, `+0x104`, `+0x2A6C` and `+0x2A70`; calls `0x80056CF0`,
/// `0x800D2270`, `0x802DCBFC`, `0x800D1F10` and [`fn_801363c0`]; may post
/// `0x80375CAC` twice.
///
/// # Safety
/// `this` must be live; `+0x1508` must be a live record when the guard passes
/// and `+0x14FC` must be a writable motion record.
///
/// # Confidence
/// medium - every guard, store, `+0x14A4` table index and call is literal.
/// Two spots where the export differs from the stream are marked `// observed:`
/// (the `neg`/`extsb` pair that narrows the sampled angle, and the `+0x104`
/// store, which the stream feeds from `+0x1DEC`). The tilt pair uses the same
/// `0x80237C40`/`0x80237BD0` sine/cosine pair as [`fn_80138510`].
pub unsafe fn fn_80137320(this: usize) {
    if platform::call2(W98_FUN_80056CF0, this as u32, 0x36) == 0 {
        platform::call2(
            FUN_802DCBFC,
            this as u32,
            (W113_DATA_80324FF0 + platform::read_u32(this + 0x14A4) as usize * 12) as u32,
        );
        return;
    }
    if platform::read_u32(this + 0x10D4) & 0x180000 != 0
        || platform::read_u32(this + 0x1508) == 0
    {
        vcall60_2(this, 0x294, G_80375CAC as u32, 0);
        return;
    }
    let mut angle = platform::call1(FUN_800D2270, (this + 0x14FC) as u32) as i16;
    if platform::read_u32(this + 0x1DEC) < 2 {
        if platform::read_u8(this + 0x348) == 1 {
            // observed: `neg r3,r0` / `extsb r30,r0` negates and narrows the
            // resampled angle to `i8` before it lands in `+0x100`.
            angle = (-(platform::call1(FUN_800D2270, (this + 0x14FC) as u32) as i32)) as i8
                as i16;
        }
        platform::write_u16(this + 0x100, angle as u16);
        let mut gain = read_f32(W90_R2_5754_NEG2_5);
        if platform::read_u32(this + 0x1090) == 0 {
            gain = read_f32(W104_R2_5834);
        }
        let phase = (read_f32(W107_R2_5820_INV256) as f64 * (angle as u16 as f64)) as f32 as f64;
        let sine = call_f64_f64(W106_FUN_80237C40, phase) as f32;
        let yaw = read_i16(this + 0x102) as u16 as f64;
        let yaw_phase =
            (read_f32(W107_R2_5820_INV256) as f64 * yaw) as f32 as f64;
        let cosine = call_f64_f64(FUN_80237BD0, yaw_phase) as f32;
        write_f32(this + 0x2A6C, gain * sine * cosine);
        let tilt = call_f64_f64(FUN_80237BD0, phase) as f32;
        write_f32(this + 0x2A70, gain * tilt);
    } else {
        // observed: the stream stores `+0x1DEC` here (`sth r0,0x104(r31)`);
        // the export's `-sVar8` is the dead `neg` that precedes it.
        platform::write_u16(this + 0x104, platform::read_u32(this + 0x1DEC) as u16);
    }
    if fn_801363c0(this) != 0 {
        return;
    }
    platform::call2(
        FUN_802DCBFC,
        this as u32,
        (W113_DATA_80324FF0 + platform::read_u32(this + 0x14A4) as usize * 12) as u32,
    );
    let height = read_f32(this + 0x1DF0) + read_f32(this + 0x13FC);
    call_f64_u32(W113_FUN_800D1F10, height as f64, (this + 0x14FC) as u32);
    if platform::read_u8(this + 0x1526) & 1 != 0 {
        vcall60_2(this, 0x294, G_80375CAC as u32, 0);
    }
}

/// Recomputes the ride's steering rates, easings and tilt gates once per frame.
///
/// In plain English: clear the `+0x2070` counter when the sub-controller cancels
/// it, and derive the `busy`/`riding` booleans from the `+0xEA4`
/// sub-controller. A steering step
/// of `0x3E00` (or `0x2000` while riding, or the negated `+0x2070` counter) is
/// converted to a rate through the `0x80237BD0` cosine and stored at
/// `+0x206C`. Two rate/limit ladders, selected by the variant word and by
/// `busy`/`riding`, pick the `0x802F5748` table entry that eases the
/// vertical value at `+0xEC`; the body then stores `-4.0` at `+0x118`, `0.0`
/// at `+0x114`, the new tilt speed at `+0x2068`, and the two derived values at
/// `+0x110`/`+0x11C`, finally selecting `1.0` or `0.3` for `+0x2064`.
///
/// # Original
/// - Ghidra: `FUN_80130F40` at `0x80130F40` (1160 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80130f40_FUN_80130f40.c`
/// - Removed: the `0x802DCD70`/`0x802DCDBC` prologue and epilogue pair
///   (`_savegpr_26`/`_restgpr_26`); the incoming `r3` is the ride and `r4` the
///   variant word the export printed as that helper's "return".
///
/// # Arguments
/// * `ride` - ride object (incoming `r3`).
/// * `variant` - mode/variant word (incoming `r4`), selected by both ladders.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x100`/`+0x102` (through `0x8015F340`), `+0x110`, `+0x114`,
/// `+0x118`, `+0x11C`, `+0x2064`, `+0x2068`, `+0x206C`, `+0x2070` and `+0xEC`;
/// calls `0x8005E4F0`, `0x8005E500`, `0x8005E7A0`, `0x80056CF0`, `0x8015F140`,
/// `0x801611C0` (through [`fn_80130ce0`]) and the `+0x444` vtable slot.
///
/// # Safety
/// `ride` must be live through `+0x2070`; its `+0x60` vtable must be readable;
/// the `r13-0x5580` tilt object must point at a live record when the `+0x8C0`
/// word is read.
///
/// # Confidence
/// medium - the control flow, the `0x802F5748` table indices, every rate and
/// limit and all stores match the instruction stream. The exported C differs in
/// two places and both are marked `// observed:`: at `0x8013100C` the stream
/// negates and narrows the `+0x2070` word rather than the `0x3E00`/`0x2000`
/// step, and the second `0x8005E7A0`/`0x8005E500` pair is reached only through
/// the `+0x2070 == 0` guard.
pub unsafe fn fn_80130f40(ride: usize, variant: u32) {
    if platform::read_u32(ride + 0x2070) != 0
        && platform::call1(W113_FUN_8005E540, (ride + 0xEA4) as u32) != 0
    {
        platform::write_u32(ride + 0x2070, 0);
    }

    let busy = platform::call1(W98_FUN_8005E4F0, (ride + 0xEA4) as u32) != 0
        || (platform::read_u32(ride + 0x2070) == 0
            && platform::call1(W98_FUN_8005E500, (ride + 0xEA4) as u32) != 0);
    let riding = platform::call2(W102_FUN_8005E7A0, (ride + 0xEA4) as u32, 0) != 0;

    let mut steer: i32 = 0;
    if busy {
        steer = 0x3E00;
        if riding {
            steer = 0x2000;
        }
        if platform::call1(W98_FUN_8005E500, (ride + 0xEA4) as u32) != 0 {
            // observed: `neg r29,r0` / `extsb r29,r0` at 0x8013100C. `r0` still
            // holds `+0x2070` there, so the step assigned above is replaced by
            // the negated, 8-bit-narrowed counter.
            steer = (platform::read_u32(ride + 0x2070).wrapping_neg() as i8) as i32;
        }
    }

    let facing = platform::read_u8(ride + 0x348);
    let yaw = vcall60_1(ride, 0x444, facing as u32);
    platform::call3(
        FUN_8015F340,
        (ride + 0x102) as u32,
        (yaw as i8) as i32 as u32,
        0x400,
    );
    let pitch = fn_80130ce0(ride);
    platform::call3(
        FUN_8015F340,
        (ride + 0x100) as u32,
        (pitch as i8) as i32 as u32,
        0x300,
    );

    let mut yaw_scale = read_f32(W98_R2_5928_ZERO);
    let mut limit = read_f32(W113_DAT_802F576C);
    if variant != 0 {
        if busy {
            yaw_scale = read_f32(W113_DAT_802F5760);
            limit = if platform::call2(W98_FUN_80056CF0, ride as u32, 0x42) != 0 {
                read_f32(W113_DAT_802F5790)
            } else {
                read_f32(W113_DAT_802F5778)
            };
        }
    } else {
        if busy {
            yaw_scale = read_f32(W113_DAT_802F575C);
            limit = read_f32(W113_DAT_802F5774);
        } else if riding {
            limit = read_f32(W113_DAT_802F5780);
        }
        if read_f32(W113_DAT_802F575C) <= read_f32(ride + 0xEC).abs() {
            limit = read_f32(W113_DAT_802F577C);
        }
    }

    let phase = (read_f32(W107_R2_5820_INV256) as f64 * (steer as u16 as f64)) as f32 as f64;
    let cosine = call_f64_f64(FUN_80237BD0, phase) as f32;
    write_f32(ride + 0x206C, yaw_scale * cosine);

    let mut target = read_f32(ride + 0x206C) as f64;
    let half_height = read_f32(ride + 0x1030) * read_f32(W98_R2_591C_HALF);
    if read_f32(ride + 0x1138) > read_f32(ride + 0xB0) + half_height {
        if (read_f32(ride + 0xEC) as f64) < -(read_f32(W113_DAT_802F5760) as f64) {
            limit = read_f64(W113_R2_5818_NEG).abs() as f32;
        }
    } else {
        target = read_f32(W104_R2_5834) as f64;
        limit = if read_f32(ride + 0xEC) <= read_f32(W98_R2_5928_ZERO) {
            read_f64(W113_R2_5810_NEG).abs() as f32
        } else {
            read_f64(W113_R2_5818_NEG).abs() as f32
        };
    }
    w102_ease(
        target,
        read_f32(W98_R2_591C_HALF) as f64,
        limit as f64,
        read_f32(W102_R2_5890) as f64,
        ride + 0xEC,
    );

    write_f32(ride + 0x118, read_f32(W113_R2_781C_NEG4));
    write_f32(ride + 0x114, read_f32(W98_R2_5928_ZERO));

    let rate;
    let limit2;
    if variant != 0 {
        rate = read_f32(W113_DAT_802F5768);
        limit2 = if platform::call2(W98_FUN_80056CF0, ride as u32, 0x41) != 0 {
            read_f32(W113_DAT_802F5790)
        } else {
            read_f32(W113_DAT_802F5778)
        };
    } else if riding {
        rate = read_f32(W113_DAT_802F5764);
        limit2 = read_f32(W113_DAT_802F5774);
    } else {
        rate = read_f32(W96_R2_5840_0_3);
        if read_f32(ride + 0x10C).abs() < read_f32(W96_R2_5840_0_3) {
            limit2 = read_f32(W102_R2_588C);
        } else if busy {
            limit2 = read_f32(W113_DAT_802F5780);
        } else {
            limit2 = read_f32(W113_DAT_802F5770);
        }
    }
    let limit2 = if variant == 0 && read_f32(ride + 0x10C).abs() >= read_f32(W113_DAT_802F5764)
    {
        read_f32(W113_DAT_802F577C)
    } else {
        limit2
    };

    let facing_scale =
        read_f32(W113_FACING_SCALE_TABLE + platform::read_u8(ride + 0x348) as usize * 4);
    let yaw_target = limit2 * facing_scale;
    let sine = call_f64_f64(W106_FUN_80237C40, phase) as f32;
    let tilt_speed = facing_scale * (rate * sine);
    write_f32(ride + 0x2068, tilt_speed);

    let mut tilt = read_f32(W98_R2_5928_ZERO);
    let tilt_object = platform::read_u32(W104_SDA_5580) as usize;
    if read_f32(tilt_object + 0x8C0) != read_f32(W98_R2_5928_ZERO) {
        tilt = read_f32(W113_R2_5808_8_25);
    }
    let mut vertical = tilt_speed + read_f32(W96_R2_5840_0_3) * tilt;
    let mut turn = yaw_target + read_f32(W102_R2_588C) * tilt;
    if tilt_speed * tilt < read_f32(W98_R2_5928_ZERO) {
        if variant != 0 {
            vertical = tilt_speed + read_f32(W98_R2_5920_TENTH) * tilt;
            turn = yaw_target + read_f32(W113_R2_5804_0_0001) * tilt;
        } else if riding {
            vertical = tilt_speed + read_f32(W113_R2_5800_0_13) * tilt;
            if read_f32(ride + 0x10C).abs() >= read_f32(R2_58FC_ONE) {
                turn = yaw_target + read_f32(W113_R2_57FC_0_003) * tilt;
            }
        }
    }
    write_f32(ride + 0x110, vertical);
    write_f32(ride + 0x11C, turn.abs());
    if busy || riding || variant != 0 {
        write_f32(ride + 0x2064, read_f32(R2_58FC_ONE));
    } else {
        write_f32(ride + 0x2064, read_f32(W96_R2_5840_0_3));
    }
}

// ===========================================================================
// Wave 114: the last three entries of the `0x80110000` bucket.
//
// These are the per-frame tile pass of the WorldMap course background, the
// same object Wave 89 and Wave 100 reconstructed: `+0x3B8` points at a
// 66 x 34 grid of `0x10`-byte cells `[x, y, z, class]`, `+0x3F8`/`+0x3FC`
// are the two per-player grid records, `+0x3C4 + class * 0x24 + slot * 4`
// holds the nine tile records of each class, `+0x430` is one extra record
// used at column `1` of class `+0x434`, and `+0x5FC` is the rail matrix that
// `0x801194A0` rebuilds for `0x80119C50`. A cell whose class word is `9` is
// empty; classes `0..2` select one of the three record groups.
//
// All three records used to be skipped as "GQR reconstruction" bodies. The
// `GQR` blocks in their exports are the decompiler's rendering of the
// compiler's `psq_st`/`psq_l` saves of the non-volatile paired-single
// registers `ps28..ps31`; they carry no game data. Likewise the leading
// `FUN_802DCD54`/`FUN_802DCD60` and trailing `FUN_802DCDA0`/`FUN_802DCDAC`
// calls are the `__savegprlr_N`/`__restgprlr_N` prologue and epilogue
// helpers, not game calls: the object of each record is the incoming `r3`
// and is modelled as the `this` argument (see the Wave 3 note near
// [`wm_effect_slot_alloc`]). Both conventions are documented on the bodies.
// ===========================================================================

// --- new callee used only by wave 114 -------------------------------------
/// `0x8016A130`: stores three scale floats into the object bound to a tile
/// record (`record[1] + 0xDC..0xE4`).
const W114_FUN_8016A130: usize = 0x8016_A130;

/// Builds a GX translation matrix `(x, y, z)` at `out` through `0x801C0BD0`.
///
/// # Arguments
/// - `out`: twelve writable floats (a GX 3x4 matrix).
/// - `x`, `y`, `z`: translation words; the rotation part is written as identity.
///
/// # Safety
/// `out` must be writable for `0x30` bytes.
///
/// # Confidence
/// high - `0x801C0BD0` only ever writes `[3]`, `[7]` and `[0xB]` from its three
/// `f64` arguments and the two identity constants.
unsafe fn w114_translate(out: usize, x: f64, y: f64, z: f64) {
    call_f64_f64_f64_u32(FUN_801C0BD0, x, y, z, out as u32);
}

/// Concatenates the matrix at `rhs` onto `lhs` in place through `0x801C0540`.
///
/// # Safety
/// Both addresses must point at twelve readable floats and `lhs` must be
/// writable.
///
/// # Confidence
/// high - the export passes `(lhs, rhs, lhs)` literally at every site.
unsafe fn w114_concat(lhs: usize, rhs: usize) {
    platform::call3(FUN_801C0540, lhs as u32, rhs as u32, lhs as u32);
}

/// Re-binds every visible tile record and posts the closest one as a sound.
///
/// In plain English: one frame after the background becomes active, walk the
/// three visible grid groups, ask every tile record's model for the screen
/// position of both of its clips, apply the volcano effect to each clip while
/// remembering the clip closest to the projected scene centre, and post sound
/// event `0x2CD` at that closest position. On every later frame the same walk
/// only refreshes the per-clip bind byte through vtable slot `+0xB0`.
///
/// The collider object at `r13 - 0x5940` carries a "already armed" word at
/// `+0x30`: the body clears it and takes the first-frame path when it was
/// non-zero, and the refresh-only path when it was already zero.
///
/// # Original
/// - Ghidra: `FUN_80119240` at `0x80119240` (608 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80119240_FUN_80119240.c`
///
/// # Arguments
/// - `this`: course-background controller; reads `+0x4E4`, `+0x3C4..+0x430`
///   and `+0x5F4`/`+0x5F6`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Up to 54 virtual calls through [`fn_801191e0`] or
/// [`wm_volcano_effect_apply`], one collider word clear, and one
/// `0x8006A4B0` + `0x80198C30` sound post on the first frame.
///
/// # Safety
/// `this` must be live; the collider, the scene object read by
/// [`fn_80119140`] and the sound object at `r13 - 0x5920` must be non-null;
/// every non-null tile record must expose a readable vtable.
///
/// # Confidence
/// medium - the gate, the three loop bounds, the two vtable helpers, the
/// distance test and the sound post are literal. The exported record has no
/// declared argument and starts with `iVar9 = FUN_802dcd60()`; that address is
/// `__savegprlr_22`, which does not write `r3`, so the object is the incoming
/// `r3` and is modelled as `this`. The bytes at `+0x11` and `+0x14` are read as
/// the record's "exists"/"hit" flags because `0x80119C50` writes `+0x14`, and
/// `+0x5F4`/`+0x5F6` are the per-clip selector halfwords forwarded to
/// `0x80168230` (role inferred from the call shape).
pub unsafe fn fn_80119240(this: usize) {
    // observed: `(FUN_800b3b50(0xffffffff) == 0 && (r13-0x5986 & 0xF) == 0)
    // && *(int *)(this + 0x4E4) != 1` guards the whole body.
    if platform::call1(W100_FUN_800B3B50, 0xFFFF_FFFF) != 0
        || (platform::read_u8(W100_SDA_5986_INPUT) & 0xF) != 0
        || platform::read_u32(this + 0x4E4) == 1
    {
        return;
    }

    let collider = platform::read_u32(SDA_5940_OBJECT) as usize;
    let refreshing = platform::read_u32(collider + 0x30) == 0;
    if !refreshing {
        platform::write_u32(collider + 0x30, 0);
    }

    let mut centre = crate::platform::GuestLocal::new( [0f32; 2]);
    fn_80119140(centre.as_mut_ptr() as usize);

    // observed: the best position starts at the scene centre projected by
    // `0x80119140`, with `0.0` for Z, and the best distance at `1e6`.
    let mut best = crate::platform::GuestLocal::new( [0f32; 3]);
    best[0] = centre[0];
    best[1] = centre[1];
    best[2] = read_f32(W89_R2_5C1C_ZERO);
    let mut nearest = read_f32(W100_R2_5BB4_1E6) as f64;

    let mut group = 0;
    while group < 3 {
        let mut slot = 0;
        while slot < 9 {
            let record =
                platform::read_u32(this + group * 0x24 + slot * 4 + 0x3C4) as usize;
            if record != 0 {
                let head = platform::read_u32(record) as usize;
                if head != 0
                    && platform::read_u8(record + 0x11) != 0
                    && platform::read_u8(record + 0x14) != 0
                {
                    let mut clip: i32 = 0;
                    while clip < 2 {
                        let mut position = crate::platform::GuestLocal::new( [0f32; 3]);
                        // observed: both branches ask `0x80168230` for the clip
                        // position with the per-clip halfword at `+0x5F4`.
                        fn_80119230(
                            this as u32,
                            head as u32,
                            platform::read_u16(this + 0x5F4 + clip as usize * 2) as u32,
                            position.as_mut_ptr() as u32,
                        );
                        if refreshing {
                            if platform::read_u8(record + clip as usize + 0x12) != 0 {
                                // observed: `FUN_801191e0` (slot `+0xB0`).
                                fn_801191e0(record, position.as_mut_ptr() as u32, clip);
                            }
                        } else {
                            // observed: `FUN_80119180` (slot `+0xA0`, volcano).
                            wm_volcano_effect_apply(
                                record,
                                position.as_mut_ptr() as u32,
                                clip as usize,
                            );
                            let dx = (position[0] - centre[0]) as f64;
                            let dy = (position[1] - centre[1]) as f64;
                            let distance = dx * dx + dy * dy;
                            if distance < nearest {
                                best = position;
                                nearest = distance;
                            }
                        }
                        clip += 1;
                    }
                }
            }
            slot += 1;
        }
        group += 1;
    }

    if !refreshing {
        let mut record = crate::platform::GuestLocal::new( [0u8; 16]);
        platform::call2(
            FUN_8006A4B0,
            record.as_mut_ptr() as u32,
            best.as_ptr() as u32,
        );
        platform::call4(
            FUN_80198C30,
            platform::read_u32(SDA_5920_WORD),
            0x2CD,
            record.as_ptr() as u32,
            0,
        );
    }
}

/// Rebuilds the rail matrix at `+0x5FC` from the first non-empty grid cell of
/// the current column.
///
/// In plain English: look up the row of the current column in the grid at
/// `+0x3B8` (the class word `9` marks an empty cell, so it is the first cell
/// whose class is not `9`), store that row in `+0x5FA`, take the cell's X/Y
/// plus the `+0x480`/`+0x484` offsets and the `0x8011A100` base position, and
/// compose the rail matrix from the lift (`0x80116B10`), the depth
/// (`scene + 0x44`), the two rotation sources (`+0x498`/`+0x49C`) and the
/// `+0xDC`/`+0xE0` scale. `+0x5F0` selects the variant that drops the
/// horizontal cell term; a zero size class (`0x8011A1A0`) selects the short
/// fallback chain.
