    let grid = platform::read_u32(this + 0x3B8) as usize;
    let column = platform::read_u16(this + 0x5F8) as u32;

    // observed: `iVar7 = 0x231` four-cell steps = 561 * 4 = 2244 = 66 * 34
    // cells; `pfVar4[3] != 1.26117e-44` is the class word compared as a float,
    // and that constant is bit pattern `9` (the empty-cell marker).
