    let cell_x = (read_f32(cell) as f64 + read_f32(this + 0x480) as f64) as f32;
    let cell_y = (read_f32(cell + 4) as f64 + read_f32(this + 0x484) as f64) as f32;
    let size = fn_8011a1a0(this);

