const E230_FN_80047190: usize = 0x8004_7190;
const E230_FN_80069530: usize = 0x8006_9530;
const E230_FN_800B37B0: usize = 0x800B_37B0;
const E230_FN_80053120: usize = 0x8005_3120;
const E230_FN_80053540: usize = 0x8005_3540;
const E230_FN_8005E040: usize = 0x8005_E040;
const E230_FN_8005E2B0: usize = 0x8005_E2B0;
