const E230_FN_80275560: usize = 0x8027_5560;
const E230_FN_80046FC0: usize = 0x8004_6FC0;
const E230_FN_800D7020: usize = 0x800D_7020;

/// `r13 - 0x5460` = `0x80429C20`: global one-up/item gate word tested by the
/// enter body before selecting the per-player item state.
const E230_SDA_5460_GATE: usize = SDA_BASE - 0x5460;
/// `r13 - 0x54B8` = `0x80429BC8`: current WorldMap player object.
const E230_SDA_54B8_PLAYER: usize = SDA_BASE - 0x54B8;
/// `r13 - 0x547C` = `0x8042A204`: HUD/mode word; a zero value enables the
/// per-slot ownership-mask read in the enter body.
const E230_SDA_547C_HUD_MODE: usize = SDA_BASE - 0x547C;
/// `r13 - 0x51F8` = `0x8042DE88`: sound/effect system used for the per-child
/// sequence query and the archive lookup.
const E230_SDA_51F8_SOUND: usize = SDA_BASE - 0x51F8;

/// `r2 - 0x56D0` = `0x8042D9B0`: `6.0f`, the upper limit of the move-axis
/// smoothing in [`fn_801450a0`].
const E230_R2_56D0_SIX: usize = SDA2_BASE - 0x56D0;
/// `r2 - 0x5904` = `0x8042D77C`: `3.0f`, the per-frame step of the two move
/// axes in [`fn_801450a0`].
const E230_R2_5904_THREE: usize = SDA2_BASE - 0x5904;

/// `0x80354E60`: per-player byte-to-slot index used by the enter body.
const E230_TBL_80354E60: usize = 0x8035_4E60;
/// `0x80354E80`: per-slot flag words; bit `0` selects the `0x294` post.
const E230_TBL_80354E80: usize = 0x8035_4E80;

// ---------------------------------------------------------------------------
// 0x80144D60 - table slot 0 (vtable +0x08): map-object enter/init
// ---------------------------------------------------------------------------

/// Builds the WorldMap map object's visible state and per-player bindings.
///
/// The body releases the embedded display wrapper, republishes the item/state
/// word (`+0x1090`) at `+0x14DC`/`+0x14E0`, copies lane bit `0x00800000` of
/// the actor word at `+0x04` into the terrain byte `+0x348`, and seeds the
/// floating state: `0.0` into `+0xF4`..`+0xFC`, `-4.0` into `+0x118`,
/// `1.0` into `+0xDC`/`+0xE0`/`+0xE4`/`+0x1544`, and the first word of the
/// pointer returned by vtable `+0x3C4` into `+0x114`. It then clears the two
/// `+0x2A78`/`+0x1008`/`+0x100C` words, selects mode `1`/`0` from vtable
/// `+0xE0`, copies the position triple into `+0x152C`, binds the display
/// wrapper at `+0x2BA8`, resets the contact record, posts the low byte of
/// `+0x04`'s bits `8..15` to vtable `+0x270`, and builds the model transform.
///
/// The remaining block (only when the `r13 - 0x5460` gate is clear and the
/// current player's `+0x120D` byte is not `0x28`) selects the per-player slot
/// through `0x80354E60[+0x38D]`, posts either `0x294` (bit 0 of
/// `0x80354E80[slot]`) or the per-slot `r13 - 0x59D0` halfword to vtable
/// `+0x3D8`, writes the `r13 - 0x59C8` halfword to `+0x1081`, and finally
/// stores the ownership mask (`0x80069530(+0x38D)`) at `+0xE44` when vtable
/// `+0xE0` and the `r13 - 0x547C` mode word are both zero.
///
/// # Original (untabled)
/// - Address: `0x80144D60`, 736 B (`bclr 20,0` at `0x8014503C`; the next
///   `functions.tsv` entry is `0x80145040`)
/// - Table: slot 0 of `0x80325428`, i.e. vtable `0x80325420 + 0x08`
/// - Reach: `vcall(object, 0x08)` through the map object's `+0x60` vtable
/// - Not in `functions.tsv`; no Ghidra export
///
/// # Arguments
/// - `this`: the `0x2D08`-byte WorldMap map object.
///
/// # Returns
/// `1` unconditionally.
///
/// # Side effects
/// Calls the display release/bind helpers, `0x80056C30(this, 0)`,
/// `0x8004D5A0`, `0x80046A50`, `0x80069530`, the contact reset
/// [`fn_801434e0`], the two [`fn_801434c0`]/[`fn_801434e0`] resets,
/// [`fn_80145650`] and `0x800D1500(this + 0x14FC, this, 1)`; posts vtable
/// `+0xE4`, `+0x444`, `+0x3C4`, `+0xE0`, `+0x270`, `+0x3D8`; writes the fields
/// listed above and `+0x102`, `+0x348`, `+0x1081`, `+0xE44`, `+0xE98`.
///
/// # Safety
/// `this` must be a live map object with a valid `+0x60` vtable, a bound
/// display wrapper at `+0x2A60`, and readable per-player tables. The
/// `+0x1090` index must select a valid `0x80354E60` slot.
///
/// # Confidence
/// high - every load, store, slot offset and table index is a literal
/// transcription of the 194-instruction body.
pub unsafe fn fn_80144d60(this: usize) -> u32 {
    let item = platform::read_u32(this + 0x1090);

    // observed: `addi r3,r3,0x2A60` before the release; `r4`/`r5` are dead.
    platform::call1(E230_FN_800D6DF0, (this + 0x2A60) as u32);

    platform::write_u32(this + 0x14E0, item);
    platform::write_u32(this + 0x14DC, item);
    let _ = vcall60_2(this, 0xE4, item, 1);

    // observed: `rlwinm r4,r0,8,31,31` = bit 23 of the actor word.
    let actor_word = platform::read_u32(this + 0x04);
    platform::write_u8(this + 0x348, ((actor_word >> 23) & 1) as u8);

    // observed: slot `+0x444` returns a halfword stored at `+0x102`.
    let low = vcall60_0(this, 0x444);
    platform::write_u16(this + 0x102, low as u16);

    write_f32(this + 0xF4, read_f32(R2_5928_ZERO));
    write_f32(this + 0xF8, read_f32(R2_5928_ZERO));
    write_f32(this + 0xFC, read_f32(R2_5928_ZERO));
    write_f32(this + 0x118, read_f32(R2_781C_NEG4));

    let source = vcall60_0(this, 0x3C4) as usize;
    write_f32(this + 0x114, read_f32(source));

    let one = read_f32(R2_58FC_ONE);
    write_f32(this + 0xDC, one);
    write_f32(this + 0xE0, one);
    write_f32(this + 0xE4, one);
    write_f32(this + 0x1544, one);

    let _ = platform::call2(E230_FN_80056C30, this as u32, 0);
    platform::write_u32(this + 0x2A78, 0);
    platform::write_u32(this + 0x1008, 0);
    platform::write_u32(this + 0x100C, 0);

    let mode = if vcall60_0(this, 0xE0) != 0 { 1 } else { 0 };
    wm_set_mode_byte(this, mode);

    write_f32(this + 0x152C, read_f32(this + 0xAC));
    write_f32(this + 0x1530, read_f32(this + 0xB0));
    write_f32(this + 0x1534, read_f32(this + 0xB4));
    let _ = platform::call2(E230_FN_800D8280, (this + 0x2BA8) as u32, this as u32);

    fn_801434c0(this);
    fn_801434e0(this);

    // observed: `rlwinm r4,r0,16,24,31` = `(actor_word >> 8) & 0xFF`.
    let _ = vcall60_1(this, 0x270, (platform::read_u32(this + 0x04) >> 8) & 0xFF);

    fn_80145650(this);
    let _ = platform::call3(
        E230_FN_800D1500,
        (this + 0x14FC) as u32,
        this as u32,
        1,
    );

    if platform::read_u32(E230_SDA_5460_GATE) == 0 {
        let player = platform::read_u32(E230_SDA_54B8_PLAYER) as usize;
        if platform::read_u8(player + 0x120D) != 0x28 {
            // observed: `lbz` + `extsb` of the per-player slot byte.
            let index = (platform::read_u8(this + 0x38D) as i8) as u32;
            let slot = platform::read_u32(E230_TBL_80354E60 + index as usize * 4);
            let flags = platform::read_u32(E230_TBL_80354E80 + slot as usize * 4);
            if flags & 1 != 0 {
                let _ = vcall60_2(this, 0x3D8, 2, 0x294);
            } else {
                let word = platform::read_u16(W101_SDA_59D0 + index as usize * 2) as u32;
                if word != 0 {
                    let _ = vcall60_2(this, 0x3D8, 2, word);
                }
                let value = platform::read_u16(W101_SDA_59C8 + index as usize * 2) as u32;
                platform::write_u8(this + 0x1081, value as u8);
            }
        }
    }

    if vcall60_0(this, 0xE0) == 0 && platform::read_u32(E230_SDA_547C_HUD_MODE) == 0 {
        let slot = (platform::read_u8(this + 0x38D) as i8) as u32;
        let mask = platform::call1(E230_FN_80069530, slot);
        platform::write_u32(this + 0xE44, mask);
    }

    // observed: a four-way select with a zero default for values above 3.
    let state = platform::read_u32(this + 0x14D4);
    let selected = if state <= 3 { state } else { 0 };
    platform::write_u32(this + 0xE98, selected);

    let _ = platform::call1(E230_FN_8004D5A0, this as u32);
    let _ = platform::call1(E230_FN_80046A50, this as u32);

    // observed: `extsb` of the slot byte stored as a full word.
    let index = (platform::read_u8(this + 0x38D) as i8) as u32;
    platform::write_u32(this + 0xEA4, index);
    1
}

// ---------------------------------------------------------------------------
// 0x80144AA0 - table slot 3 (vtable +0x14): pickup gate + map reset
// ---------------------------------------------------------------------------

/// Re-arms the item pickup and resets the contact record.
///
/// When [`fn_80147680`] accepts the current player but the class predicate
/// (`+0xE0`) is zero, the slot byte `+0x38D` is handed to `0x800B37B0(slot, 1)`
/// (the pickup notification). The body then always runs the per-player copy
/// [`fn_80144b20`] and the interface notification `0x80047190`.
///
/// # Original (untabled)
/// - Address: `0x80144AA0`, 116 B (`bclr` at `0x80144B10`)
/// - Table: slot 3 of `0x80325428`, i.e. vtable offset `+0x14`
/// - Reach: `vcall(object, 0x14)`
/// - Not in `functions.tsv`; no Ghidra export
///
/// # Arguments
/// - `this`: the WorldMap map object.
///
/// # Returns
/// `1` unconditionally.
///
/// # Side effects
/// May call `0x800B37B0`; always calls [`fn_80144b20`] and `0x80047190`, which
/// writes `+0x6F4`, raises event flag `0xB5` and notifies the `+0x1464`
/// interface.
///
/// # Safety
/// `this` must be live, `+0x60` must hold the map vtable and the globals used
/// by [`fn_80147680`] must be initialised.
///
/// # Confidence
/// high - the guard chain, the two calls and the constant `1` are literal.
pub unsafe fn fn_80144aa0(this: usize) -> u32 {
    if fn_80147680() != 0 && vcall60_0(this, 0xE0) == 0 {
        let slot = (platform::read_u8(this + 0x38D) as i8) as u32;
        let _ = platform::call2(E230_FN_800B37B0, slot, 1);
    }
    fn_80144b20(this);
    let _ = platform::call1(E230_FN_80047190, this as u32);
    1
}

// ---------------------------------------------------------------------------
// 0x80046BB0 - table slot 6 (vtable +0x20): per-child sound/ramp update
// ---------------------------------------------------------------------------

/// Updates the map object's child sound handles and their three ramp fields.
///
/// The body first scans the four handles at `+0xDEC` (stride `0x10`, word
/// `+0x08`). If every one of them is positive the frame is skipped; otherwise
/// it walks the `+0xE40` child records at `+0xE60` (stride 8). For each
/// non-null child it queries the sound system with the child id (`child +
/// 0x9C`, or `-1`), and dispatches on the returned flag bits:
///
/// * bit 0 clear - call `0x80267420(f32 +0xE50, child, 0)` (ramp target) when
///   `child != 0`;
/// * bit 0 set - the same call, but only while the sound system's `+0x14`
///   word is `3`, or `2` with `+0x10 == 3`;
/// * bit 3 - query the archive record `0x80275780(sound + 0x100, id, out)`
///   and store `out[3] + *(i32 *)(this + 0xE54)` (or `out[3]` when the offset
///   is negative) as the child's `+0x98` mode byte via `0x80267390`;
/// * bit 1 - store `f32 +0xE5C` at `child + 0xB4` via `0x802674C0`.
///
/// # Original (untabled)
/// - Address: `0x80046BB0`, 572 B (`bclr` at `0x80046DE8`)
/// - Table: slot 6 of `0x80325428`, i.e. vtable offset `+0x20`
/// - Reach: `vcall(object, 0x20)`
/// - Not in `functions.tsv`; no Ghidra export
///
/// # Arguments
/// - `this`: the map object; `+0xDEC` is the handle array, `+0xE40` the child
///   count, `+0xE60` the child pointer array (stride 8), `+0xE50`/`+0xE54`/
///   `+0xE5C` the ramp value/offset/rate, `+0xEA4` the move-state block.
///
/// # Returns
/// `1` unconditionally.
///
/// # Side effects
/// `0x80053120(this)`, `0x80056CF0(this, 111)`, `0x8005E3B0(+0xEA4, 0)`,
/// `0x8005E040(+0xEA4)`, `0x80053540(this)`, `0x8005E2B0(+0xEA4)`, the
/// `+0x424`/`+0xD4` vtable slots, `0x8006CED0`/`0x8006A4B0` (two position
/// reads), the per-child calls above, and writes `+0xE90`/`+0xE94`.
///
/// # Safety
/// The handle array, the child records and the sound system must be live; each
/// non-null child pointer must be a valid ramp/handle object.
///
/// # Confidence
/// high - every offset, the two loops, the flag masks (`1`, `8`, `2` of the
/// inverted status word) and all call arguments are literal.
pub unsafe fn fn_80046bb0(this: usize) -> u32 {
    let _ = platform::call1(E230_FN_80053120, this as u32);
    if platform::call2(E230_FN_80056CF0, this as u32, 111) != 0 {
        let _ = platform::call2(E230_FN_8005E3B0, (this + 0xEA4) as u32, 0);
    }
    let _ = platform::call1(E230_FN_8005E040, (this + 0xEA4) as u32);

    let _ = vcall60_0(this, 0x424);
    let _ = platform::call1(E230_FN_80053540, this as u32);
    let _ = vcall60_0(this, 0xD4);
    let _ = platform::call1(E230_FN_8005E2B0, (this + 0xEA4) as u32);

    let mut position_a = crate::platform::GuestLocal::new( [0u32; 4]);
    let mut position_b = crate::platform::GuestLocal::new( [0u32; 2]);
    platform::call2(
        E230_FN_8006CED0,
        position_a.as_mut_ptr() as u32,
        this as u32,
    );
    platform::call2(
        E230_FN_8006A4B0,
        position_b.as_mut_ptr() as u32,
        position_a.as_mut_ptr() as u32,
    );
    write_f32(this + 0xE90, f32::from_bits(position_b[0]));
    write_f32(this + 0xE94, f32::from_bits(position_b[1]));

    // observed: up to four handle slots at `+0xDEC`; a non-positive handle
    // ends the scan and enters the child loop.
    let mut index: u32 = 0;
    while index < 4 {
        let handle = platform::call2(E230_FN_80275560, (this + 0xDEC) as u32, index) as i32;
        if handle <= 0 {
            break;
        }
        index += 1;
    }
    if index == 4 {
        return 1;
    }

    let sound = platform::read_u32(E230_SDA_51F8_SOUND) as usize;
    let count = platform::read_u32(this + 0xE40);
    let mut child_index = 0u32;
    while child_index < count {
        let record = this + 0xE60 + child_index as usize * 8;
        let child = platform::read_u32(record) as usize;
        if child != 0 {
            let id = if child != 0 {
                platform::read_u32(child + 0x9C)
            } else {
                u32::MAX
            };
            let status = platform::call2(E230_FN_80196660, sound as u32, id);

            if status & 1 == 0 {
                if child != 0 {
                    crate::resource::archive::fn_80267420(
                        read_f32(this + 0xE50) as f64,
                        child,
                        0,
                    );
                }
            } else {
                let system = platform::read_u32(SDA_51D8_PTR) as usize;
                let mode = platform::read_u32(system + 0x14);
                let fire = mode == 3
                    || (mode == 2 && platform::read_u32(system + 0x10) == 3);
                if fire && child != 0 {
                    crate::resource::archive::fn_80267420(
                        read_f32(this + 0xE50) as f64,
                        child,
                        0,
                    );
                }
            }

            if status & 8 != 0 {
                let archive = platform::read_u32(sound + 0x100);
                let mut out = crate::platform::GuestLocal::new( [0u32; 8]);
                platform::call3(
                    E230_FN_80275780,
                    archive,
                    id,
                    out.as_mut_ptr() as u32,
                );
                let offset = platform::read_u32(this + 0xE54) as i32;
                if child != 0 {
                    let value = if offset < 0 {
                        out[3]
                    } else {
                        out[3].wrapping_add(offset as u32)
                    };
                    platform::call2(E230_FN_80267390, child as u32, value);
                }
            }

            if status & 2 != 0 && child != 0 {
                crate::resource::archive::fn_802674c0(
                    child,
                    read_f32(this + 0xE5C),
                );
            }
        }
        child_index += 1;
    }
    1
}

// ---------------------------------------------------------------------------
// 0x801450A0 - table slot 8 (vtable +0x28): two-axis move-state update
// ---------------------------------------------------------------------------

/// Drives the two smoothed move axes and the state transition for mode `2`.
///
/// For any mode other than `2` the body is a tail call to
/// `0x80046FC0(this, mode)`. For mode `2` it caches the position triple,
/// substitutes the linked actor's `+0xAC` when [`fn_8013aaa0`] returns one,
/// and then, unless the mode byte `+0x153C` is already `3`:
///
/// * when `+0x1538` is set, steps `+0x152C`/`+0x1530` toward the cached
///   `x`/`y` by `3.0` using `0x8015F470` (the arrival flag is the OR of the
///   two "not arrived" results) and clears `+0x1538` when both axes arrived;
/// * otherwise runs the four-constant smoother `0x8015F140(x, 0.25, 6.0,
///   0.1, axis)` on both axes.
///
/// It then selects mode `5` when flag `92` is set, or mode `0` when the mode
/// byte is `5`, and always finishes with `0x80046FC0(this, mode)`.
///
/// # Original (untabled)
/// - Address: `0x801450A0`, 336 B (`bclr` at `0x801451EC`)
/// - Table: slot 8 of `0x80325428`, i.e. vtable offset `+0x28`
/// - Reach: `vcall(object, 0x28)` with the requested mode in `r4`
/// - Not in `functions.tsv`; no Ghidra export
///
/// # Arguments
/// - `this`: the WorldMap map object.
/// - `mode`: requested move mode; only `2` runs the body.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x152C`, `+0x1530`, `+0x1538` and the mode byte `+0x153C`; calls
/// [`fn_8013aaa0`], `0x8015F470`/`0x8015F140`, `0x80056CF0(this, 92)` and
/// `0x80046FC0`.
///
/// # Safety
/// `this` must be live with a readable `+0x60` vtable, and the two `f32`
/// fields at `+0x152C`/`+0x1530` must be writable.
///
/// # Confidence
/// high - the mode guard, both smoothing paths and every constant are literal.
pub unsafe fn fn_801450a0(this: usize, mode: u32) {
    if mode != 2 {
        let _ = platform::call2(E230_FN_80046FC0, this as u32, mode);
        return;
    }

    let mut x = read_f32(this + 0xAC);
    let y = read_f32(this + 0xB0);
    let linked = fn_8013aaa0(this) as usize;
    if linked != 0 {
        x = read_f32(linked + 0xAC);
    }

    if platform::read_u8(this + 0x153C) != 3 {
        if platform::read_u32(this + 0x1538) != 0 {
            let step = read_f32(E230_R2_5904_THREE);
            let mut pending = false;
            if crate::engine::display::fn_8015f470(
                x as f64,
                step as f64,
                (this + 0x152C) as *mut f32,
            ) == 0
            {
                pending = true;
            }
            if crate::engine::display::fn_8015f470(
                y as f64,
                step as f64,
                (this + 0x1530) as *mut f32,
            ) == 0
            {
                pending = true;
            }
            if !pending {
                platform::write_u32(this + 0x1538, 0);
            }
        } else {
            let rate = read_f32(W90_R2_56C0_0_25);
            let limit = read_f32(E230_R2_56D0_SIX);
            let deadband = read_f32(R2_5920_0_1);
            crate::engine::display::fn_8015f140(
                x as f64,
                rate as f64,
                limit as f64,
                deadband as f64,
                (this + 0x152C) as *mut f32,
            );
            crate::engine::display::fn_8015f140(
                y as f64,
                rate as f64,
                limit as f64,
                deadband as f64,
                (this + 0x1530) as *mut f32,
            );
        }
    }

    if platform::call2(E230_FN_80056CF0, this as u32, 92) != 0 {
        wm_set_mode_byte(this, 5);
    } else if platform::read_u8(this + 0x153C) == 5 {
        wm_set_mode_byte(this, 0);
    }

    let _ = platform::call2(E230_FN_80046FC0, this as u32, mode);
}

