///
/// # Safety
/// The position, anchor and direction fields must be readable/writable.
///
/// # Confidence
/// high - both blocks are instruction-for-instruction identical.
#[inline]
unsafe fn b238_toggle_anchor(this: usize) {
    let direction = platform::read_u32(this + 0x460) ^ 1;
    platform::write_u32(this + 0x460, direction);
    let sign = read_f32(B238_TABLE_8042B840 + direction as usize * 4);
    let step = read_f32(B238_R2_76C4_24) * sign;
    write_f32(this + 0x450, read_f32(this + 0xAC) + step);
}

