/// Calls virtual slot `slot` of `object` with one integer and three `f32`
/// arguments.
///
/// The slot is reached through the object's own vtable at `+0x00`, as the map
/// block does, and the singles are passed in the EABI double-precision FPRs.
///
/// # Safety
/// `object` must be live and the slot must accept `(object, u32, f64, f64, f64)`.
#[inline]
unsafe fn d240_vcall_u32_f32x3(
    object: usize,
    slot: usize,
    arg: u32,
    a: f32,
    b: f32,
    c: f32,
) -> u32 {
    let vtable = platform::read_u32(object) as usize;
    let entry = platform::read_u32(vtable + slot) as usize;
    let f = crate::platform::guest_fn!(entry, fn(usize, u32, f64, f64, f64) -> u32);
    f(object, arg, a as f64, b as f64, c as f64)
}

/// Calls `addr` with eight integer arguments and returns its `r3`.
///
/// # Safety
/// `addr` must point at a function with this prototype and every argument must
/// satisfy it.
#[inline]
unsafe fn d240_call8(
    addr: usize,
    a: u32,
    b: u32,
    c: u32,
    d: u32,
    e: u32,
    f: u32,
    g: u32,
    h: u32,
) -> u32 {
    let call = crate::platform::guest_fn!(addr, fn(u32, u32, u32, u32, u32, u32, u32, u32) -> u32);
    call(a, b, c, d, e, f, g, h)
}

