    platform::write_u8(this + 0x348, 0);
    write_f32(this + 0xE8, 0.0);
    write_f32(this + 0xEC, 0.0);
    write_f32(this + 0xF0, 0.0);
    platform::write_u32(this + 0x145C, 0x3C);
