/// high - both name tokens, both flag ids, the flag set and the three stores are
/// literal; the branch structure is preserved rather than merged because each
/// arm repeats the record lookup.
pub unsafe fn fn_80126510(this: usize, vector: usize) -> u32 {
    let record = vcall0(this + 0x1464, 0x28) as usize;
    if vcall1(record, 0x10, DATA_80375E2C as u32) != 0
        && crate::game::player::fn_80056cf0(this, 0x1C) != 0
    {
        crate::game::player::fn_80056c70(this, 0x22);
        write_f32(this + 0x14B0, read_f32(vector));
        write_f32(this + 0x14B4, read_f32(vector + 4));
        write_f32(this + 0x14B8, read_f32(vector + 8));
        return 1;
    }
    let record = vcall0(this + 0x1464, 0x28) as usize;
    if vcall1(record, 0x10, D246_DATA_80375F70 as u32) != 0
        && crate::game::player::fn_80056cf0(this, 0x1F) != 0
    {
        crate::game::player::fn_80056c70(this, 0x22);
        write_f32(this + 0x14B0, read_f32(vector));
        write_f32(this + 0x14B4, read_f32(vector + 4));
        write_f32(this + 0x14B8, read_f32(vector + 8));
        return 1;
    }
    0
}

