                    let old_x = read_f32(object + 0xAC);
                    let old_y = read_f32(object + 0xB0);
                    let old_z = read_f32(object + 0xB4);
                    let height = read_f32(object + 0x5A8);
                    position = [old_x, old_y, old_z];
                    write_f32(object + 0xAC, height);
                    write_f32(object + 0xB8, height);
                    write_f32(object + 0xBC, old_y);
                    write_f32(object + 0xC0, old_z);
