/// - Prologue `stwu sp,-0x30` / `bl 0x802DCD64` (`_savegpr_22`); epilogue
///   `bl 0x802DCDB0` (`_restgpr_22`)
/// - Not in `functions.tsv`; no Ghidra export
/// - observed: the five unrolled owner stores are `0x1C8`, `0x42C`, `0x690`,
///   `0x8F4` and `0xB58`, i.e. `record_i + 0x1C8` for `i = 0..4`
///
/// # Arguments
/// * `this` - controller whose `+0x70` layout and `+0x144 + i * 0x264` record
///   array are initialised.
///
/// # Returns
/// `1` on success or when already initialised, `0` when the arc fails to load.
///
/// # Side effects
/// Loads the arc, builds five layouts, writes the record fields and sets
/// `+0xD38`.
///
/// # Safety
/// `this` must be the `0x8010C050`-constructed controller and the five records
/// must be writable.
///
/// # Confidence
/// medium - every call, offset and constant is literal; the pane/name roles are
/// `// inferred:` from the `P_cursor` / `N_cursor` string block at
/// `0x80322700..0x8032275C`.
pub unsafe fn fn_8010c200(this: usize) -> u32 {
    if platform::read_u8(this + 0xD38) != 0 {
        return 1;
    }

    let layout = this + 0x70;
    if platform::call2(
        W286_FUN_80006BE0,
        layout as u32,
        W286_ARC_SELECT_CURSOR as u32,
    ) == 0
    {
        return 0;
    }

    // observed: five unrolled `record_i + 0x1C8` owner stores.
    platform::write_u32(this + 0x1C8, layout as u32);
    platform::write_u32(this + 0x42C, layout as u32);
    platform::write_u32(this + 0x690, layout as u32);
    platform::write_u32(this + 0x8F4, layout as u32);
    platform::write_u32(this + 0xB58, layout as u32);

    for index in 0..5usize {
        let record = this + index * 0x264;
        let child = this + 0x144 + index * 0x264;
        let roots = this + 0x2E0 + index * 0x264;
        let names = this + 0x2F0 + index * 0x264;

        w286_vcall8_2(child, 0x14, W286_BRLYT_SELECT_CURSOR as u32, 0);
        platform::call3(
            W286_FUN_800C8FB0,
            child as u32,
            W286_SDA_6488 as u32,
            1,
        );
        platform::call4(
            W286_FUN_800C90F0,
            child as u32,
            W286_SDA_6484 as u32,
            W286_R2_3488 as u32,
            1,
        );
        let root = platform::call1(W286_FUN_80007220, child as u32);
        platform::write_u32(record + 0x2DC, root);
        platform::call4(
            W286_FUN_800C8E40,
            child as u32,
            W286_DATA_80322740 as u32,
            roots as u32,
            4,
        );
        platform::call4(
            W286_FUN_800C8D60,
            child as u32,
            W286_DATA_8032275C as u32,
            names as u32,
            5,
        );

        let node = platform::read_u32(record + 0x2DC) as usize;
        platform::write_u8(node + 0xBB, platform::read_u8(node + 0xBB) & 0xFE);
        fn_8010c780(this, index as u32);
        platform::write_u8(record + 0x150, if index == 4 { 0x0E } else { 0x93 });
        platform::call2(W286_FUN_800C9380, child as u32, 0);
    }

    platform::write_u8(this + 0xD38, 1);
    1
}

