/// Resets and activates the ice projectile.
///
/// The `+0x04` flag word selects the player (bits 0..1), the spawn kind
/// (bits 16..17), the layer (bits 8..9 group) and two more two-bit fields
/// (bits 12..13 and bit 4). The body first rejects the spawn through
/// [`fn_801245c0`], increments the two per-player counters, seeds the motion
/// and collision fields, probes the floor, and finally publishes the position
/// and the `+0x394` event.
///
/// # Original (untabled)
/// - Ghidra: none - no `functions.tsv` row and no export file for `0x80123330`.
/// - Extent: `0x80123330..0x801235DC` (684 bytes, 171 words); one zero word
///   follows, then [`fn_801235e0`] at `0x801235E0`.
/// - Table: slot 0 of the `0x80324778` array (header `0x80324770`; word
///   `0x80324778`, offset `+0x000`).
/// - observed: `lwz r4,4(r3)`; `rlwinm 0,30,31`/`rlwinm 16,30,31`; `bl
///   0x801245C0`; `stw 60,0x3D0`; `lwzx`/`addi 1`/`stwx` on both counter
///   tables; `bl 0x80075270`; `bl 0x801237F0`; `bl 0x80123740`;
///   `bl 0x80123A00`; `bl 0x8006A4B0`; `bl 0x80198C30`; `ori 0x80` at
///   `+0x120`; `stfs 0,0xD0/0xD4/0xD8`; `stb 5,0x36D`; `bl 0x8008E770`;
///   `bl 0x8008C3E0`; `bl 0x8008C330`; `lwzu r12,0x40C` + `lwz 8`; `bl
///   0x80075CA0`; `fsubs`/`fcmpo` against 6.0; `bl 0x8006D090`;
///   `lwz r12,0x394` + `lwz 0x18`.
///
/// # Arguments
/// - `this`: ice projectile; `+0x04` flags, `+0xAC..+0xB4` position,
///   `+0x38D` player, `+0x38F` layer, `+0x3F0`/`+0x394`/`+0x40C` sub-objects.
///
/// # Returns
/// `1` when the projectile activates, `0` when [`fn_801245c0`] rejects the
/// spawn or the floor test sends it into the failure path.
///
/// # Side effects
/// Up to two counter increments, roughly thirty field writes, four geometry
/// calls, one sound event, one collision registration and two virtual calls.
///
/// # Safety
/// `this` must be a live `0x430`-byte actor with initialised `+0x394`/
/// `+0x40C` sub-objects; the course/counter globals must be mapped.
///
/// # Confidence
/// high - every branch, store, offset and constant is literal. The signed
/// `neg`/`or`/`slwi` sign test at `0x8012362C` is the mirror of the
/// `bc 4,2` skip in [`fn_801235e0`].
pub unsafe fn fn_80123330(this: usize) -> u32 {
    let flags = platform::read_u32(this + 0x04);
    let player = (flags & 3) as i32;
    platform::write_u8(this + 0x38D, player as u8);
    let kind = ((flags >> 16) & 3) as i32;
    if fn_801245c0(player, kind) == 0 {
        crate::resource::registry::fn_80162510(this);
        return 0;
    }

    platform::write_u32(this + 0x3D0, 60);

    let slot = player as usize * 4;
    let counter_a = G_80375AA8 + slot;
    let counter_b = G_80375AB8 + slot;
    platform::write_u32(
        counter_a,
        platform::read_u32(counter_a).wrapping_add(1),
    );
    platform::write_u32(
        counter_b,
        platform::read_u32(counter_b).wrapping_add(1),
    );

    let lane = ((flags >> 8) & 3) as u8;
    platform::write_u8(this + 0x38F, lane);
    platform::write_u8(this + 0x1E8, lane);
    platform::write_u8(this + 0x2D8, lane);
    let other = ((flags >> 12) & 3) as u8;
    platform::write_u8(this + 0x1E7, other);
    platform::write_u8(this + 0x2D1, other);
    platform::write_u8(this + 0x30A, other);

    let probe_code = crate::game::stage::fn_80075270(
        read_f32(this + 0xAC) as f64,
        read_f32(this + 0xB0) as f64,
        lane as u32,
        this + 0x3E0,
    );
    platform::write_u32(this + 0x3DC, probe_code as u32);
    platform::write_u8(this + 0x348, ((flags >> 4) & 1) as u8);

    let mut height = crate::platform::GuestLocal::<f32>::new( 0.0f32);
    if fn_801237f0(this, ((height.as_mut_ptr() as *mut f32)) as usize) != 0 {
        write_f32(this + 0xB0, *height + read_f32(R2_5A04_TEN));
    }

    if fn_80123740(this) != 0 {
        fn_80123a00(this);
        let sound = platform::read_u32(SDA_5920_WORD);
        let mut record = crate::platform::GuestLocal::new( [0u8; 16]);
        crate::game::player::fn_8006a4b0(record.as_mut_ptr() as usize, this + 0xAC);
        crate::audio::ax::fn_80198c30(sound, 617, record.as_ptr() as u32, 0);
        crate::resource::registry::fn_80162510(this);
        return 0;
    }

    platform::write_u32(this + 0x120, platform::read_u32(this + 0x120) | 0x80);
    write_f32(this + 0xD0, read_f32(R2_5A10_ZERO));
    write_f32(this + 0xD4, read_f32(R2_5A10_ZERO));
    write_f32(this + 0xD8, read_f32(R2_5A10_ZERO));
    platform::write_u8(this + 0x36D, 5);

    let info = platform::read_u32(W286_SDA_COURSE_INFO) as usize;
    let table = platform::read_u32(W286_SDA_COURSE_TABLE) as usize;
    let index = platform::read_u8(info + W286_COURSE_INDEX) as usize;
    let record = table + index * W286_COURSE_STRIDE;
    let course = if platform::read_u32(record + 0x2C) != 0 {
        record
    } else {
        0
    };
    let section = crate::resource::course::section4b_entry_at_point(course, this + 0xAC);
    platform::write_u8(this + 0x349, section);

    crate::game::stage::collision_area_set_descriptor(
        this + 0x148,
        this as u32,
        W286_G_802F4D34,
    );
    platform::write_u8(this + 0x1E8, platform::read_u8(this + 0x38F));
    crate::game::stage::collision_area_register(this + 0x148);

    vcall2(this + 0x40C, 0x08, (this + 0x3F0) as u32, 3);

    let mut probe = crate::platform::GuestLocal::new( [0u32; 3]);
    probe[0] = platform::read_u32(this + 0xAC);
    probe[1] = (read_f32(this + 0xB0) + read_f32(R2_5A04_TEN)).to_bits();
    probe[2] = platform::read_u32(this + 0xB4);
    let mut ground = crate::platform::GuestLocal::<f32>::new( 0.0f32);
    let found = crate::game::stage::fn_80075ca0(
        probe.as_ptr() as usize,
        ((ground.as_mut_ptr() as *mut f32)) as usize,
        platform::read_u8(this + 0x38F) as u32,
        1,
    );
    if found != 0 {
        let candidate = *ground - read_f32(W286_F32_SDA2_5A08);
        if candidate > read_f32(this + 0xB0) {
            write_f32(this + 0xB0, candidate);
        }
    }

    crate::game::player::fn_8006d090(
        this + 0x1EC,
        this,
        W286_G_802F4D10 as u32,
        W286_G_802F4D1C as u32,
        W286_G_802F4D28 as u32,
    );
    platform::write_u32(this + 0x3D4, 0);
    write_f32(this + 0x3E4, read_f32(this + 0xAC));
    write_f32(this + 0x3E8, read_f32(this + 0xB0));
    write_f32(this + 0x3EC, read_f32(this + 0xB4));
    let sound = platform::read_u32(SDA_5920_WORD);
    vcall1(this + 0x394, 0x18, sound.wrapping_add(0x30));
    1
}

