const W287_FUN_80078C10: usize = 0x8007_8C10;
/// `0x80078300` / `0x800D8670`: scene layout refresh pair.
const W287_FUN_80078300: usize = 0x8007_8300;
const W287_FUN_800D8670: usize = 0x800D_8670;
/// `0x80156930` / `0x80156AB0`: left/right edge probes of one 0x44-byte record.
const W287_FUN_80156930: usize = 0x8015_6930;
const W287_FUN_80156AB0: usize = 0x8015_6AB0;
/// `0x80154E50`: counts the players whose `+0x1530` lies inside a band and
/// returns the four-bit mask.
const W287_FUN_80154E50: usize = 0x8015_4E50;

/// Steps one `f32` through the translated easing helper.
///
/// # Safety
/// `value` must be a writable `f32`.
#[inline]
unsafe fn w287_step(value: usize, target: f32, rate: f32, limit: f32, deadband: f32) {
    let _ = crate::engine::display::fn_8015f140(
        target as f64,
        rate as f64,
        limit as f64,
        deadband as f64,
        value as *mut f32,
    );
}

/// Calls a no-argument function and keeps its `r3`.
///
/// # Safety
/// `addr` must point to that ABI.
#[inline]
unsafe fn w287_call0(addr: usize) -> u32 {
    let f = crate::platform::guest_fn!(addr, fn() -> u32);
    f()
}

/// Calls a one-argument function and keeps its `f1` result.
///
/// # Safety
/// `addr` must point to that ABI.
#[inline]
unsafe fn w287_f32_1(addr: usize, a: u32) -> f32 {
    let f = crate::platform::guest_fn!(addr, fn(u32) -> f32);
    f(a)
}

/// Calls `0x80154E50(this, near, far)` with two single-precision arguments.
///
/// # Safety
/// `this` must be a live scene object.
#[inline]
unsafe fn w287_zone(this: usize, near: f32, far: f32) -> u32 {
    let f = crate::platform::guest_fn!(W287_FUN_80154E50, fn(u32, f32, f32) -> u32);
    f(this as u32, near, far)
}

// ---------------------------------------------------------------------------
// 0x801546C0 - untabled gap creator: install `0x80327248`
// ---------------------------------------------------------------------------

/// Allocates and constructs the `0x90BE4`-byte game-scene object.
///
/// In plain English: allocate the scene, run the common base constructor,
/// install the `0x80327248` vtable at `+0x60`, then construct the four layout
/// sub-objects at `+0x90AAC`, `+0x90AC0`, `+0x90B60` and `+0x90BA4`.
///
/// # Original (untabled)
/// - Address: `0x801546C0`, 128 B (`0x801546C0..0x80154740`; the body starts
///   after two zero words at `0x801546B8`, and `0x80154740` is slot 0)
/// - Installation site: `lis r4,0x8032` / `addi r4,r4,0x7248` /
///   `stw r4,0x60(r31)` at `0x801546EC..0x801546F8`
/// - Class size `0x90BE4` is the immediate at `0x801546C8`/`0x801546D0`
///   (`lis r3,0x9` / `addi r3,r3,0xBE4`)
/// - Not in `functions.tsv`; no Ghidra export (the gap before slot 0)
/// - observed: the four constructor calls are
///   `0x800D85D0(+0x90AAC)`, `0x80089150(+0x90AC0)`,
///   `0x8007E180(+0x90B60)`, `0x800CD390(+0x90BA4)`; the vtable store happens
///   after the `0x80077060` base-constructor call.
///
/// # Arguments
/// None.
///
/// # Returns
/// The new object, or the null pointer when allocation failed.
///
/// # Safety
/// The SDA allocator behind [`W287_FUN_801628C0`] must be initialised.
///
/// # Confidence
/// high - the size, the constructor order, the four sub-object offsets and the
/// single vtable store are literal.
pub unsafe fn fn_801546c0() -> usize {
    let object = platform::call1(W287_FUN_801628C0, 0x90BE4) as usize;
    if object == 0 {
        return 0;
    }
    platform::call1(W287_FUN_80077060, object as u32);
    platform::write_u32(object + 0x60, W287_VTABLE_80327248 as u32);
    platform::call1(W287_FUN_800D85D0, (object + 0x90AAC) as u32);
    platform::call1(W287_FUN_80089150, (object + 0x90AC0) as u32);
    platform::call1(W287_FUN_8007E180, (object + 0x90B60) as u32);
    platform::call1(W287_FUN_800CD390, (object + 0x90BA4) as u32);
    object
}

// ---------------------------------------------------------------------------
// 0x80154D00 - slot 3: release
// ---------------------------------------------------------------------------

/// Releases the scene text block and the two scene sub-managers.
///
/// # Original (untabled)
/// - Address: `0x80154D00`, 72 B (`0x80154D00..0x80154D48`; two zero words
///   then the next body at `0x80154D50`)
/// - Table: slot 3 of `0x80327248`, i.e. vtable offset `+0x14`
/// - Reach: `vcall(object, 0x14)`
/// - Not in `functions.tsv`; no Ghidra export
/// - Prologue `stwu sp,-0x10`; epilogue `bclr` at `0x80154D44`
/// - observed: returns `1` unconditionally.
///
/// # Arguments
/// - `this`: the game-scene object.
///
/// # Returns
/// `1`.
///
/// # Safety
/// `this + 0x90AAC` must be the text block built by [`fn_801546c0`].
///
/// # Confidence
/// high - the three calls, the constant `1` and the return are literal.
pub unsafe fn fn_80154d00(this: usize) -> u32 {
    platform::call1(W287_FUN_800D8780, (this + 0x90AAC) as u32);
    platform::call1(W287_FUN_80077D80, this as u32);
    platform::call1(W287_FUN_80077020, this as u32);
    1
}

// ---------------------------------------------------------------------------
// 0x80154D50 - slot 9: draw / collection flush
// ---------------------------------------------------------------------------

/// Flushes the collection panes and the three per-player icon records.
///
/// In plain English: release the text block, refresh the tween pane, walk the
/// three icon pointers at `+0x90A40`, `+0x90A44` and `+0x90A48` (mark
/// `+0x36 = 1` and call their slot `+0x14`), flush the optional `+0x90A4C`
/// object, then reset the counter word and the active byte.
///
/// # Original (untabled)
/// - Address: `0x80154D50`, 244 B (`0x80154D50..0x80154E44`; three zero words
///   then the next body at `0x80154E50`)
/// - Table: slot 9 of `0x80327248`, i.e. vtable offset `+0x2C`
/// - Reach: `vcall(object, 0x2C)`
/// - Not in `functions.tsv`; no Ghidra export
/// - Prologue `stwu sp,-0x20`; epilogue `bclr` at `0x80154E40`
/// - observed: the loop bound is `3` and the record stride is `4`; the
///   `0x800CD2C0` result gates the extra flush but is not otherwise used.
///
/// # Arguments
/// - `this`: the game-scene object.
///
/// # Returns
/// `1`.
///
/// # Safety
/// The three `+0x90A40` words must be null or live interface objects, and
/// `+0x90BD8`/`+0x90BE2` must be writable.
///
/// # Confidence
/// high - the three-call prologue, the 3-record loop, the optional fourth
/// flush and the two resets are literal.
pub unsafe fn fn_80154d50(this: usize) -> u32 {
    platform::call1(W287_FUN_800CD600, (this + 0x90BA4) as u32);
    platform::call1(W287_FUN_800878D0, (this + 0x90A50) as u32);

    let mut index = 0u32;
    while index < 3 {
        let record = platform::read_u32(this + 0x90A40 + index as usize * 4) as usize;
        if record != 0 {
            platform::write_u8(record + 0x36, 1);
            let vtable = platform::read_u32(record) as usize;
            let entry = platform::read_u32(vtable + 0x14) as usize;
            platform::call1(entry, record as u32);
        }
        index += 1;
    }

    if w287_call0(W287_FUN_800CD2C0) != 0 {
        let extra = platform::read_u32(this + 0x90A4C) as usize;
        if extra != 0 {
            let vtable = platform::read_u32(extra) as usize;
            let entry = platform::read_u32(vtable + 0x14) as usize;
            platform::call1(entry, extra as u32);
        }
    }

    platform::call1(W287_FUN_80089B80, (this + 0x90AC0) as u32);
    platform::call1(W287_FUN_800CD610, (this + 0x90BA4) as u32);
    platform::write_u32(this + 0x90BD8, 0);
    platform::write_u8(this + 0x90BE2, 0);
    1
}



// ---------------------------------------------------------------------------
// 0x80154F60 - slot 6: scene update
// ---------------------------------------------------------------------------

/// Per-frame update of the game-scene HUD: five counters, the coin/time state
/// machine, the collected-record slide and the five-step layout animation.
///
/// This is the largest body of the table. It is kept as one function because
/// every phase shares the camera object [`W287_SDA_5880`], the player record
/// [`W287_SDA_57E8`] and the interpolated box `this + 0x8FE64..+0x8FEAC`.
/// The structure follows the binary phase by phase:
///
/// 1. five per-player counters at `(scene)+0x901E4` (1..9 increments, 10 wraps
///    to 0);
/// 2. camera rectangle refresh and the three zone tests (`2290..2300`,
///    `3790..3800`, `5420..5430`) that raise the coin state
///    `+0x90BE0` from 0 to 1/2;
/// 3. the `+0x909C8` timer transition that seeds the slide box;
/// 4. collection bookkeeping through the `+0x900FE..+0x90101` record words;
/// 5. the fade/`+0x90024` random-model block;
/// 6. the 128-record slide walk (`8 * 16` records of `0x44` bytes), then
///    the five-step animation `+0x90118`.
///
/// # Original (untabled)
/// - Address: `0x80154F60`, 6328 B (`0x80154F60..0x80156818`; two zero words
///   then the next body at `0x80156820`)
/// - Table: slot 6 of `0x80327248`, i.e. vtable offset `+0x20`
/// - Reach: `vcall(object, 0x20)`
/// - Not in `functions.tsv`; no Ghidra export
/// - Prologue `stwu sp,-0x1C0` / `bl 0x802DCD58` (`_savegpr_20`), epilogue
///   `bl 0x802DCDA4` (`_restgpr_20`) at `0x80156804`
/// - observed: the five-counter loop is unrolled five times but driven by
///   `mtctr 5` / `bdnz`; the 60-record walk is a nested `8 x 16` loop; the
///   three zone tests are the only callers of `0x80154E50` from this body.
///
/// # Arguments
/// - `this`: the game-scene object installed by [`fn_801546c0`].
///
/// # Returns
/// `1` on every path, including both early exits.
///
/// # Side effects
/// Writes the `+0x8FE64..+0x90120` block, the five `+0x901E4` counters, the
/// `+0x909C8..+0x90BE2` state words and the camera object; plays the sound
/// ids 187/188 through `0x80195380`; calls four layout helpers.
///
/// # Safety
/// `this` must be a live scene object, the SDA pointers at
/// [`W287_SDA_5880`], [`W287_SDA_54B8`] and [`W287_SDA_58B0`] must be readable,
/// and the `8 * 16` slide table at `(scene)+0x1078` must be valid.
///
/// # Confidence
/// high for the control flow, every call and every store; medium for the
/// semantic roles (`inferred:` from the layout names and the update order), and
/// the two bitmask writes at `0x801557FC..0x80155840` are preserved literally
/// because the compiler reuses `r0`/`r4` across the two helper calls.
pub unsafe fn fn_80154f60(this: usize) -> u32 {
    let camera = platform::read_u32(W287_SDA_5880) as usize;
    let info = platform::read_u32(W287_SDA_54B8) as usize;
    let model = platform::read_u8(this + 0x90025);
    let player = platform::call1(W287_FUN_8005F900, model as u32) as usize;
    let _current = platform::call1(W287_FUN_8005FD20, player as u32);
    let player_index = platform::read_u8(info + 0x120E) as usize;
    let rider = platform::read_u8(info + 0x120F) as u32;
    let mut record_base =
        platform::read_u32(W287_SDA_57E8) as usize + player_index * 0x3B0;
    if platform::read_u32(record_base + 0x2C) == 0 {
        record_base = 0;
    }

    if platform::call1(W287_FUN_800B3B50, 0xFFFF_FFFF) != 0 {
        return 1;
    }
    if player == 0 {
        return 1;
    }

    // Phase 1: the five small counters at scene + 0x901E4.
    let mut i = 0u32;
    while i < 5 {
        let scene = platform::read_u32(W287_SDA_58B0) as usize;
        let cell = scene + 0x901E4 + i as usize;
        let value = platform::read_u8(cell);
        if value != 0 && value < 99 {
            // observed: `v < 10 ? v + 1 : 0` (branchless subfc/subfe form).
            let next = if value < 10 { value + 1 } else { 0 };
            platform::write_u8(cell, next);
        }
        i += 1;
    }

    platform::call1(W287_FUN_80082180, camera as u32);
    platform::call1(W287_FUN_800821E0, camera as u32);
    platform::write_f32(this + 0x8FEA8, read_f32(camera + 0x38));
    platform::write_f32(this + 0x8FEAC, read_f32(camera + 0x3C));
    platform::write_f32(
        camera + 0x50,
        read_f32(camera + 0x38) + read_f32(W287_F_HALF) * read_f32(camera + 0x40),
    );
    platform::write_f32(
        camera + 0x54,
        read_f32(camera + 0x3C) - read_f32(W287_F_HALF) * read_f32(camera + 0x44),
    );

    // Phase 2: the three zone tests. They only run for player 0 in the
    // "23" scene with the byte trio (1, 23, 0).
    if platform::read_u8(info + 0x120C) == 1
        && platform::read_u8(info + 0x120D) == 23
        && platform::read_u8(info + 0x120E) == 0
    {
        let rect = [
            read_f32(player + 0x152C),
            read_f32(player + 0x1530),
            read_f32(player + 0x1534),
        ];
        let _ = rect;

        match read_i16(this + 0x90BE0) {
            0 => {
                let x = read_f32(camera + 0x38);
                if x >= read_f32(W287_F_2290) && x <= read_f32(W287_F_2300) {
                    let mask = w287_zone(this, read_f32(this + 0x90038), read_f32(W287_F_NEG350));
                    if mask != 0 {
                        let _ = platform::call3(
                            W287_FUN_80195380,
                            platform::read_u32(W287_SDA_51F8),
                            187,
                            mask,
                        );
                        write_i16(this + 0x90BE0, read_i16(this + 0x90BE0) + 1);
                    } else {
                        if platform::read_u8(this + 0x90BE2) == 0 {
                            let _ = platform::call3(
                                W287_FUN_80195380,
                                platform::read_u32(W287_SDA_51F8),
                                188,
                                1,
                            );
                            platform::write_u8(this + 0x90BE2, 1);
                        }
                        write_i16(this + 0x909C8, 1);
                    }
                } else {
                    platform::write_u8(this + 0x90BE2, 0);
                }
            }
            1 => {
                let x = read_f32(camera + 0x38);
                if x >= read_f32(W287_F_3790) && x <= read_f32(W287_F_3800) {
                    let mask = w287_zone(this, read_f32(W287_F_NEG440), read_f32(this + 0x9003C));
                    if mask != 0 {
                        let _ = platform::call3(
                            W287_FUN_80195380,
                            platform::read_u32(W287_SDA_51F8),
                            187,
                            mask,
                        );
                        write_i16(this + 0x90BE0, read_i16(this + 0x90BE0) + 1);
                    } else {
                        if platform::read_u8(this + 0x90BE2) == 0 {
                            let _ = platform::call3(
                                W287_FUN_80195380,
                                platform::read_u32(W287_SDA_51F8),
                                188,
                                1,
                            );
                            platform::write_u8(this + 0x90BE2, 1);
                        }
                        write_i16(this + 0x909C8, 2);
                    }
                } else {
                    platform::write_u8(this + 0x90BE2, 0);
                }
            }
            2 => {
                let x = read_f32(camera + 0x38);
                if x >= read_f32(W287_F_5420) && x <= read_f32(W287_F_5430) {
                    let mask = w287_zone(this, read_f32(W287_F_NEG350), read_f32(W287_F_NEG420));
                    if mask != 0 {
                        let _ = platform::call3(
                            W287_FUN_80195380,
                            platform::read_u32(W287_SDA_51F8),
                            187,
                            mask,
                        );
                        write_i16(this + 0x90BE0, read_i16(this + 0x90BE0) + 1);
                    } else {
                        if platform::read_u8(this + 0x90BE2) == 0 {
                            let _ = platform::call3(
                                W287_FUN_80195380,
                                platform::read_u32(W287_SDA_51F8),
                                188,
                                1,
                            );
                            platform::write_u8(this + 0x90BE2, 1);
                        }
                        write_i16(this + 0x909C8, 3);
                    }
                } else {
                    platform::write_u8(this + 0x90BE2, 0);
                }
            }
            _ => write_i16(this + 0x90BE0, 0),
        }

        // Phase 3a: keep +0x909C8 clear while the camera is inside the box
        // enlarged by 50.
        let x = read_f32(camera + 0x38);
        let limit = w287_f32_1(W287_FUN_800789A0, this as u32);
        if !(x < limit) {
            let x = read_f32(camera + 0x38);
            let limit = w287_f32_1(W287_FUN_800789A0, this as u32);
            if !(x > limit + read_f32(W287_F_50)) {
                write_i16(this + 0x909C8, 0);
            }
        }

        // Phase 3b: seed the slide box from the four +0x8FE64 records.
        let (a, b) = match read_i16(this + 0x909C8) {
            1 => (read_f32(W287_F_989), read_f32(W287_F_2605)),
            2 => (read_f32(W287_F_2519), read_f32(W287_F_4119)),
            3 => (read_f32(W287_F_4031), read_f32(W287_F_5664)),
            _ => (read_f32(W287_F_352), read_f32(W287_F_7280)),
        };
        platform::write_u32(W287_SDA_5478, 2);
        platform::write_f32(this + 0x8FE64, a);
        platform::write_f32(this + 0x8FE68, b);
        platform::write_f32(this + 0x90030, w287_f32_1(W287_FUN_800789A0, this as u32));
        platform::write_f32(this + 0x90034, w287_f32_1(W287_FUN_80078B40, this as u32));
        let first = w287_f32_1(W287_FUN_800789A0, this as u32);
        let second = w287_f32_1(W287_FUN_80078B40, this as u32);
        platform::write_f32(this + 0x8FEA0, second - first);
    }

    // Phase 4: collection bookkeeping for the live player object.
    if player != 0 {
        let rider_kind = platform::read_u8(player + 0x349) as u32;
        if read_f32(this + 0x90098) > read_f32(W287_F_ZERO) {
            platform::write_u8(
                this + 0x900FE,
                platform::call2(W287_FUN_8008E530, record_base as u32, rider_kind) as u8,
            );
            platform::write_u8(
                this + 0x900FF,
                platform::call2(W287_FUN_8008E560, record_base as u32, rider_kind) as u8,
            );
            platform::write_u8(
                this + 0x90100,
                platform::call2(W287_FUN_8008E590, record_base as u32, rider_kind) as u8,
            );
            let scene = platform::read_u32(W287_SDA_58B0) as usize;
            platform::write_f32(this + 0x90098, w287_f32_1(W287_FUN_80078EB0, scene as u32));

            let code = platform::call1(W287_FUN_80078780, rider_kind);
            if code == 15 {
                platform::write_f32(this + 0x9001C, read_f32(W287_F_NEG999999));
            } else {
                // observed: one 32-bit unsigned -> double conversion through
                // the 2^52 magic, then `16.0f * n`.
                let scaled = code as f32 * read_f32(W287_F_16);
                platform::write_f32(this + 0x9001C, scaled);
            }

            if platform::read_u8(this + 0x900FE) == 5 {
                platform::write_u8(this + 0x90021, 1);
                let mut index = 0u32;
                let count = platform::call1(W287_FUN_80078800, rider_kind);
                while index < count {
                    let record =
                        platform::call2(W287_FUN_80078830, rider_kind, index) as usize;
                    if record != 0 {
                        let slot = platform::read_u8(record + 0x12).wrapping_sub(1) as u32;
                        let _ = platform::call3(W287_FUN_802DD1EC, 0, 1, slot);
                        if platform::read_u32(W287_SDA_5608) != 0 {
                            platform::write_u8(this + 0x90020, index as u8);
                            platform::write_u8(this + 0x90101, platform::read_u8(record + 0x0C));
                            platform::write_u8(this + 0x900FE, platform::read_u8(record + 0x0D));
                            platform::write_u8(this + 0x900FF, platform::read_u8(record + 0x0E));
                            platform::write_u8(this + 0x90100, platform::read_u8(record + 0x0F));
                            break;
                        }
                    }
                    index += 1;
                }
            }
        }

        let current = platform::call2(
            W287_FUN_8008E4D0,
            record_base as u32,
            rider_kind,
        ) as u8;
        platform::write_u8(
            this + 0x90101,
            platform::call2(W287_FUN_8008E500, record_base as u32, current as u32) as u8,
        );

        if platform::read_u8(this + 0x90021) != 0 {
            let wanted = platform::read_u8(this + 0x90020) as u32;
            let active = platform::call2(W287_FUN_80078830, rider_kind, wanted) as usize;
            if active != 0 {
                let mut index = 0u32;
                let count = platform::call1(W287_FUN_80078800, rider_kind);
                let mut switch_to = u32::MAX;
                while index < count {
                    if index != platform::read_u8(this + 0x90020) as u32 {
                        let record =
                            platform::call2(W287_FUN_80078830, rider_kind, index) as usize;
                        if record != 0 {
                            let slot = platform::read_u8(record + 0x12).wrapping_sub(1) as u32;
                            let _ = platform::call3(W287_FUN_802DD1EC, 0, 1, slot);
                            let word0 = platform::read_u32(W287_SDA_5608);
                            let word1 = platform::read_u32(W287_SDA_5608 + 4);
                            let and0 = word0 & word0;
                            let and1 = and0 & word1;
                            if (word0 | word0) != 0 {
                                // observed: both words become the old word0.
                                platform::write_u32(W287_SDA_5608 + 4, word0);
                                platform::write_u32(W287_SDA_5608, word0);
                                let selected = platform::call3(W287_FUN_802DD1EC, 0, 1, slot);
                                let word0b = platform::read_u32(W287_SDA_5608);
                                platform::write_u32(W287_SDA_5608 + 4, !and1);
                                platform::write_u32(W287_SDA_5608, word0b & !selected);
                                platform::write_u8(this + 0x90020, index as u8);
                                platform::write_u8(
                                    this + 0x90101,
                                    platform::read_u8(record + 0x0C),
                                );
                                platform::write_u8(
                                    this + 0x900FE,
                                    platform::read_u8(record + 0x0D),
                                );
                                platform::write_u8(
                                    this + 0x900FF,
                                    platform::read_u8(record + 0x0E),
                                );
                                platform::write_u8(
                                    this + 0x90100,
                                    platform::read_u8(record + 0x0F),
                                );
                                switch_to = index;
                                break;
                            }
                        }
                    }
                    index += 1;
                }
                let _ = switch_to;
            }
        }
    }

    // Phase 5: fade and the random-model refresh.
    let fade = read_f32(this + 0x8FE9C);
    platform::write_f32(this + 0x90014, read_f32(this + 0x9000C));
    if fade < read_f32(W287_F_ONE) {
        let present = w287_call0(W287_FUN_8005FFB0);
        let one = present == 1;
        if !one || platform::read_u8(this + 0x900C6) != 0 {
            let pick = w287_call0(W287_FUN_8005FC70) as u8;
            let table = W287_TBL_802F5908;
            platform::write_u8(
                this + 0x90025,
                platform::read_u8(table + pick as usize),
            );
            platform::write_u8(this + 0x90024, 0);
        } else {
            platform::write_u8(this + 0x90024, 1);
        }
    }

    let mode = platform::read_u32(W287_SDA_56C0) as usize;
    if platform::read_u8(mode + 0x18) == 0 {
        if platform::read_u8(this + 0x90024) == 0 {
            platform::write_f32(this + 0x8FE9C, read_f32(W287_F_ZERO));
            platform::call1(W287_FUN_80079710, this as u32);
            let pick = w287_call0(W287_FUN_8005FC70) as u8;
            platform::write_u8(this + 0x90025, pick);
            let object = platform::call1(W287_FUN_8005F900, pick as u32) as usize;
            let mut position = crate::platform::GuestLocal::new( [
                read_f32(object + 0x152C),
                read_f32(object + 0x1530),
                read_f32(object + 0x1534),
            ]);
            let _ = platform::call3(
                W287_FUN_8007A6C0,
                this as u32,
                position.as_mut_ptr() as u32,
                0,
            );
            if platform::read_u8(this + 0x900C6) != 0
                && platform::read_u8(this + 0x90118) == 0
            {
                platform::call1(W287_FUN_80079E80, this as u32);
            }
            if read_f32(this + 0x8FE9C) < read_f32(W287_F_ONE) {
                platform::write_f32(this + 0x90BDC, read_f32(W287_F_ZERO));
            }
        } else {
            platform::write_f32(this + 0x8FE9C, read_f32(W287_F_ONE));
            platform::call2(W287_FUN_8007AB70, this as u32, 0);
            if read_f32(this + 0x8FE9C) < read_f32(W287_F_ONE) {
                platform::write_f32(this + 0x90BDC, read_f32(W287_F_ONE));
            }
        }
    }

    // Phase 6a: early-out and the interpolated slide box.
    let scene = platform::read_u32(W287_SDA_58B0) as usize;
    if platform::read_u8(scene + 0x909CA) != 0 {
        return 1;
    }

    let mut base_x = read_f32(this + 0x8FE8C) // f5
        + read_f32(this + 0x8FE9C) * (read_f32(this + 0x8FE94) - read_f32(this + 0x8FE8C));
    let mut base_y = read_f32(this + 0x8FE88) // f4
        + read_f32(this + 0x8FE9C) * (read_f32(this + 0x8FE90) - read_f32(this + 0x8FE88));
    let dx = read_f32(this + 0x8FE78)
        + read_f32(this + 0x8FE9C) * (read_f32(this + 0x8FE80) - read_f32(this + 0x8FE78));
    let dy = read_f32(this + 0x8FE7C)
        + read_f32(this + 0x8FE9C) * (read_f32(this + 0x8FE84) - read_f32(this + 0x8FE7C));
    let ease = read_f32(this + 0x8FE9C);
    if ease <= read_f32(W287_F_ZERO) {
        platform::write_f32(this + 0x8FE90, read_f32(this + 0x8FE88));
        platform::write_f32(this + 0x8FE94, read_f32(this + 0x8FE8C));
        platform::write_f32(this + 0x8FE80, read_f32(this + 0x8FE78));
        platform::write_f32(this + 0x8FE84, read_f32(this + 0x8FE7C));
    }

    // Phase 6b: twenty records, then the two walker helpers.
    let row_base = this + 0x89078 + rider as usize * 0x190;
    let mut changed = 0u32;
    let mut index = 0u32;
    while index < 20 {
        let record = row_base + index as usize * 20;
        if platform::call2(W287_FUN_80156C30, this as u32, record as u32) == 1 {
            platform::write_u8(
                this + 0x90114,
                platform::read_u8(record + 0x11).wrapping_add(1),
            );
            changed = 1;
            break;
        }
        index += 1;
    }
    if platform::call1(W287_FUN_80156D70, this as u32) == 1 {
        platform::write_u8(this + 0x90114, 4);
        changed = 1;
    }

    if platform::read_u8(info + 0x120E) == 0
        && platform::read_u32(W287_SDA_5478) == 1
    {
        let record = platform::read_u32(record_base + 0x0C) as usize;
        if platform::read_u8(info + 0x1211) == platform::read_u8(record + 0x10) {
            let state = platform::read_u8(this + 0x90114);
            let not_ten = state.wrapping_sub(10) >= 5;
            let not_seventeen = state.wrapping_sub(17) >= 6;
            if not_ten && not_seventeen {
                let script = platform::read_u8(info + 0x120C);
                let scene_byte = platform::read_u8(0x8031_5B9D);
                let skip_a = script == 2 && platform::read_u8(info + 0x120D) == 4;
                let skip_b = script == 0 && platform::read_u8(info + 0x120D) == 41;
                let skip_c = script == 7
                    && platform::read_u8(info + 0x120D) == 23
                    && platform::read_u8(info + 0x120E) == 3;
                let small = scene_byte.wrapping_add(0xE0) < 2;
                if !skip_a
                    && !skip_b
                    && !skip_c
                    && !small
                    && platform::read_u32(W287_SDA_5480) < 90
                {
                    let gate = platform::read_u32(W287_SDA_5704) as usize;
                    if platform::read_u8(this + 0x900C6) != 0 {
                        platform::write_u8(this + 0x90114, 0);
                    } else if platform::read_u8(W287_SDA_5464) != 0
                        && platform::read_u32(gate + 0xAF4) <= 0
                    {
                        platform::write_u8(this + 0x90114, 8);
                        changed = 1;
                        platform::write_f32(this + 0x90110, read_f32(W287_F_ONE));
                    } else if state == 8 && read_f32(this + 0x90110) > read_f32(W287_F_ZERO)
                    {
                        platform::write_u8(this + 0x90114, 0);
                    }
                }
            }
        }
    }

    // Phase 6c: the layout animation, five states.
    let mode_object = platform::read_u32(W287_SDA_59EC) as usize;
    let mut overlay = crate::platform::GuestLocal::new( read_f32(this + 0x90110));
    let mut anim = platform::read_u8(this + 0x90118) as u32;
    let cur_y = read_f32(this + 0x9003C);
    let obj_y = read_f32(mode_object + 0x38);
    let obj_x = read_f32(mode_object + 0x34);
    let f25 = dy + read_f32(this + 0x9003C);
    let target_x = read_f32(mode_object + 0x30);
    let stored_x = read_f32(this + 0x90038);
    let _ = (cur_y, obj_y, obj_x, target_x, stored_x, f25);

    match anim {
        0 => {
            if (platform::read_u32(mode_object + 0x10) & 1) != 0 {
                platform::write_f32(this + 0x90120, base_x - dy);
                platform::write_u8(this + 0x90117, 1);
                platform::write_f32(
                    this + 0x9011C,
                    base_y + read_f32(W287_F_HALF) * dx,
                );
                platform::write_u8(this + 0x90114, 6);
                anim += 1;
                changed = 1;
            }
        }
        1 => {
            let mut out_a = crate::platform::GuestLocal::new( read_f32(this + 0x9011C));
            let mut out_b = crate::platform::GuestLocal::new( read_f32(this + 0x90120));
            let edge = base_y + read_f32(W287_F_HALF) * dx;
            if !(cur_y < edge) {
                w287_step(
                    (out_a.as_mut_ptr() as *mut f32) as usize,
                    cur_y,
                    read_f32(W287_F_01),
                    read_f32(W287_F_5),
                    read_f32(W287_F_ONE),
                );
            }
            w287_step(
                (out_b.as_mut_ptr() as *mut f32) as usize,
                f25 - dy,
                read_f32(W287_F_01),
                read_f32(W287_F_TWO),
                read_f32(W287_F_ONE),
            );
            platform::write_f32(this + 0x9011C, *out_a);
            platform::write_f32(this + 0x90120, *out_b);
            platform::write_u8(this + 0x90114, 6);
            changed = 1;
            if (platform::read_u32(mode_object + 0x10) & 2) != 0 {
                platform::write_u32(W287_SDA_5368, 40);
                anim += 1;
            }
        }
        2 => {
            if base_x > f25 {
                platform::write_u8(this + 0x90114, 6);
                changed = 1;
            }
            let mut out_a = crate::platform::GuestLocal::new( read_f32(this + 0x9011C));
            let mut out_b = crate::platform::GuestLocal::new( read_f32(this + 0x90120));
            if platform::read_u32(W287_SDA_5368) < 15 {
                let edge = base_y + read_f32(W287_F_HALF) * dx;
                if !(target_x < edge) {
                    w287_step(
                        (out_a.as_mut_ptr() as *mut f32) as usize,
                        target_x,
                        read_f32(W287_F_01),
                        read_f32(W287_F_5),
                        read_f32(W287_F_ONE),
                    );
                }
            }
            w287_step(
                (out_b.as_mut_ptr() as *mut f32) as usize,
                f25 - dy,
                read_f32(W287_F_01),
                read_f32(W287_F_TWO),
                read_f32(W287_F_ONE),
            );
            if platform::read_u32(W287_SDA_5368) != 0 {
                let v = platform::read_u32(W287_SDA_5368);
                platform::write_u32(W287_SDA_5368, v - 1);
            }
            platform::write_f32(this + 0x9011C, *out_a);
            platform::write_f32(this + 0x90120, *out_b);
            platform::write_u8(this + 0x90114, 5);
            if (platform::read_u32(mode_object + 0x10) & 4) != 0 {
                platform::write_u8(this + 0x90114, 7);
                anim += 1;
                *overlay = read_f32(W287_F_ZERO);
                changed = 2;
            }
        }
        3 => {
            let mut out_a = crate::platform::GuestLocal::new( read_f32(this + 0x9011C));
            let mut out_b = crate::platform::GuestLocal::new( read_f32(this + 0x90120));
            w287_step(
                (out_a.as_mut_ptr() as *mut f32) as usize,
                read_f32(this + 0x9003C),
                read_f32(W287_F_01),
                read_f32(W287_F_5),
                read_f32(W287_F_ONE),
            );
            let delta = (f25 - dy) - obj_x;
            if delta > read_f32(W287_F_NEG40) {
                let step = read_f32(W287_F_21) * (read_f32(W287_F_ONE) - *overlay);
                w287_step(
                    (out_b.as_mut_ptr() as *mut f32) as usize,
                    obj_x + read_f32(W287_F_NEG57) + step,
                    read_f32(W287_F_01),
                    read_f32(W287_F_TWO),
                    read_f32(W287_F_ONE),
                );
            } else {
                let step = read_f32(W287_F_5) * (read_f32(W287_F_ONE) - *overlay);
                w287_step(
                    (out_b.as_mut_ptr() as *mut f32) as usize,
                    obj_x + read_f32(W287_F_NEG57) + step,
                    read_f32(W287_F_01),
                    read_f32(W287_F_TWO),
                    read_f32(W287_F_ONE),
                );
            }
            platform::write_f32(this + 0x9011C, *out_a);
            platform::write_f32(this + 0x90120, *out_b);
            platform::write_u8(this + 0x90114, 5);
            changed = 1;
            if (platform::read_u32(mode_object + 0x10) & 8) != 0 {
                platform::write_u8(this + 0x90114, 7);
                anim += 1;
                *overlay = read_f32(W287_F_ZERO);
                changed = 2;
            }
        }
        4 => {
            platform::write_u8(this + 0x90114, 7);
            changed = 1;
            let mut out_b = crate::platform::GuestLocal::new( read_f32(this + 0x90120));
            let delta = (f25 - dy) - obj_x;
            if delta > read_f32(W287_F_NEG40) {
                let step = read_f32(W287_F_24) * *overlay;
                w287_step(
                    (out_b.as_mut_ptr() as *mut f32) as usize,
                    obj_x + read_f32(W287_F_NEG57) + step,
                    read_f32(W287_F_01),
                    read_f32(W287_F_TWO),
                    read_f32(W287_F_ONE),
                );
            } else {
                let step = read_f32(W287_F_8) * *overlay;
                w287_step(
                    (out_b.as_mut_ptr() as *mut f32) as usize,
                    obj_x + read_f32(W287_F_NEG57) + step,
                    read_f32(W287_F_01),
                    read_f32(W287_F_TWO),
                    read_f32(W287_F_ONE),
                );
            }
            platform::write_f32(this + 0x90120, *out_b);
        }
        _ => {}
    }

    // Phase 6d: record the animation index, blend the overlay and keep the
    // +0x90114 state coherent.
    let step = if anim < 2 {
        read_f32(W287_F_002)
    } else if anim == 3 {
        read_f32(W287_F_005)
    } else {
        read_f32(W287_F_0025)
    };
    platform::write_u8(this + 0x90118, anim as u8);
    let state = platform::read_u8(this + 0x90114);
    if state.wrapping_sub(10) >= 5 && state.wrapping_sub(17) >= 6 {
        let target = if changed == 1 {
            read_f32(W287_F_ONE)
        } else {
            read_f32(W287_F_ZERO)
        };
        w287_step(
            (overlay.as_mut_ptr() as *mut f32) as usize,
            target,
            read_f32(W287_F_HALF),
            step,
            read_f32(W287_F_6),
        );
        if platform::read_u8(this + 0x90118) == 0
            && *overlay <= read_f32(W287_F_ZERO)
        {
            platform::write_u8(this + 0x90114, 0);
        }
    }
    platform::write_f32(this + 0x90110, *overlay);

    // Phase 6e: the 8 x 16 slide walk.
    let player_row = rider as usize * 0x2200;
    let mut left_hit_x = base_x;
    let mut right_hit_x = base_y;
    let mut left_bound_x = read_f32(this + 0x8FE6C);
    let mut right_bound_x = read_f32(this + 0x8FE70);
    let mut left_hit_y = base_y;
    let mut right_hit_y = base_y;
    let mut left_bound_y = read_f32(this + 0x8FE64);
    let mut right_bound_y = read_f32(this + 0x8FE68);
    let mut left_seen = 0u32;
    let mut right_seen = 0u32;
    let mut left2_seen = 0u32;
    let mut right2_seen = 0u32;
    let mut row = 0u32;
    while row < 8 {
        let mut col = 0u32;
        while col < 16 {
            let cell = 0x1078 + player_row + row as usize * 0x440 + col as usize * 0x44;
            let record = platform::read_u32(scene + cell) as usize + col as usize * 0x44;
            if read_f32(this + 0x90110) != read_f32(W287_F_ZERO) {
                let mut out_a = crate::platform::GuestLocal::<f32>::new( 0.0f32);
                let mut out_b = crate::platform::GuestLocal::<f32>::new( 0.0f32);
                if platform::call4(
                    W287_FUN_80156930,
                    this as u32,
                    record as u32,
                    (out_a.as_mut_ptr() as *mut f32) as u32,
                    (out_b.as_mut_ptr() as *mut f32) as u32,
                ) == 1
                {
                    let flags = platform::read_u16(record + 0x40);
                    if (flags & 0x10) != 0 {
                        if left_seen == 0 {
                            let hit = -read_f32(record + 0x10);
                            left_hit_x = hit;
                            let probe = (flags & 0x100) == 0 || *out_a > hit;
                            if probe && base_x < hit {
                                left_bound_x = -read_f32(record + 0x08);
                                left_seen = 1;
                            }
                        }
                    } else if right_seen == 0 {
                        let raw = -read_f32(record + 0x14);
                        let hit = raw + dy;
                        right_hit_x = hit;
                        let probe = (flags & 0x200) == 0 || *out_b < raw;
                        if probe && base_x > hit {
                            right_bound_x = -read_f32(record + 0x0C);
                            right_seen = 1;
                        }
                    }
                }
                if read_f32(record + 0x18) != read_f32(W287_F_ZERO) {
                    let mut out_c = crate::platform::GuestLocal::<f32>::new( 0.0f32);
                    let mut out_d = crate::platform::GuestLocal::<f32>::new( 0.0f32);
                    if platform::call4(
                        W287_FUN_80156AB0,
                        this as u32,
                        record as u32,
                        (out_c.as_mut_ptr() as *mut f32) as u32,
                        (out_d.as_mut_ptr() as *mut f32) as u32,
                    ) == 1
                    {
                        let flags = platform::read_u16(record + 0x40);
                        if (flags & 0x40) != 0 {
                            if left2_seen == 0 {
                                let hit = read_f32(record + 0x28);
                                left_hit_y = hit;
                                let probe = (flags & 0x100) == 0 || *out_c < hit;
                                if probe && base_y > hit {
                                    left_bound_y = read_f32(record + 0x20);
                                    left2_seen = 1;
                                }
                            }
                        } else if right2_seen == 0 {
                            let raw = read_f32(record + 0x2C);
                            let hit = raw - dx - read_f32(W287_F_32);
                            right_hit_y = hit;
                            let probe = (flags & 0x200) == 0 || *out_d > raw;
                            if probe && base_y < hit {
                                right_bound_y = read_f32(record + 0x24);
                                right2_seen = 1;
                            }
                        }
                    }
                }
            }
            col += 1;
        }
        row += 1;
    }

    // Phase 6f: the X track (with the frame-counted easing).
    let mut x_value = crate::platform::GuestLocal::new( if platform::read_u8(this + 0x90024) == 0 {
        read_f32(this + 0x90048)
    } else {
        read_f32(this + 0x90058)
    });
    let frame = platform::read_u32(this + 0x90BD8);
    let cam_z = read_f32(camera + 0x3C);
    if *x_value >= left_bound_x && left_hit_x >= cam_z {
        *x_value = left_bound_x;
    } else {
        if *x_value >= left_bound_x {
            // observed: the >= branch only clamps, it still eases.
        }
        if cam_z >= left_bound_x && *x_value - read_f32(W287_F_32) >= cam_z {
            *x_value = read_f32(W287_F_32) + cam_z;
        }
        if frame >= 10 {
            w287_step(
                (x_value.as_mut_ptr() as *mut f32) as usize,
                left_bound_x,
                read_f32(W287_F_01),
                read_f32(W287_F_6),
                read_f32(W287_F_ONE),
            );
        } else {
            *x_value = left_bound_x;
        }
    }
    if platform::read_u8(this + 0x90024) == 0 {
        platform::write_f32(this + 0x90048, *x_value);
    } else {
        platform::write_f32(this + 0x90058, *x_value);
    }
    let x0 = read_f32(this + 0x90048);
    let x1 = read_f32(this + 0x90058);
    platform::write_f32(this + 0x90038, x0 + ease * (x1 - x0));

    // Phase 6g: the Y track.
    let mut y_value = crate::platform::GuestLocal::new( if platform::read_u8(this + 0x90024) == 0 {
        read_f32(this + 0x9004C)
    } else {
        read_f32(this + 0x9005C)
    });
    if *y_value <= right_bound_x && right_hit_x <= cam_z {
        *y_value = right_bound_x;
    } else {
        if cam_z > right_bound_x && *y_value + dy + read_f32(W287_F_32) > cam_z {
            *y_value = cam_z - dy - read_f32(W287_F_32);
        }
        if frame >= 10 {
            w287_step(
                (y_value.as_mut_ptr() as *mut f32) as usize,
                right_bound_x,
                read_f32(W287_F_01),
                read_f32(W287_F_6),
                read_f32(W287_F_ONE),
            );
        } else {
            *y_value = right_bound_x;
        }
    }
    if platform::read_u8(this + 0x90024) == 0 {
        platform::write_f32(this + 0x9004C, *y_value);
    } else {
        platform::write_f32(this + 0x9005C, *y_value);
    }
    let y0 = read_f32(this + 0x9004C);
    let y1 = read_f32(this + 0x9005C);
    platform::write_f32(this + 0x9003C, y0 + ease * (y1 - y0));

    // Phase 6h: the left-edge track starts from the two translated limit getters.
    let mut edge_value = crate::platform::GuestLocal::new( if platform::read_u8(this + 0x90024) == 0 {
        w287_f32_1(W287_FUN_80078CE0, this as u32)
    } else {
        w287_f32_1(W287_FUN_80078CF0, this as u32)
    });
    if *edge_value > left_bound_y && left_hit_y >= cam_z {
        *edge_value = left_bound_y;
    } else {
        if cam_z >= left_bound_y && *edge_value - read_f32(W287_F_32) >= cam_z {
            *edge_value = read_f32(W287_F_32) + cam_z;
        }
        if frame >= 10 {
            w287_step(
                (edge_value.as_mut_ptr() as *mut f32) as usize,
                left_bound_y,
                read_f32(W287_F_01),
                read_f32(W287_F_6),
                read_f32(W287_F_ONE),
            );
        } else {
            *edge_value = left_bound_y;
        }
    }
    if platform::read_u8(this + 0x90024) == 0 {
        platform::write_f32(this + 0x90040, *edge_value);
    } else {
        platform::write_f32(this + 0x90050, *edge_value);
    }
    let low = w287_f32_1(W287_FUN_80078CE0, this as u32);
    let high = w287_f32_1(W287_FUN_80078CF0, this as u32);
    platform::write_f32(this + 0x90030, low + ease * (high - low));

    // Phase 6i: the lower-edge track.
    let mut lower = crate::platform::GuestLocal::new( if platform::read_u8(this + 0x90024) == 0 {
        read_f32(this + 0x90044)
    } else {
        read_f32(this + 0x90054)
    });
    if *lower >= right_bound_y || right_hit_y <= cam_z {
        if frame >= 10 {
            w287_step(
                (lower.as_mut_ptr() as *mut f32) as usize,
                right_bound_y,
                read_f32(W287_F_01),
                read_f32(W287_F_6),
                read_f32(W287_F_ONE),
            );
        } else {
            *lower = right_bound_y;
        }
    } else {
        *lower = right_bound_y;
    }
    if platform::read_u8(this + 0x90024) == 0 {
        platform::write_f32(this + 0x90044, *lower);
    } else {
        platform::write_f32(this + 0x90054, *lower);
    }
    let l0 = read_f32(this + 0x90044);
    let l1 = read_f32(this + 0x90054);
    platform::write_f32(this + 0x90034, l0 + ease * (l1 - l0));

    // Phase 6j: clamp the camera box and publish the frame transform.
    if platform::read_u8(mode + 0x18) == 0 {
        let limit_y = w287_f32_1(W287_FUN_80078A70, this as u32);
        let span = w287_f32_1(W287_FUN_80078C10, this as u32) - dx;
        let x = read_f32(this + 0x9003C);
        let y = read_f32(this + 0x90038);
        let shifted_y = dy + x;
        if platform::read_u32(W287_SDA_5478) != 2 {
            if base_y <= limit_y {
                base_y = limit_y;
            } else if base_y >= span {
                base_y = span;
            }
            if base_x > shifted_y {
                base_x = shifted_y;
            } else if base_x >= y {
                base_x = y;
            }
        }
    }
    platform::write_f32(camera + 0x60, base_y);
    platform::write_f32(camera + 0x64, base_x);
    if read_f32(camera + 0x58) != read_f32(W287_F_SENTINEL) {
        base_y = read_f32(camera + 0x58);
    }
    if read_f32(camera + 0x5C) != read_f32(W287_F_SENTINEL) {
        base_x = read_f32(camera + 0x5C);
    }
    platform::write_f32(camera + 0x38, base_y + read_f32(camera + 0x78));
    platform::write_f32(camera + 0x3C, base_x + read_f32(camera + 0x7C));
    platform::write_u32(this + 0x90BD4, _current);
    platform::write_f32(camera + 0x40, dx);
    platform::write_f32(camera + 0x44, dy);
    platform::write_f32(camera + 0x48, read_f32(camera + 0x38) + read_f32(W287_F_HALF) * dx);
    platform::write_f32(camera + 0x4C, read_f32(camera + 0x3C) - read_f32(W287_F_HALF) * dy);

    // Phase 6k: the layout refresh trio.
    if (platform::read_u8(W287_SDA_5986) & 0x0F) != 0 {
        platform::call1(W287_FUN_80087890, (this + 0x90A50) as u32);
        platform::call1(W287_FUN_800D8670, (this + 0x90AAC) as u32);
        platform::call1(W287_FUN_80078300, this as u32);
    }
    platform::call1(W287_FUN_8007E4E0, (this + 0x90B60) as u32);
    platform::call1(W287_FUN_80089B60, (this + 0x90AC0) as u32);
    let counter = platform::read_u32(this + 0x90BD8);
    if counter <= 100 {
        platform::write_u32(this + 0x90BD8, counter + 1);
    }
    1
}

